L21_1 = "Regina MacCready l\195\160 \196\145\198\161n v\225\187\139 l\195\173nh h\225\187\151 tr\225\187\163 chuy\195\170n tri\225\187\135u h\225\187\147i t\198\176\225\187\157ng b\196\131ng v\195\160 l\195\160m suy y\225\186\191u kh\225\186\163 n\196\131ng t\225\186\165n c\195\180ng c\225\187\167a qu\195\162n \196\145\225\187\139ch. N\196\131ng l\198\176\225\187\163ng b\196\131ng c\225\187\167a c\195\180 \196\145\225\186\183c bi\225\187\135t hi\225\187\135u qu\225\186\163 khi \196\145\225\187\145i \196\145\225\186\167u L\195\173nh Thi\225\186\191t Gi\195\161p.\n\nChi\225\186\191c \196\144\225\187\147ng H\225\187\147 \196\145\195\163 \196\145\198\176\225\187\163c truy\225\187\129n l\225\186\161i trong gia t\225\187\153c c\225\187\167a c\195\180 \196\145\198\176\225\187\163c t\225\187\145i \198\176u h\195\179a \196\145\225\187\131 s\225\187\173 d\225\187\165ng s\225\187\169c m\225\186\161nh c\225\187\167a b\196\131ng. T\195\185y theo ng\198\176\225\187\157i s\225\187\173 d\225\187\165ng, n\195\179 kh\195\180ng ch\225\187\137 c\195\179 th\225\187\131 t\225\186\161o ra b\196\131ng m\195\160 c\195\178n c\195\179 th\225\187\131 g\195\162y ra hi\225\187\135n t\198\176\225\187\163ng th\225\187\157i ti\225\186\191t to\195\160n qu\225\187\145c. V\225\186\165n \196\145\225\187\129 l\195\160 ch\225\187\167 nh\195\162n hi\225\187\135n t\225\186\161i c\225\187\167a n\195\179, Regina v\225\186\171n ch\198\176a ho\195\160n to\195\160n ki\225\187\131m so\195\161t \196\145\198\176\225\187\163c s\225\187\169c m\225\186\161nh c\225\187\167a n\195\179. C\195\180 ph\225\186\163i duy tr\195\172 nh\225\186\173n th\225\187\169c s\225\187\169c m\225\186\161nh c\225\187\167a b\225\186\163n th\195\162n, n\225\186\191u kh\195\180ng, c\195\180 s\225\186\189 b\225\186\175t \196\145\225\186\167u \196\145\195\179ng b\196\131ng ngay khi l\198\161i l\225\187\143ng ph\195\178ng b\225\187\139. \196\144\225\187\145i v\225\187\155i c\195\180, kh\195\180ng c\195\179 m\195\179n qu\195\160 n\195\160o t\225\187\145t h\198\161n m\225\187\153t chi\225\186\191c ch\196\131n b\195\180ng v\195\160 c\195\160 ph\195\170.\n\nGia t\225\187\153c c\195\180 \196\145\195\163 s\225\186\163n sinh ra nhi\225\187\129u v\225\187\139 ch\225\187\167 t\225\187\139ch c\225\187\167a \nHi\225\187\135p H\225\187\153i Nghi\195\170n C\225\187\169u Si\195\170u Nhi\195\170n Echhart t\225\187\171 khi h\225\187\153i th\195\160nh l\225\186\173p, tuy nhi\195\170n, Regina ch\198\176a bao gi\225\187\157 l\195\160 ng\198\176\225\187\157i th\195\173ch truy\225\187\129n th\225\187\145ng n\195\160y. C\195\179 l\225\186\189 c\195\180 li\225\187\129u m\225\186\161ng ki\225\187\131m so\195\161t chi\225\186\191c \196\144\225\187\147ng H\225\187\147 c\225\187\167a m\195\172nh b\225\187\159i v\195\172 c\195\180 mu\225\187\145n t\225\187\171 b\225\187\143 truy\225\187\129n th\225\187\145ng c\197\169 c\225\187\167a gia \196\145\195\172nh. Ho\225\186\183c c\195\180 \196\145\195\163 ch\195\161n v\225\187\155i vi\225\187\135c l\195\186c n\195\160o c\197\169ng th\225\186\165y l\225\186\161nh."
