L32_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_DELTA_CA_MARIA"
L33_1 = "Maria Antonov (Garguantia) l\195\160 m\225\187\153t L\195\173nh C\198\161 \196\144\225\187\153ng c\195\179 kh\225\186\163 n\196\131ng duy tr\195\172 tr\225\186\173n tuy\225\186\191n v\225\187\155i kh\225\186\163 n\196\131ng \196\145i\225\187\129u ph\225\187\145i \196\145\225\187\147ng minh ra ti\225\187\129n tuy\225\186\191n nhanh ch\195\179ng v\195\160 g\195\162y cho\195\161ng k\225\186\187 th\195\185.\n\nM\195\161y gia t\225\187\145c kh\195\180ng-th\225\187\157i gian t\225\186\165n c\195\180ng Garguantia l\195\160 m\225\187\153t v\197\169 kh\195\173 chi\225\186\191n l\198\176\225\187\163c li\195\170n k\225\186\191t v\225\187\155i kh\225\186\163 n\196\131ng v\225\186\173n chuy\225\187\131n c\225\187\167a Maria Antonov \196\145\225\187\131 t\225\187\145i \196\145a h\195\179a s\225\187\169c m\225\186\161nh c\225\187\167a n\195\179. Tuy nhi\195\170n, v\195\172 c\195\179 m\225\187\153t l\225\187\151 h\225\187\149ng thi\225\186\191t k\225\186\191 c\198\161 b\225\186\163n, ng\198\176\225\187\157i d\195\185ng ph\225\186\163i g\195\161nh v\195\161c tr\225\187\141ng l\198\176\225\187\163ng l\225\187\155n trong khi Garguantia \196\145\198\176\225\187\163c k\195\173ch ho\225\186\161t. \196\144\225\187\131 kh\225\186\175c ph\225\187\165c l\225\187\151 h\225\187\149ng n\195\160y, nh\195\179m nghi\195\170n c\225\187\169u \196\145\195\163 thi\225\186\191t k\225\186\191 \196\145\225\186\163o ng\198\176\225\187\163c c\195\180ng ngh\225\187\135 sinh h\225\187\141c m\195\160 Maria \196\145\198\176a cho h\225\187\141, gi\195\186p c\195\180 \225\186\165y thay \196\145\225\187\149i tu\225\187\149i t\195\161c th\225\187\177c s\225\187\177 c\225\187\167a m\195\172nh.\n\nB\225\186\177ng c\195\161ch xu\225\186\165t hi\225\187\135n tr\225\187\159 l\225\186\161i trong h\195\172nh h\195\160i tr\225\186\187 h\198\161n, Maria \196\145\195\163 khi\225\186\191n c\195\161c qu\195\162n nh\195\162n ph\225\186\163i g\225\187\141i c\195\180 l\195\160 \"N\225\187\175 Th\225\186\167n Chi\225\186\191n Tranh Hi\225\187\135n \196\144\225\186\161i\"."
