L4_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CORRUPTED_M_ARMOR"
L5_1 = "Mors l\195\160 m\225\187\153t L\195\173nh Ph\195\178ng V\225\187\135 t\196\131ng v\196\169nh vi\225\187\133n HP v\195\160 DEF c\225\187\167a c\195\180 \225\186\165y b\225\186\165t c\225\187\169 khi n\195\160o \196\145\225\187\147ng minh ch\225\186\191t.\n\nTrong th\225\187\157i C\225\187\165c Qu\225\186\163n L\195\189 C\197\169, Mors l\195\160 m\225\187\153t th\225\187\177c th\225\187\131 ch\225\187\169ng minh m\225\187\169c \196\145\225\187\153 nguy hi\225\187\131m c\225\187\167a m\225\187\153t C\195\161i B\195\179ng \196\145\225\187\145i v\225\187\155i c\195\161c \196\145\198\161n v\225\187\139 b\195\172nh th\198\176\225\187\157ng. Nh\225\187\175ng c\225\186\163nh quay c\225\187\167a c\195\180 \225\186\165y cho th\225\186\165y m\225\187\153t th\225\187\169 hung d\225\187\175 v\195\160 \196\145\195\161ng lo ng\225\186\161i. C\195\180 \225\186\165y l\195\160 m\225\187\153t V.T.A.M, c\225\187\149 x\198\176a nh\198\176 Maestra Nequitia, nh\198\176ng gi\225\187\145ng nh\198\176 b\225\186\165t k\225\187\179 C\195\161i B\195\179ng n\195\160o kh\195\161c, kh\195\180ng c\195\179 c\195\161ch n\195\160o \196\145\225\187\131 bi\225\186\191t li\225\187\135u m\225\187\153t ng\198\176\225\187\157i c\195\179 th\225\187\177c s\225\187\177 c\195\179 th\225\187\131 giao ti\225\186\191p v\225\187\155i c\195\180 \225\186\165y hay kh\195\180ng ch\225\187\137 v\195\172 c\195\180 \225\186\165y c\195\179 kh\225\186\163 n\196\131ng tr\195\178 chuy\225\187\135n.\n\n\196\144\195\161ng ch\195\186 \195\189, c\195\180 \225\186\165y l\195\160 m\225\187\153t \196\145\225\187\145i t\198\176\225\187\163ng hi\225\186\191m hoi th\225\187\131 hi\225\187\135n th\195\161i \196\145\225\187\153 th\195\185 \196\145\225\187\139ch v\225\187\155i V.T.A.M, nh\198\176ng ai c\197\169ng ph\225\186\163i ng\195\161n ng\225\186\169m v\195\172 c\195\161c h\195\160nh vi \196\145\195\179 kh\195\180ng \196\145\198\176\225\187\163c th\225\187\131 hi\225\187\135n \196\145\225\186\167y \196\145\225\187\167, nh\198\