L2_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_SIXWING_AMY"
L3_1 = "  Amy Firstwing l\195\160 m\225\187\153t L\195\173nh B\225\186\175n T\225\187\137a s\225\187\173 d\225\187\165ng nh\225\187\175ng s\225\187\163i d\195\162y \196\145\225\187\131 c\225\186\175t v\195\160o k\225\186\187 th\195\185 v\195\160 \196\145i\225\187\129u khi\225\187\131n nh\225\187\175ng k\225\186\187 c\195\178n s\225\187\145ng s\195\179t.\n\n   C\195\161ch c\195\180 \225\186\165y \196\131n m\225\186\183c v\195\160 c\198\176 x\225\187\173 k\225\187\179 l\225\186\161 th\225\187\131 hi\225\187\135n m\225\187\153t \196\145i\225\187\129u g\195\172 \196\145\195\179 r\225\186\165t r\195\181 r\195\160ng, nh\198\176ng kh\195\180ng ai bi\225\186\191t l\195\160 g\195\172. Ch\195\173nh x\195\161c h\198\161n, b\225\186\165t c\225\187\169 ai c\225\187\145 g\225\186\175ng t\195\172m hi\225\187\131u qu\195\161 kh\225\187\169 c\225\187\167a c\195\180 \225\186\165y \196\145\225\187\129u \196\145\195\163 bi\225\186\191n m\225\186\165t kh\195\180ng d\225\186\165u v\225\186\191t. Theo l\225\187\157i khai c\225\187\167a nh\195\162n ch\225\187\169ng, c\195\180 \225\186\165y b\225\186\165t c\225\186\169n, thi\225\186\191u ki\195\170n nh\225\186\171n, c\195\161u k\225\187\137nh v\195\160 m\225\186\175c ch\225\187\169ng ch\225\187\145ng \196\145\225\187\145i x\195\163 h\225\187\153i.\n   Nh\198\176ng h\225\187\147 s\198\161 th\225\187\177c t\225\186\191 c\225\187\167a c\195\180 \225\186\165y cho th\225\186\165y c\195\180 \225\186\165y l\195\160 m\225\187\153t chuy\195\170n gia t\225\187\137 m\225\187\137 v\195\160 kh\195\180ng bao gi\225\187\157 l\195\160m vi\225\187\135c m\195\160 kh\195\180ng \196\145\225\186\161t \196\145\198\176\225\187\163c m\225\187\165c \196\145\195\173ch r\195\181 r\195\160ng. V\225\186\173y, ai m\225\187\155i l\195\160 c\195\180 \225\186\165y? "
