L3_1 = "SI_COLLECTION_UNIT_INTRO_OPR_MOMO"
L4_1 = "Momo l\195\160 m\225\187\153t Ch\195\186a Qu\225\187\183 (t\225\187\177 x\198\176ng) c\195\179 \196\145\225\187\153i qu\195\162n b\225\186\165t kh\225\186\163 chi\225\186\191n b\225\186\161i, bao g\225\187\147m m\225\187\153t con b\195\186p b\195\170 r\225\187\147ng hung h\195\163n t\195\170n l\195\160 Huff Puff v\195\160 T\225\187\169 Thi\195\170n V\198\176\198\161ng (ch\198\176a r\195\181 danh t\195\173nh t\225\186\165t c\225\186\163). \n\nC\195\180 \225\186\165y tuy\225\187\135t v\225\187\157i \196\145\225\186\191n m\225\187\169c lu\195\180n b\225\187\139 nh\225\187\175ng th\225\186\191 l\225\187\177c b\195\170n ngo\195\160i \196\145e d\225\187\141a, bao g\225\187\147m c\225\186\163 ch\225\186\173u hoa ng\225\186\171u nhi\195\170n r\198\161i, v\197\169ng n\198\176\225\187\155c tr\195\180ng v\195\180 h\225\186\161i tr\195\170n \196\145\198\176\225\187\157ng ph\225\187\145 v\195\160 c\225\186\163 chim b\225\187\147 c\195\162u l\225\186\171n chim v\195\160nh khuy\195\170n b\195\169 t\195\173. T\225\186\165t nhi\195\170n, cu\225\187\145i c\195\185ng th\195\172 Momo lu\195\180n chi\225\186\191m \198\176u th\225\186\191! Nh\225\187\175ng th\225\186\167n d\195\162n trung th\195\160nh c\225\187\167a c\195\180 \225\186\165y nh\198\176 Gremory lu\195\180n b\225\186\163o \196\145\225\186\163m v\225\187\129 \196\145i\225\187\129u \196\145\195\179. \n\nMomo c\195\179 th\225\187\131 b\225\186\175t th\225\186\167n d\195\162n c\225\187\167a m\195\172nh l\195\160m b\225\186\165t c\225\187\169 \196\145i\225\187\129u g\195\172 cho c\195\180 \225\186\165y n\225\186\191u c\195\180 \225\186\165y mu\225\187\145n, nh\198\176ng c\195\180 \225\186\165y l\225\186\161i quan s\195\161t t\195\162m tr\225\186\161ng c\225\187\167a h\225\187\141 tr\198\176\225\187\155c khi \196\145\198\176a ra y\195\170u c\225\186\167u. M\225\187\153t \196\145\225\186\183c \196\145i\225\187\131m \196\145\195\161ng ng\198\176\225\187\161ng m\225\187\153 c\225\187\167a m\225\187\153t nh\195\160 l\195\163nh