L16_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_FUTURE_TITAN_RA"
L17_1 = "C\195\161c nh\195\160 khoa h\225\187\141c tr\225\186\187 coi d\225\187\177 \195\161n Chi\225\186\191n Tranh T\198\176\198\161ng Lai l\195\160 l\195\189 t\198\176\225\187\159ng c\225\187\167a gi\225\187\155i h\225\187\141c thu\225\186\173t. Tuy nhi\195\170n, do chi\225\186\191n tranh \196\145ang di\225\187\133n ra, l\225\187\163i \195\173ch xung \196\145\225\187\153t c\225\187\167a c\195\161c qu\225\187\145c gia \196\145\198\176\225\187\163c \196\145\225\186\167u t\198\176, v\195\160 c\225\186\163 xu\225\186\165t th\195\162n v\195\160 ngu\225\187\147n g\225\187\145c kh\195\161c nhau c\225\187\167a c\195\161c nh\195\162n vi\195\170n li\195\170n quan, th\225\186\173t kh\195\180ng d\225\187\133 d\195\160ng \196\145\225\187\131 c\195\161c nh\195\160 nghi\195\170n c\225\187\169u t\225\186\173p trung ho\195\160n to\195\160n v\195\160o nghi\195\170n c\225\187\169u. \n\nC\195\161c h\225\187\147 s\198\161 c\225\187\167a Jupiter l\195\160 nh\225\187\175ng \196\145\225\187\129 xu\225\186\165t \196\145\195\163 b\225\187\139 b\225\187\159i C\195\161c nh\195\160 nghi\195\170n c\225\187\169u Chi\225\186\191n Tranh T\198\176\198\161ng Lai  t\225\187\171 b\225\187\143 v\195\172 nhi\225\187\129u h\225\186\161n ch\225\186\191 trong th\225\186\191 gi\225\187\155i th\225\187\177c g\225\186\175n li\225\187\129n v\225\187\155i n\195\179. Ba trong s\225\187\145 \196\145\195\179 \196\145\198\176\225\187\163c so\225\186\161n th\225\186\163o \196\145\225\187\131 t\196\131ng c\198\176\225\187\157ng s\225\187\169c m\225\186\161nh c\225\187\167a v\197\169 kh\195\173 ch\195\173nh kh\195\180ng ng\198\176\225\187\157i l\195\161i. \n\nK\225\186\191 ho\225\186\161ch Triaina l\195\160 m\225\187\153t c\225\186\163i ti\225\186\191n c\195\179 k\225\186\191 ho\225\186\161ch \196\145\198\176a hi\225\187\135u su\225\186\165t c\225\187\167a Titan g\225\186\167n v\225\187\155i hi\225\187\135u su\225\186\165t c\225\187\167a b\225\186\163n g\225\187\145c. L\225\187\155p gi\195\161p h\225\187\163p ch\225\186\165t t\196\131ng c\198\176\225\187\157ng v\195\160 s\195\186ng ph\195\178ng kh\195\180ng d\225\186\161ng h\225\187\153p cho ph\195\169p n\195\179 th\195\173ch \225\187\169ng v\225\187\155i nhi\225\187\129u t\195\172nh hu\225\187\145ng \196\145a d\225\186\161ng, v\195\160 h\195\160ng lo\225\186\161t h\225\187\135 th\225\187\145ng ph\195\178ng ng\225\187\177 ch\225\187\167 \196\145\225\187\153ng \196\145ang th\195\161ch th\225\187\169c b\225\186\165t k\225\187\179 k\225\186\187 th\195\185 n\195\160o c\195\179 th\225\187\131 v\198\176\225\187\163t qua cu\225\187\153c b\225\186\175n ph\195\161 t\195\160n b\225\186\161o. Sergei Chernov, nh\195\160 nghi\195\170n c\225\187\169u l\195\160 m\225\187\153t ph\225\186\167n c\225\187\167a k\225\186\191 ho\225\186\161ch, \196\145\195\163 ghi ch\195\186 nh\198\176 v\225\186\173y. \n\226\148\128 \227\128\140V\195\172 m\225\187\153t t\198\176\198\161ng lai m\195\160 con c\195\161i ch\195\186ng ta s\225\186\189 kh\195\180ng bi\225\186\191t g\195\172 v\225\187\129 chi\225\186\191n tranh.\227\128\141"
