L39_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ALPHA_C_SPEAR"
L40_1 = "Raphaela Juri K\225\186\187 S\196\131n \196\144u\225\187\149i \195\129c Qu\225\187\183 l\195\160 m\225\187\153t L\195\173nh T\225\186\165n C\195\180ng Lai c\195\179 th\225\187\131 chuy\225\187\131n \196\145\225\187\149i gi\225\187\175a Th\195\161p \226\128\156Ch\225\186\191 \196\144\225\187\153 Ng\198\176\225\187\157i Canh G\195\161c\226\128\157 v\195\160 L\195\173nh T\225\186\165n C\195\180ng \226\128\156Ch\225\186\191 \196\144\225\187\153 K\225\186\187 S\196\131n \196\144u\225\187\149i\226\128\157.\n\nRaphaela \196\145\195\163 ph\195\161t minh ra th\198\176\198\161ng thu\225\186\173t c\225\187\167a ri\195\170ng m\195\172nh ch\225\187\137 trong m\225\187\153t th\195\161ng sau khi \196\145\225\187\141c ghi ch\195\186 b\195\173 m\225\186\173t c\225\187\167a anh trai sinh \196\145\195\180i c\225\187\167a c\195\180 \225\186\165y, Jun, \196\145\225\187\131 l\225\186\161i. C\195\180 \225\186\165y l\195\160 ng\198\176\225\187\157i duy nh\225\186\165t \196\145\195\163 th\195\160nh th\225\186\161o \226\128\156Th\198\176\198\161ng Thu\225\186\173t Truy Tung\226\128\157, cho ph\195\169p c\195\180 \225\186\165y t\225\186\165n c\195\180ng m\225\186\161nh m\225\186\189 h\198\161n khi chi\225\186\191n \196\145\225\186\165u v\225\187\155i \195\161c qu\225\187\183.\n\nC\195\180 \225\186\165y tham gia Alphatrix v\195\172 h\225\187\141 \196\145\195\161nh gi\195\161 cao gi\195\161 tr\225\187\139 K\225\186\187 S\196\131n \196\144u\225\187\149i \195\129c Qu\225\187\183 c\225\187\167a c\195\180. C\195\161c ho\225\186\161t \196\145\225\187\153ng c\225\187\167a c\195\180 \196\145\225\187\129u \196\145\198\176\225\187\163c c\195\180ng ty \225\187\167ng h\225\187\153.\n*M\195\180 t\225\186\163 \225\187\159 tr\195\170n l\195\160 b\225\186\163n t\195\179m t\225\186\175t l\195\189 l\225\187\139ch \196\145\225\187\145i t\198\176\225\187\163ng \196\145i\225\187\129u tra \196\145\198\176\225\187\163c n\225\187\153p cho Alphatrix."
