L9_1 = "Maria Antonov l\195\160 m\225\187\153t l\195\173nh h\225\187\151 tr\225\187\163 t\225\186\165n c\195\180ng, ng\198\176\225\187\157i ngay l\225\186\173p t\225\187\169c tri\225\187\131n khai c\195\161c \196\145\198\161n v\225\187\139 c\225\187\167a m\195\172nh \196\145\225\187\131 chi\225\186\191n \196\145\225\186\165u trong khi c\198\176\225\187\157ng h\195\179a kh\225\186\163 n\196\131ng t\225\186\165n c\195\180ng c\225\187\167a \196\145\225\187\147ng minh.\n\nTrung T\198\176\225\187\155ng Antonov l\195\160 m\225\187\153t anh h\195\185ng n\225\187\149i ti\225\186\191ng, ng\198\176\225\187\157i \196\145\195\163 d\225\186\171n d\225\186\175t Cu\225\187\153c Chi\225\186\191n \196\144\225\186\161i Thanh L\225\187\141c \196\145\225\186\191n chi\225\186\191n th\225\186\175ng. H\225\187\141c thuy\225\186\191t Ch\225\187\145ng \196\130n M\195\178n c\225\187\167a c\195\180 \225\186\165y v\225\186\171n \196\145\198\176\225\187\163c s\225\187\173 d\225\187\165ng nh\198\176 m\225\187\153t quy tr\195\172nh ti\195\170u chu\225\186\169n trong ng\195\160nh TASKFORCE.\n\nL\195\160 th\225\186\191 h\225\187\135 th\225\187\169 3 trong m\225\187\153t gia \196\145\195\172nh t\225\187\139 n\225\186\161n ng\198\176\225\187\157i Nga, c\195\180 \225\186\165y l\195\160 m\225\187\153t ph\225\187\165 n\225\187\175 c\195\179 nguy\195\170n t\225\186\175c v\195\160 \196\145\225\186\161t \196\145\225\186\191n c\225\186\165p b\225\186\173c hi\225\187\135n t\225\186\161i v\225\187\155i n\196\131ng l\225\187\177c b\225\186\163n th\195\162n, b\225\186\165t ch\225\186\165p nh\225\187\175ng th\225\187\167 \196\145o\225\186\161n \196\145\225\187\131 k\195\169o c\195\180 \225\186\165y xu\225\187\145ng c\225\187\167a c\225\186\165p tr\195\170n. \n\nM\225\187\153t s\225\187\145 ng\198\176\225\187\157i n\195\179i r\225\186\177ng c\195\180 \225\186\165y v\225\186\171n ti\225\186\191p t\225\187\165c \196\145\195\173ch th\195\162n ch\225\187\137 huy c\195\161c t\195\161c chi\225\186\191n kh\195\180ng ch\