L36_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ETC_S_DOCTOR"
L37_1 = "Lone Lee k\225\186\187 ph\225\186\163n di\225\187\135n l\195\160 m\225\187\153t L\195\173nh H\225\187\151 Tr\225\187\163 c\195\179 nhi\225\187\129u hi\225\187\135u \225\187\169ng b\225\186\165t l\225\187\163i kh\195\161c nhau, ch\225\186\179ng h\225\186\161n nh\198\176 Gi\225\186\163m CRIT DMG. \n\nTr\198\176\225\187\155c \196\145\195\162y, c\195\180 \225\186\165y ch\225\187\137 l\195\160 m\225\187\153t nh\195\160 khoa h\225\187\141c u u\225\186\165t th\195\180ng th\225\186\161o v\225\187\129 hi\225\187\135u \225\187\169ng Counterside. T\195\172nh y\195\170u \196\145\198\161n ph\198\176\198\161ng \196\145\195\163 thay \196\145\225\187\149i t\225\186\165t c\225\186\163, khi\225\186\191n c\195\180 \225\186\165y c\196\131m gh\195\169t t\225\186\165t c\225\186\163 c\195\161c c\225\186\183p \196\145\195\180i tr\195\170n th\225\186\191 gi\225\187\155i. \n\nC\195\180 \225\186\165y gia nh\225\186\173p ph\195\178ng th\195\173 nghi\225\187\135m tr\225\187\177c thu\225\187\153c C\225\187\165c Qu\225\186\163n L\195\189 \196\145\225\187\131 nghi\195\170n c\225\187\169u V.T.A.M. trong khi v\225\186\171n c\195\179 \195\162m m\198\176u ti\195\170u di\225\187\135t nh\225\187\175ng k\225\186\187 th\195\185 c\225\187\167a m\195\172nh. K\225\186\191 ho\225\186\161ch \196\145\195\163 th\225\186\165t b\225\186\161i v\195\160o th\225\187\157i \196\145i\225\187\131m quan tr\225\187\141ng v\195\160 c\195\180 \196\145\195\163 b\225\187\139 t\225\187\145ng v\195\160o t\195\185.\n\nGi\225\187\157 \196\145\195\162y, c\195\180 \225\186\165y \196\145\195\163 v\198\176\225\187\163t ng\225\187\165c th\195\160nh c\195\180ng v\195\160 kh\195\180ng ai bi\225\186\191t c\195\180 \225\186\165y \196\145\225\187\139nh l\195\160m g\195\172. M\225\187\153t \196\145i\225\187\129u r\195\181 r\195\160ng l\195\160 b\195\162y gi\225\187\157 c\195\180 \225\186\165y \196\145ang l\195\160m vi\225\187\135c cho ai \196\145\195\179 v\195\160 kh\195\180ng c\195\178n h\225\187\169ng th\195\186 v\225\187\155i vi\225\187\135c ph\195\161 h\225\187\167y c\195\161c c\225\186\183p \196\145\195\180i v\195\180 t\225\187\153i n\225\187\175a. "
