L37_1 = "SI_EVENT_HELP_DESC_EVENT_BINGO_LONELY"
L38_1 = "<b><color=#4EC2F3>[S\225\187\177 Ki\225\187\135n Li\195\170n K\225\186\191t M\225\186\161ch \196\144\225\187\139nh M\225\187\135nh C\225\187\167a Lone Lee]</color></b>\n<color=#FFCF3B>- Thu th\225\186\173p v\195\160 ph\195\162n t\195\173ch H\225\187\147 s\198\161 \196\144\225\187\139nh M\225\187\135nh.</color>\n<color=#FFCF3B>- Ho\195\160n th\195\160nh c\195\161c h\195\160ng Bingo v\195\160 nh\225\186\173n ph\225\186\167n th\198\176\225\187\159ng trong s\225\187\177 ki\225\187\135n \196\145\225\186\183c bi\225\187\135t n\195\160y.</color>\n\n<b><color=#FFFFFF>[Ph\195\162n T\195\173ch D\225\187\175 Li\225\187\135u] </color></b>\n<color=#F2F2F2>- Ch\198\161i H\225\187\147i 2 tr\225\187\159 l\195\170n c\225\187\167a Nhi\225\187\135m V\225\187\165 Ch\195\173nh, Chuy\225\187\135n B\195\170n L\225\187\129, T\195\161c Chi\225\186\191n Cung \225\187\168ng v\195\160 S\225\187\177 Ki\225\187\135n \196\145\225\187\131 c\195\179 c\198\161 h\225\187\153i t\195\172m th\225\186\165y <color=#FFCF3B>H\225\187\147 S\198\161 \196\144\225\187\139nh M\225\187\135nh</color>.</color>\n<color=#F2F2F2>- S\225\187\173 d\225\187\165ng <color=#FFCF3B>H\225\187\147 S\198\161 \196\144\225\187\139nh M\225\187\135nh</color> v\195\160 ph\195\162n t\195\173ch d\225\187\175 li\225\187\135u c\225\187\167a n\195\179 \196\145\225\187\131 nh\225\186\173n m\225\187\153t s\225\187\145 ng\225\186\171u nhi\195\170n.</color>\n<color=#F2F2F2>- M\225\187\151i s\225\187\145 s\225\186\189 m\225\187\159 \195\180 c\225\187\167a n\195\179 khi nh\225\186\173n \196\145\198\176\225\187\163c l\225\186\167n \196\145\225\186\167u ti\195\170n.</color>\n<color=#F2F2F2>- <color=#FFCF3B>H\225\187\147 S\198\161 \196\144\225\187\139nh M\225\187\135nh</color> ch\198\176a \196\145\198\176\225\187\163c s\225\187\173 d\225\187\165ng s\225\186\189 b\225\187\139 x\195\179a sau s\225\187\177 ki\225\187\135n, trong th\225\187\157i gian b\225\186\163o tr\195\172 theo l\225\187\139ch tr\195\172nh.</color>\n<color=#F2F2F2>- <color=#FFCF3B>H\225\187\147 S\198\161 \196\144\225\187\139nh M\225\187\135nh </color>c\195\178n d\198\176 c\195\179 th\225\187\131 \196\145\198\176\225\187\163c \196\145\225\187\149i l\225\186\165y Xu V\195\160ng t\225\186\161i C\225\187\173a H\195\160ng trong th\225\187\157i gian s\225\187\177 ki\225\187\135n.</color>\n\n<b><color=#FFFFFF>[Ph\195\162n T\195\173ch B\225\186\163o \196\144\225\186\163m]</color></b>\n<color=#F2F2F2>- C\195\161c con s\225\187\145 c\225\187\153ng th\195\170m <color=#FFCF3B>\196\144i\225\187\131m Tr\195\185ng L\225\186\183p</color> n\225\186\191u \196\145\198\176\225\187\163c nh\225\186\173n nhi\225\187\129u l\225\186\167n.</color>\n<color=#F2F2F2>- B\225\186\161n c\195\179 th\225\187\131 s\225\187\173 d\225\187\165ng <color=#FFCF3B>\196\144i\225\187\131m Tr\195\185ng L\225\186\183p</color> n\195\160y \196\145\225\187\131 m\225\187\159 c\195\161c \195\180 \196\145\195\163 m\225\187\159 kh\195\179a m\195\160 b\225\186\161n ch\225\187\141n.</color>\n\n<b><color=#FFFFFF>[Nhi\225\187\135m V\225\187\165 Ph\195\162n T\195\173ch]</color></b>\n<color=#F2F2F2>- 4 \195\180 trung t\195\162m c\195\179 th\225\187\131 ch\225\187\137 \196\145\198\176\225\187\163c m\225\187\159 th\195\180ng qua c\195\161c nhi\225\187\135m v\225\187\165 Ph\195\162n T\195\173ch, ch\225\187\169 kh\195\180ng th\225\187\131 th\195\180ng qua Ph\195\162n T\195\173ch th\198\176\225\187\157ng hay B\225\186\163o \196\144\225\186\163m.</color>\n\n<b><color=#FFFFFF>[Ph\225\186\167n Th\198\176\225\187\159ng] </color></b>\n<color=#F2F2F2>- M\225\187\159 t\225\186\165t c\225\186\163 d\225\187\175 li\225\187\135u theo \196\145\198\176\225\187\157ng th\225\186\179ng ho\225\186\183c \196\145\198\176\225\187\157ng ch\195\169o s\225\186\189 \196\145\198\176\225\187\163c <color=#FFCF3B>Bingo</color>.</color>\n<color=#F2F2F2>- Ho\195\160n th\195\160nh m\225\187\151i h\195\160ng Bingo v\195\160 b\225\186\161n s\225\186\189 nh\225\186\173n \196\145\198\176\225\187\163c <color=#FFCF3B>ph\225\186\167n th\198\176\225\187\159ng Ho\195\160n Th\195\160nh Bingo</color>.</color>\n<color=#F2F2F2>- B\225\186\161n c\197\169ng c\195\179 th\225\187\131 nh\225\186\173n \196\145\198\176\225\187\163c <color=#FFCF3B> ph\225\186\167n th\198\176\225\187\159ng Bingo T\195\173ch L\197\169y</color>, t\195\185y thu\225\187\153c v\195\160o s\225\187\145 l\198\176\225\187\163ng h\195\160ng Bingo b\225\186\161n \196\145\195\163 ho\195\160n th\195\160nh.</color>"
