L10_1 = "<b><color=#4EC2F3>[S\225\187\177 Ki\225\187\135n Li\195\170n K\225\186\191t M\225\186\161ch M\195\185a Thu]</color></b>\n<color=#FFCF3B>- Thu th\225\186\173p v\195\160 ph\195\162n t\195\173ch H\225\187\147 S\198\161 M\195\185a Thu.</color>\n<color=#FFCF3B>- Ho\195\160n th\195\160nh c\195\161c h\195\160ng Bingo v\195\160 nh\225\186\173n th\198\176\225\187\159ng trong s\225\187\177 ki\225\187\135n \196\145\225\186\183c bi\225\187\135t n\195\160y.</color>\n\n<b><color=#FFFFFF>[Ph\195\162n T\195\173ch D\225\187\175 Li\225\187\135u]</color></b>\n<color=#F2F2F2>- Ch\198\161i c\195\161c h\225\187\147i Nhi\225\187\135m V\225\187\165 Ch\195\173nh, H\225\187\163p \196\144\225\187\147ng Mi\225\187\133n Ph\195\173 v\195\160 S\225\187\177 Ki\225\187\135n \196\145\225\187\131 c\195\179 c\198\161 h\225\187\153i t\195\172m <color=#FFCF3B>H\225\187\147 S\198\161 M\195\185a Thu</color>.</color>\n<color=#F2F2F2>- S\225\187\173 d\225\187\165ng <color=#FFCF3B>H\225\187\147 S\198\161 M\195\185a Thu</color> v\195\160 ph\195\162n t\195\173ch d\225\187\175 li\225\187\135u c\225\187\167a n\195\179 \196\145\225\187\131 nh\225\186\173n m\225\187\153t s\225\187\145 ng\225\186\171u nhi\195\170n.</color>\n<color=#F2F2F2>- M\225\187\151i s\225\187\145 m\225\187\159 \195\180 khi \196\145\198\176\225\187\163c nh\225\186\173n l\225\186\167n \196\145\225\186\167u .</color>\n<color=#F2F2F2>- <color=#FFCF3B>H\225\187\147 S\198\161 M\195\185a Thu</color> ch\198\176a d\195\185ng h\225\186\191t s\225\186\189 b\225\187\139 x\195\179a trong th\225\187\157i gian b\225\186\163o tr\195\172 theo l\225\187\139ch tr\195\172nh sau th\225\187\157i gian s\225\187\177 ki\225\187\135n.</color>\n\n<b><color=#FFFFFF>[Ph\195\162n T\195\173ch B\225\186\163o \196\144\225\186\163m]</color></b>\n<color=#F2F2F2>- N\225\186\191u b\225\186\161n t\195\172m th\225\186\165y c\195\185ng m\225\187\153t s\225\187\145 nhi\225\187\129u h\198\161n m\225\187\153t l\225\186\167n, b\225\186\161n nh\225\186\173n \196\145\198\176\225\187\163c <color=#FFCF3B>\196\144i\225\187\131m Tr\195\185ng L\225\186\183p</color>.</color>\n<color=#F2F2F2>- B\225\186\161n c\195\179 th\225\187\131 s\225\187\173 d\225\187\165ng <color=#FFCF3B>\196\144i\225\187\131m Tr\195\185ng L\225\186\183p</color> \196\145\225\187\131 m\225\187\159 kh\195\179a v\225\187\139 tr\195\173 m\195\160 b\225\186\161n mu\225\187\145n.</color>\n\n<b><color=#FFFFFF>[Nhi\225\187\135m V\225\187\165 Ph\195\162n T\195\173ch]</color></b>\n<color=#F2F2F2>- 4 v\225\187\139 tr\195\173 trong trung t\195\162m ch\225\187\137 c\195\179 th\225\187\131 \196\145\198\176\225\187\163c m\225\187\159 kh\195\179a b\225\186\177ng nhi\225\187\135m v\225\187\165 Ph\195\162n T\195\173ch, v\195\160 kh\195\180ng th\225\187\131 \196\145\198\176\225\187\163c m\225\187\159 kh\195\179a b\225\186\177ng Ph\195\162n T\195\173ch th\198\176\225\187\157ng hay B\225\186\163o \196\144\225\186\163m.</color>\n\n<b><color=#FFFFFF>[Ph\225\186\167n Th\198\176\225\187\159ng]</color></b>\n<color=#F2F2F2>- M\225\187\159 kh\195\179a t\225\186\165t c\225\186\163 d\225\187\175 li\225\187\135u trong c\195\185ng m\225\187\153t h\195\160ng theo b\225\186\165t k\225\187\179 h\198\176\225\187\155ng n\195\160o, v\195\160 h\195\160ng <color=#FFCF3B>Bingo</color> s\225\186\189 \196\145\198\176\225\187\163c ho\195\160n th\195\160nh.</color>\n<color=#F2F2F2>- M\225\187\151i h\195\160ng Bingo cung c\225\186\165p m\225\187\153t <color=#FFCF3B>ph\225\186\167n th\198\176\225\187\159ng</color> sau khi ho\195\160n th\195\160nh.</color>\n<color=#F2F2F2>- Ho\195\160n th\195\160nh m\225\187\153t s\225\187\145 h\195\160ng Bingo nh\225\186\165t \196\145\225\187\139nh, v\195\160 b\225\186\161n c\197\169ng s\225\186\189 nh\225\186\173n \196\145\198\176\225\187\163c <color=#FFCF3B>ph\225\186\167n th\198\176\225\187\159ng Bingo T\195\173ch L\197\169y</color>.</color>"
