L11_1 = "Lee Sooyeon \196\145\195\163 tr\225\187\159 l\225\186\161i chi\225\186\191n tr\198\176\225\187\157ng v\225\187\155i trang b\225\187\139 thi\225\186\191t b\225\187\139 m\225\187\155i! C\195\180 \225\186\165y l\195\160 m\225\187\153t l\195\173nh t\225\186\165n c\195\180ng t\225\186\167m xa m\225\186\161nh m\225\186\189 v\225\187\155i kh\225\186\163 n\196\131ng t\225\186\173n di\225\187\135t k\225\186\187 th\195\185 khi c\195\180 \225\186\165y tham chi\225\186\191n t\225\187\171 tr\195\170n kh\195\180ng. Ch\225\187\137 m\225\187\153t m\195\172nh c\195\180 l\195\160 \196\145\225\187\167 \196\145\225\187\131 \196\145\225\186\163m b\225\186\163o uy th\225\186\191 tr\195\170n kh\195\180ng. \n\nC\195\180 \196\145\195\163 t\225\187\171ng l\195\160 ph\195\179 ch\225\187\167 t\225\187\139ch c\225\187\167a C\195\180ng ty Coffin, trong th\225\187\157i gian \196\145\195\179, s\225\187\177 nghi\225\187\135p c\225\187\167a c\195\180 v\225\187\155i t\198\176 c\195\161ch l\195\160 Counter C\225\186\165p S \196\145\195\163 tr\225\187\159 th\195\160nh m\225\187\153t k\225\187\183 ni\225\187\135m. Tuy nhi\195\170n, g\225\186\167n \196\145\195\162y c\195\180 \225\186\165y \196\145\195\163 b\195\173 m\225\186\173t tr\225\187\159 l\225\186\161i v\195\160 ch\225\187\169ng minh r\225\186\177ng c\195\180 \225\186\165y kh\195\180ng h\225\187\129 k\195\169m c\225\187\143i b\225\186\177ng c\195\161ch l\195\160m m\225\187\155i th\195\160nh t\195\173ch c\197\169 c\225\187\167a m\195\172nh v\225\187\155i nhi\225\187\129u s\225\186\175c th\195\161i.\nC\195\180 \225\186\165y v\225\186\171n l\195\160 m\225\187\153t ng\198\176\225\187\157i keo ki\225\187\135t v\225\187\155i th\195\161i \196\145\225\187\153 l\225\186\161nh l\195\185ng, th\195\173ch kinh doanh, nh\198\176ng \195\173t nh\225\186\165t b\195\162y gi\225\187\157 khi chi\225\186\191n \196\145\225\186\165u, c\195\180 \225\186\165y khi\225\186\191n m\225\187\141i ng\198\176\225\187\157i qu\195\170n \196\145i \196\145i\225\187\129u \196\145\195\179 v\195\160 nh\225\187\155 ra t\225\186\161i sao c\195\180 \225\186\165y l\195\160 \195\161t ch\225\187\167 b\195\160i c\225\187\167a c\195\180ng ty.\nC\195\180 \225\186\165y t\225\187\177 h\195\160o v\225\187\129 kh\225\186\163 n\196\131ng chi\225\186\191n \196\145\225\186\165u c\225\187\167a m\195\172nh, nh\198\176ng v\195\172 m\225\187\153t s\225\187\145 l\195\189 do, c\195\180 \225\186\165y kh\195\180ng th\195\173ch n\195\179i v\225\187\129 phong c\195\161ch chi\225\186\191n \196\145\225\186\165u c\197\169 c\225\187\167a m\195\172nh.\n"
