L13_1 = "(V\196\131n b\225\186\163n n\195\160y \196\145\195\163 \196\145\198\176\225\187\163c kh\195\180i ph\225\187\165c b\225\187\159i Qu\225\186\163n Tr\225\187\139 Vi\195\170n L\225\187\155p 1.) \nLyudmila s\225\187\173 d\225\187\165ng ph\195\161o h\225\186\163i qu\195\162n \196\145\225\187\131 b\225\186\175n ph\195\161 k\225\186\187 th\195\185 t\225\187\171 m\225\187\141i ph\195\173a v\195\160 th\225\186\191 ch\225\187\151 c\195\161c \196\145\225\187\147ng minh \196\145\195\163 ng\195\163 xu\225\187\145ng. Kh\225\186\163 n\196\131ng ngo\225\186\161i c\225\186\163m c\225\187\167a c\195\180, m\225\187\153t s\225\187\169c m\225\186\161nh hi\225\186\191m c\195\179 ngay c\225\186\163 trong C\225\187\165c Qu\225\186\163n L\195\189, c\195\179 th\225\187\131 h\225\186\161 g\225\187\165c nh\225\187\175ng k\225\186\187 th\195\185 mu\225\187\145n ti\225\186\191p c\225\186\173n c\195\180 xuy\195\170n qua h\195\160ng h\195\160ng l\225\187\155p l\225\187\155p s\195\186ng th\225\186\167n c\195\180ng m\225\187\153t c\195\161ch hi\225\187\135u qu\225\186\163. \n\nBan \196\145\225\186\167u, c\195\180 \225\186\165y mu\225\187\145n tr\225\187\159 th\195\160nh m\225\187\153t ki\225\187\131m so\195\161t vi\195\170n kh\195\180ng l\198\176u, nh\198\176ng xu h\198\176\225\187\155ng b\225\186\165t t\225\187\137nh khi nh\195\172n th\225\186\165y m\195\161u \196\145\195\163 c\225\186\163n tr\225\187\159 gi\225\186\165c m\198\161 n\195\160y c\225\187\167a c\195\180 \225\186\165y, v\195\160 ngay c\225\186\163 vi\225\187\135c b\225\187\149 nhi\225\187\135m c\195\180 \225\186\165y th\195\160nh nh\195\162n vi\195\170n ph\225\187\165 tr\195\161ch c\225\186\167u n\225\187\145i \196\145\195\163 ph\225\186\163i t\225\186\161m d\225\187\171ng. L\195\186c \196\145\225\186\167u, c\195\180 b\225\187\139 b\225\186\161n m\195\172nh, Lee Sooyeon, \195\169p bu\225\187\153c tr\225\187\159 th\195\160nh \196\145\225\186\183c v\225\187\165 th\225\187\177c \196\145\225\187\139a, nh\198\176ng c\195\180 nhanh ch\195\179ng nh\225\186\173n ra m\195\172nh c\195\179 t\195\160i ch\225\187\137 huy qu\195\162n \196\145\225\187\153i v\195\160 t\225\187\149 ch\225\187\169c t\195\161c chi\225\186\191n. \nC\195\180 tr\225\187\159 th\195\160nh th\225\187\167 l\196\169nh c\225\187\167a s\198\176 \196\145o\195\160n ph\195\161o binh, M\195\170 Cung, \225\187\159 \196\145\225\187\153 tu\225\187\149i tr\225\186\187 \196\145\195\161ng ng\225\186\161c nhi\195\170n, v\195\160 \198\176u ti\195\170n chi\225\186\191n \196\145\225\186\165u an to\195\160n b\225\186\177ng ph\195\161o h\198\161n l\195\160 c\225\186\173n chi\225\186\191n \196\145\195\163 nh\225\186\173n \196\145\198\176\225\187\163c s\225\187\177 \225\187\167ng h\225\187\153 t\225\187\171 qu\195\162n \196\145\225\187\153i c\225\187\167a c\195\180. \196\144i\225\187\131m y\225\186\191u duy nh\225\186\165t c\225\187\167a c\195\180 m\195\160 m\225\187\141i ng\198\176\225\187\157i \196\145\198\176\225\187\163c bi\225\186\191t l\195\160 c\195\180 r\225\186\165t v\225\187\165ng v\225\187\129 trong vi\195\170c ch\225\186\191 t\225\186\161o. R\225\186\165t nhi\225\187\129u l\225\186\167n, c\195\161c ph\225\187\165 ki\225\187\135n th\225\187\167 c\195\180ng c\225\187\167a c\195\180 \196\145\195\163 kh\225\187\167ng b\225\187\145 tinh th\225\186\167n nh\225\187\175ng \196\145\225\187\169a tr\225\186\187 nh\225\186\173n \196\145\198\176\225\187\163c ch\195\186ng.\n"
