L19_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_DAYMINE_HYUNSOO"
L20_1 = "Park Hyunsoo l\195\160 tr\198\176\225\187\159ng nh\195\179m khai th\195\161c \196\144\225\187\153i Khai M\225\187\143 Daymine 4.\nAnh \225\186\165y l\195\160 m\225\187\153t l\195\173nh ti\195\170n phong\nc\195\179 k\225\187\185 n\196\131ng ph\225\187\145i h\225\187\163p v\225\187\155i nh\225\187\175ng \196\145\225\187\147ng nghi\225\187\135p.\nAnh \225\186\165y t\225\187\171ng l\195\160 tr\225\187\163 l\195\189 hi\225\187\135n tr\198\176\225\187\157ng,\nm\225\187\153t ng\198\176\225\187\157i quen thu\225\187\153c v\225\187\155i ng\195\178i b\195\186t h\198\161n l\198\176\225\187\161i ki\225\186\191m.\nNh\198\176ng anh \225\186\165y quy\225\186\191t \196\145\225\187\139nh t\225\187\177 m\195\172nh tham gia chi\225\186\191n \196\145\225\186\165u\n\196\145\225\187\131 s\225\187\145ng s\195\179t qua th\225\187\157i k\225\187\179 suy tho\195\161i v\195\160 qu\195\161 tr\195\172nh t\195\161i c\198\161 c\225\186\165u th\198\176\225\187\157ng xuy\195\170n.\nTr\198\176\225\187\155c khi tr\225\187\159 th\195\160nh Counter, anh \225\186\165y \196\145\195\163 t\225\187\171ng\n\196\145\225\187\169ng gi\225\187\175a ranh gi\225\187\155i s\225\187\177 s\225\187\145ng v\195\160 c\195\161i ch\225\186\191t do l\195\160m vi\225\187\135c qu\195\161 s\225\187\169c.\nV\195\172 \196\145\195\163 c\195\179 kinh nghi\225\187\135m, anh \225\186\165y khuy\225\186\191n ngh\225\187\139 c\195\161c th\195\160nh vi\195\170n trong nh\195\179m c\225\187\167a m\195\172nh\nch\225\187\137 l\195\160m vi\225\187\135c trong gi\225\187\157 l\195\160m vi\225\187\135c\nv\195\160 ch\225\187\139u tr\195\161ch nhi\225\187\135m t\225\186\165t c\225\186\163 vi\225\187\135c l\195\160m th\195\170m.\nTrong qu\195\161 kh\225\187\169, anh \225\186\165y \196\145\195\163 l\195\160m vi\225\187\135c ch\196\131m ch\225\187\137 v\195\172 anh \225\186\165y y\195\170u th\195\173ch c\195\180ng vi\225\187\135c c\225\187\167a m\195\172nh\nho\225\186\183c v\195\172 anh \225\186\165y mu\225\187\145n \196\145\198\176\225\187\163c th\196\131ng ch\225\187\169c. Nh\198\176ng b\195\162y gi\225\187\157 anh \225\186\165y \196\145ang\ngi\225\187\175 v\225\187\139 tr\195\173 c\225\187\167a m\195\172nh v\195\172 c\225\186\165p d\198\176\225\187\155i c\225\187\167a m\195\172nh, nh\225\187\175ng ng\198\176\225\187\157i d\225\187\177a v\195\160o anh \225\186\165y."
