L41_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ADMIN_GREATSWORD"
L42_1 = "(V\196\131n b\225\186\163n n\195\160y \196\145\195\163 \196\145\198\176\225\187\163c kh\195\180i ph\225\187\165c b\225\187\159i Qu\225\186\163n Tr\225\187\139 Vi\195\170n L\225\187\155p 1.) \nAlex, ph\195\179 ch\225\187\137 huy S\198\176 \196\144o\195\160n M\195\170 Cung, l\195\160 l\195\173nh ti\195\170n phong s\225\187\173 d\225\187\165ng n\195\178ng ph\195\161o plasma \196\145\195\163 \196\145\198\176\225\187\163c tu s\225\187\173a th\195\160nh m\225\187\153t thanh tr\198\176\225\187\157ng ki\225\186\191m. \n\nC\195\180 s\225\187\173 d\225\187\165ng kh\225\186\163 n\196\131ng \196\145i\225\187\129u khi\225\187\131n s\195\179ng c\225\187\167a m\195\172nh \196\145\225\187\131 t\225\186\165n c\195\180ng nh\225\187\175ng k\225\186\187 th\195\185 xung quanh, v\195\160 khi c\195\180 c\195\160ng tuy\225\187\135t v\225\187\141ng, s\225\187\169c m\225\186\161nh c\225\187\167a c\195\180 c\195\160ng l\225\187\155n. \n\nBan \196\145\225\186\167u, l\195\160 m\225\187\153t trong nh\225\187\175ng b\225\186\163n sao do k\225\186\187 th\195\185 c\225\187\167a C\225\187\165c Qu\225\186\163n L\195\189 t\225\186\161o ra, c\195\180 \196\145\195\163 b\225\187\139 ng\198\176\225\187\157i t\225\186\161o ra m\195\172nh b\225\187\143 r\198\161i v\195\172 th\225\186\165t b\225\186\161i, sau \196\145\195\179 \196\145\198\176\225\187\163c C\225\187\165c Qu\225\186\163n L\195\189 gi\225\186\163i c\225\187\169u. L\225\186\167n \196\145\225\186\167u ti\195\170n c\195\180 \196\145\198\176\225\187\163c b\225\187\149 nhi\225\187\135m v\195\160o S\198\176 \196\144o\195\160n M\195\170 Cung chuy\195\170n th\225\187\177c hi\225\187\135n c\195\161c ho\225\186\161t \196\145\225\187\153ng b\225\186\175n ph\195\161 t\225\186\167m xa, b\225\187\159i v\195\172 c\195\180 kh\195\180ng \196\145\225\187\167 m\225\186\161nh \196\145\225\187\131 x\225\187\173 l\195\189 c\225\186\173n chi\225\186\191n, nh\198\176ng sau khi th\195\160nh th\225\186\161o c\195\161ch ki\225\187\131m so\195\161t v\197\169 kh\195\173 c\225\187\167a m\195\172nh, c\195\180 \196\145\195\163 tr\225\187\159 th\195\160nh m\225\187\153t ng\198\176\225\187\157i \196\145\195\161ng tin c\225\186\173y.\n\nKh\225\186\163 n\196\131ng th\225\187\177c hi\225\187\135n nhi\225\187\135m v\225\187\165 c\225\187\167a c\195\180 nhi\225\187\129u l\225\186\167n kh\195\180ng \196\145\198\176\225\187\163c t\195\173n nhi\225\187\135m, nh\198\176ng ni\225\187\129m tin kh\195\180ng th\225\187\131 lay chuy\225\187\131n c\225\187\167a ch\225\187\137 huy \196\145\225\187\145i v\225\187\155i c\195\180 v\195\160 nhu c\225\186\167u c\225\187\167a S\198\176 \196\145o\195\160n trong vi\225\187\135c h\225\187\151 tr\225\187\163 c\225\186\173n chi\225\186\191n kh\225\186\169n c\225\186\165p \196\145\195\163 gi\225\187\175 c\195\180 \225\187\159 l\225\186\161i S\198\176 \196\144o\195\160n.\n\nL\195\160 th\195\160nh l\197\169y cu\225\187\145i c\195\185ng cho s\198\176 \196\145o\195\160n c\225\187\167a m\195\172nh, c\195\180 \225\186\165y r\225\186\165t \196\145\198\176\225\187\163c k\195\173nh tr\225\187\141ng b\225\187\159i c\195\161c \196\145\225\187\147ng nghi\225\187\135p c\225\187\167a m\195\172nh.\n"
