L42_1 = "SI_COLLECTION_UNIT_INTRO_OPR_KIMHANA"
L43_1 = "Qu\225\186\163n L\195\189 Kim Hana l\195\160 m\225\187\153t th\195\160nh vi\195\170n thi\225\186\191t y\225\186\191u c\225\187\167a C\195\180ng ty Coffin, ng\198\176\225\187\157i l\195\163nh \196\145\225\186\161o nh\225\187\175ng ng\198\176\225\187\157i kh\195\161c b\225\186\177ng t\225\186\165m g\198\176\198\161ng v\195\160 l\195\178ng t\225\187\145t.\nC\195\180 \225\186\165y gia nh\225\186\173p c\195\180ng ty ngay sau khi t\225\187\145t nghi\225\187\135p trung h\225\187\141c. N\225\187\165 c\198\176\225\187\157i vui v\225\186\187 c\225\187\167a c\195\180 \225\186\165y l\195\160m b\225\187\171ng s\195\161ng kh\195\180ng kh\195\173 v\196\131n ph\195\178ng \196\145\195\180i khi c\195\179 v\225\186\187 t\225\186\187 nh\225\186\161t.\nTuy nhi\195\170n, v\225\187\129 \196\145\225\187\157i s\225\187\145ng c\195\161 nh\195\162n, c\195\180 \225\186\165y \196\145ang g\225\186\183p kh\195\179 kh\196\131n trong vi\225\187\135c t\195\172m ki\225\186\191m ng\198\176\225\187\157i \196\145\195\160n \195\180ng ph\195\185 h\225\187\163p. C\195\180 \196\145\195\163 tr\225\186\163i qua nhi\225\187\129u bu\225\187\149i xem m\225\186\175t m\195\185 qu\195\161ng, nh\198\176ng kh\195\180ng c\195\179 cu\225\187\153c h\225\186\185n h\195\178 th\225\187\169 hai n\195\160o. C\195\161c \196\145\225\187\147ng nghi\225\187\135p c\225\187\167a c\195\180 \225\186\165y nghi ng\225\187\157 \196\145i\225\187\129u \196\145\195\179 c\195\179 th\225\187\131 li\195\170n quan \196\145\225\186\191n vi\225\187\135c c\195\180 \225\186\165y th\198\176\225\187\157ng hay say x\225\187\137n. "
