L12_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_CIVIL_ZENA"
L13_1 = "Zena Bird l\195\160 T\225\187\149ng T\198\176 L\225\187\135nh c\225\187\167a H\225\187\151 Tr\225\187\163 Ch\195\173nh Th\225\187\169c.\nC\195\180 \225\186\165y l\195\160 m\225\187\153t l\195\173nh ti\195\170n phong m\225\187\155i n\225\187\149i,\nng\198\176\225\187\157i b\195\185 \196\145\225\186\175p \196\145i\225\187\131m y\225\186\191u v\225\187\129 ch\225\187\137 s\225\187\145 c\198\161 b\225\186\163n b\225\186\177ng c\195\161c k\225\187\185 n\196\131ng.\nC\195\180 \225\186\165y l\195\160 l\225\187\155p ph\195\179 khi g\225\186\183p ph\225\186\163i m\225\187\153t th\225\186\163m h\225\187\141a\ntrong chuy\225\186\191n \196\145i t\225\187\145t nghi\225\187\135p.\nSau \196\145\195\179, c\195\180 \196\145\195\163 k\195\173ch ho\225\186\161t \196\144\225\187\147ng h\225\187\147 \196\145\225\187\131 b\225\186\163o v\225\187\135 b\225\186\161n b\195\168 c\225\187\167a m\195\172nh.\nSau khi tho\195\161t kh\225\187\143i kh\225\187\167ng ho\225\186\163ng, c\195\180 \225\186\165y \196\145\195\163 tham gia\nH\225\187\151 Tr\225\187\163 Ch\195\173nh Th\225\187\169c \196\145\225\187\131 gi\195\186p \196\145\225\187\161 nhi\225\187\129u ng\198\176\225\187\157i h\198\161n v\225\187\155i\ns\225\187\169c m\225\186\161nh m\225\187\155i c\225\187\167a m\195\172nh.\nL\195\189 do t\225\186\161i sao c\195\180 \225\186\165y tr\225\187\159 th\195\160nh T\225\187\149ng T\198\176 L\225\187\135nh, m\225\186\183c d\195\185 v\225\187\155i\nt\198\176 c\195\161ch Counter v\195\160 ng\198\176\225\187\157i l\195\163nh \196\145\225\186\161o, c\195\180 \225\186\165y c\195\178n thi\225\186\191u kinh nghi\225\187\135m,\nl\195\160 v\195\172 kh\195\180ng ai mu\225\187\145n nh\225\186\173n tr\195\161ch nhi\225\187\135m n\195\160y.\nZena \196\145ang c\225\186\163m th\225\186\165y \195\161p l\225\187\177c v\225\187\155i v\225\187\139 tr\195\173 c\225\187\167a m\195\172nh,\nnh\198\176ng c\195\180 \225\186\165y kh\195\180ng ng\225\187\171ng c\225\187\145 g\225\186\175ng \196\145\225\187\131 tr\225\187\159 th\195\160nh\nng\198\176\225\187\157i ph\195\185 h\225\187\163p v\225\187\155i ch\225\187\169c v\225\187\165 c\225\187\167a m\195\172nh.\n"
