L26_1 = "Harab l\195\160 L\195\173nh H\225\187\151 Tr\225\187\163 v\195\160 khi t\225\186\165n c\195\180ng c\195\160ng l\195\162u, c\195\180 \225\186\165y l\225\186\161i c\195\160ng m\225\186\161nh h\198\161n. C\195\180 khi\225\186\191n c\195\161c \196\145\198\161n v\225\187\139 \196\145\198\176\225\187\163c tri\225\187\135u h\225\187\147i c\225\187\167a k\225\186\187 th\195\185 r\225\187\145i tr\195\173 v\195\160 t\225\187\177 t\225\186\165n c\195\180ng nhau.\n\n\196\144o\195\160n M\195\186a R\225\187\145i Cronenworth c\225\187\167a c\195\180 n\225\187\149i ti\225\186\191ng v\225\187\155i c\195\161c ch\198\176\198\161ng tr\195\172nh m\195\186a r\225\187\145i ch\195\162n th\225\187\177c. M\225\187\153t s\225\187\145 ng\198\176\225\187\157i h\195\162m m\225\187\153 c\225\187\167a h\225\187\141 b\225\187\139 cu\225\187\145n h\195\186t b\225\187\159i m\195\160n bi\225\187\131u di\225\187\133n \196\145\225\186\191n n\225\187\151i h\225\187\141 tin r\225\186\177ng h\225\187\141 nh\195\172n th\225\186\165y nh\225\187\175ng con r\225\187\145i th\225\187\177c s\225\187\177 r\198\161i n\198\176\225\187\155c m\225\186\175t.\n\nDo Chi\225\186\191n Tranh, Harab Cronenworth \196\145\195\163 \196\145i du l\225\187\139ch kh\225\186\175p th\225\186\191 gi\225\187\155i, tr\195\172nh di\225\187\133n mi\225\187\133n ph\195\173 nh\225\187\175ng ti\225\186\191t m\225\187\165c \196\145\195\161ng kinh ng\225\186\161c c\225\187\167a m\195\172nh \225\187\159 b\225\186\165t c\225\187\169 \196\145\195\162u. Khi \196\145\198\176\225\187\163c h\225\187\143i t\225\186\161i sao l\195\160m \196\145i\225\187\129u n\195\160y, c\195\180 \225\186\165y n\195\179i r\225\186\177ng c\195\180 \225\186\165y \196\145ang t\195\172m ki\225\186\191m m\225\187\153t con r\225\187\145i r\225\186\165t quan tr\225\187\141ng \196\145\225\187\145i v\225\187\155i m\195\172nh. G\225\186\167n \196\145\195\162y, c\195\179 \196\145i\225\187\129u g\195\172 \196\145\195\179 v\225\187\129 c\195\180 \225\186\165y \196\145\195\