L42_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_SL_SHOTGUN"
L43_1 = "M\225\187\153t ng\198\176\225\187\157i ti\195\170n phong, ng\198\176\225\187\157i c\195\179 th\225\187\131 \196\145\225\186\169y l\195\185i\nnhi\225\187\129u k\225\186\187 th\195\185 b\225\186\177ng c\195\161c cu\225\187\153c t\225\186\165n c\195\180ng khu v\225\187\177c m\225\186\183t \196\145\225\186\165t.\nH\225\187\141 l\195\160 \196\145\198\161n v\225\187\139 chuy\195\170n s\225\187\173 d\225\187\165ng\ns\195\186ng ng\225\186\175n SL-OSG. H\225\187\141 \196\145\195\178i h\225\187\143i s\225\187\177 gan d\225\186\161, nhanh nh\225\186\185n,\nv\195\160 k\225\187\185 n\196\131ng ra quy\225\186\191t \196\145\225\187\139nh nhanh ch\195\179ng, v\195\172 v\225\186\173y ch\225\187\137 nh\225\187\175ng ng\198\176\225\187\157i c\195\179 kinh nghi\225\187\135m nh\225\186\165t m\225\187\155i\n\196\145\198\176\225\187\163c hoan ngh\195\170nh v\195\160o v\225\187\139 tr\195\173 n\195\160y.\nSL-OSG l\195\160 m\225\187\153t kh\225\186\169u s\195\186ng ng\225\186\175n \196\145\198\176\225\187\163c ch\225\186\191 t\225\186\161o cho d\195\162n th\198\176\225\187\157ng b\225\187\159i\nc\195\180ng ty ti\225\187\129n th\195\162n c\225\187\167a \196\144\198\176\225\187\157ng Th\195\169p, Daero Machinery, v\195\160 s\225\187\169c m\225\186\161nh c\225\187\167a n\195\179\n\196\145\195\163 \196\145\198\176\225\187\163c ch\225\187\169ng minh trong Cu\225\187\153c Chi\225\186\191n \196\144\225\186\161i Thanh L\225\187\141c.\nNh\225\187\175ng kh\225\186\169u s\195\186ng n\195\160y gi\225\187\145ng nh\198\176 bi\225\187\131u t\198\176\225\187\163ng c\225\187\167a \196\144\198\176\225\187\157ng Th\195\169p,\nnh\198\176ng ng\198\176\225\187\157i s\225\187\159 h\225\187\175u ch\195\186ng\nh\195\160ng ng\195\160y \196\145\225\187\129u r\225\186\165t nh\195\160n r\225\187\151i, n\195\170n \196\145\198\176\225\187\163c g\225\187\141i l\195\160 nh\225\187\175ng c\225\187\177u binh\ntrong c\195\180ng ty."
