L13_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_SCHOOL_PRESIDENT"
L14_1 = "Yen Xing Lanchester l\195\160 ch\225\187\167 t\225\187\139ch H\225\187\153i \196\144\225\187\147ng H\225\187\141c Sinh H\225\187\141c Vi\225\187\135n Counter. C\195\180 \225\186\165y c\197\169ng l\195\160 m\225\187\153t tay ki\225\186\191m c\225\187\171 kh\195\180i c\195\179 kh\225\186\163 n\196\131ng s\225\187\173 d\225\187\165ng dao g\196\131m \196\145\225\187\131 tri\225\187\135t ti\195\170u nh\225\187\175ng hi\225\187\135u \225\187\169ng c\195\179 l\225\187\163i c\225\187\167a k\225\186\187 th\195\185.\n\nTrong s\225\187\145 c\195\161c h\225\187\141c sinh c\225\187\167a H\225\187\141c Vi\225\187\135n, Yen Xing \196\145\198\176\225\187\163c coi l\195\160 m\225\187\153t \196\145\195\160n ch\225\187\139 nghi\195\170m kh\225\186\175c, nh\198\176ng c\195\161 nh\195\162n c\195\180 \225\186\165y ch\225\187\137 mu\225\187\145n m\225\187\141i ng\198\176\225\187\157i \196\145\225\187\145i x\225\187\173 v\225\187\155i c\195\180 \225\186\165y nh\198\176 b\225\186\161n b\195\168. S\225\187\169c h\195\186t v\195\160 s\225\187\177 nghi\195\170m t\195\186c to\195\161t ra t\225\187\171 c\195\180 \225\186\165y \196\145\225\187\129u xu\225\186\165t ph\195\161t t\225\187\171 n\225\187\129n t\225\186\163ng gi\195\161o d\225\187\165c c\225\187\167a c\195\180 \225\186\165y; b\195\170n trong c\195\180 \225\186\165y c\197\169ng gi\225\187\145ng nh\198\176 nh\225\187\175ng c\195\180 g\195\161i kh\195\161c c\195\185ng \196\145\225\187\153 tu\225\187\149i, y\195\170u th\195\173ch tr\225\186\187 em v\195\160 c\195\161c lo\195\160i \196\145\225\187\153ng v\225\186\173t.\nNh\198\176ng ngay c\225\186\163 nh\225\187\175ng l\225\187\157i \196\145\225\187\147n th\225\187\149i v\225\187\129 c\195\180 \225\186\165y \196\145ang lan t\225\187\143a trong tr\198\176\225\187\157ng c\197\169ng kh\195\180ng th\225\187\131 ph\225\187\167 nh\225\186\173n s\225\187\177 th\225\186\173t r\225\186\177ng c\195\180 \225\186\165y l\195\160 m\225\187\153t th\225\187\167 l\196\169nh tr\225\187\157i sinh.\nL\195\160 b\225\186\173c th\225\186\167y v\225\187\129 v\195\181 \196\145\225\186\161o truy\225\187\129n th\225\187\145ng, c\195\180 \225\186\165y \196\145\195\163 ki\225\186\191m \196\145\198\176\225\187\163c r\225\186\165t nhi\225\187\129u ti\225\187\129n t\225\187\171 vi\225\187\135c d\225\186\161y d\225\187\151 con em c\225\187\167a c\195\161c gia \196\145\195\172nh gi\195\160u c\195\179, nh\198\176ng c\195\180 \225\186\165y \196\145\195\163 quy\195\170n g\195\179p t\225\186\165t c\225\186\163 s\225\187\145 ti\225\187\129n m\195\172nh ki\225\186\191m \196\145\198\176\225\187\163c cho H\225\187\141c Vi\225\187\135n v\195\160 x\195\163 h\225\187\153i.\196\144\225\187\147ng th\225\187\157i, c\195\180 \225\186\165y c\197\169ng \196\145\225\187\145i x\225\187\173 v\225\187\155i m\225\187\141i h\225\187\141c sinh kh\195\161c nh\198\176 nhau, b\225\186\165t k\225\187\131 h\225\187\141 l\195\160 ai.\nC\195\180 \225\186\165y tin r\225\186\177ng m\225\187\141i ng\198\176\225\187\157i c\225\186\167n ch\225\186\165p nh\225\186\173n s\225\187\177 kh\195\161c bi\225\187\135t c\225\187\167a nhau \196\145\225\187\131 \196\145\225\186\161t \196\145\198\176\225\187\163c s\225\187\177 h\195\178a \196\145\225\187\147ng ho\195\160n h\225\186\163o. Ni\225\187\129m tin c\225\187\167a c\195\180 \225\186\165y d\198\176\225\187\157ng nh\198\176 kh\195\180ng ph\225\186\163i l\195\160 ch\225\187\167 ngh\196\169a l\195\189 t\198\176\225\187\159ng su\195\180ng khi c\195\180 \225\186\165y \196\145\195\163 r\225\186\165t th\195\160nh c\195\180ng trong vai tr\195\178 l\195\163nh \196\145\225\186\161o c\225\187\167a H\225\187\153i \196\144\225\187\147ng, n\198\161i c\195\179 nh\225\187\175ng th\195\160nh vi\195\170n v\225\187\155i c\195\161 t\195\173nh ri\195\170ng hi\225\186\191m khi \196\145\225\187\147ng \195\189 v\225\187\155i nhau v\225\187\129 \196\145i\225\187\129u g\195\172 \196\145\195\179.\n"
