L14_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_POLICE_SOYEONG"
L15_1 = "Kang Soyoung, m\225\187\153t s\196\169 quan c\225\187\167a SWAT 4, l\195\160 m\225\187\153t l\195\173nh t\225\186\165n c\195\180ng t\225\186\167m xa h\225\187\151 tr\225\187\163, ng\198\176\225\187\157i \196\145\195\163 c\225\186\163i t\225\186\161o t\225\187\153i ph\225\186\161m b\225\186\177ng c\195\161ch \196\145\195\162m v\195\160o ch\195\186ng b\225\186\177ng m\225\187\153t chi\225\186\191c xe c\225\186\163nh s\195\161t. \n\nC\195\180 \225\186\165y l\195\160m vi\225\187\135c trong m\225\187\153t b\225\187\153 ph\225\186\173n \196\145\225\186\183c bi\225\187\135t chuy\195\170n x\225\187\173 l\195\189 b\225\187\141n t\225\187\153i ph\225\186\161m Counter. M\225\186\183c d\195\185 \196\145\225\187\153i c\225\187\167a c\195\180 \225\186\165y c\195\179 t\225\187\183 l\225\187\135 t\225\187\173 vong cao nh\225\186\165t, c\195\180 \225\186\165y \196\145\195\163 \225\187\159 v\225\187\139 tr\195\173 c\225\187\167a m\195\172nh l\195\162u h\198\161n b\225\186\165t k\225\187\179 ai v\195\160 gi\225\186\163i quy\225\186\191t v\195\180 s\225\187\145 v\225\187\165 \195\161n b\225\186\177ng k\225\187\185 n\196\131ng thi\225\187\135n x\225\186\161 v\195\160 suy lu\225\186\173n xu\225\186\165t s\225\186\175c c\225\187\167a m\195\172nh. Nh\198\176ng t\195\160i n\196\131ng th\225\187\177c s\225\187\177 c\225\187\167a c\195\180 \225\186\165y l\195\160 s\225\187\177 t\195\161o b\225\186\161o v\198\176\225\187\163t ra ngo\195\160i l\225\186\189 th\198\176\225\187\157ng gi\195\186p c\195\180 \225\186\165y b\225\186\175t t\225\187\153i ph\225\186\161m khi ch\195\186ng m\225\186\165t c\225\186\163nh gi\195\161c.\n\nH\225\186\167u h\225\186\191t m\225\187\141i ng\198\176\225\187\157i \196\145\225\187\129u kh\195\180ng hi\225\187\131u t\225\186\161i sao c\195\180 \225\186\165y kh\195\180ng th\225\187\131 tho\195\161t ra kh\225\187\143i v\225\187\139 tr\195\173 th\225\186\165p nh\198\176 v\225\186\173y v\225\187\155i th\195\160nh t\195\173ch tuy\225\187\135t v\225\187\157i \196\145\195\179. Nh\198\176ng c\195\180 \225\186\165y kh\195\180ng th\225\187\177c s\225\187\177 quan t\195\162m \196\145\225\186\191n vi\225\187\135c m\195\172nh \196\145\198\176\225\187\163c \196\145\225\187\145i x\225\187\173 nh\198\176 th\225\186\191 n\195\160o trong l\225\187\177c l\198\176\225\187\163ng. C\195\179 l\225\186\189 c\195\180 \225\186\165y kh\195\180ng \196\145\198\176\225\187\163c \225\187\167y vi\195\170n ch\195\186 \195\189 \196\145\225\186\191n v\195\172 \196\145\195\163 \196\145\195\162m qu\195\161 nhi\225\187\129u \195\180 t\195\180."
