L16_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_YG_SORIM"
L17_1 = "Han Sorim l\195\160 m\225\187\153t l\195\173nh t\225\186\165n c\195\180ng t\225\186\167m xa to\195\160n di\225\187\135n,\nt\225\186\165n c\195\180ng c\195\160ng nhanh khi c\195\160ng quen h\198\161n v\225\187\155i tr\225\186\173n chi\225\186\191n.c\195\160ngC\195\180 \225\186\165y l\195\160 th\225\187\167 l\196\169nh th\225\187\169 hai\nc\225\187\167a c\195\162u l\225\186\161c b\225\187\153 c\225\187\169u h\225\187\153 \196\145\225\187\153ng v\225\186\173t, Th\225\187\143 Tr\225\186\175ng.\nM\225\186\183c d\195\185 c\195\180 \225\186\165y gh\195\169t t\225\186\165t c\225\186\163 c\195\161c h\195\172nh th\225\187\169c ho\225\186\161t \196\145\225\187\153ng th\225\187\131 ch\225\186\165t,\nc\195\180 \225\186\165y h\225\187\141c r\225\186\165t nhanh. Trong b\195\160i\nhu\225\186\165n luy\225\187\135n m\195\180 ph\225\187\143ng t\195\161c chi\225\186\191n \196\145\225\186\167u ti\195\170n, c\195\180 \225\186\165y \196\145\195\163 \196\145\225\186\161t \196\145i\225\187\131m cao h\198\161n m\225\187\169c trung b\195\172nh c\225\187\167a binh l\195\173nh\ntrong vi\225\187\135c s\225\187\173 d\225\187\165ng v\197\169 kh\195\173 v\195\160 b\225\186\175n s\195\186ng, ch\225\187\137 v\225\187\155i\nki\225\186\191n \226\128\139\226\128\139th\225\187\169c c\195\180 \225\186\165y h\225\187\141c \196\145\198\176\225\187\163c khi quan s\195\161t nh\225\187\175ng ng\198\176\225\187\157i kh\195\161c.\nSorim lu\195\180n g\225\187\141i \196\144\225\187\153i tr\198\176\225\187\159ng Harim, b\225\187\159i v\195\172\nc\195\180 \225\186\165y \196\145\195\163 tr\225\187\159 th\195\160nh m\225\187\153t k\225\186\187 cu\225\187\147ng qu\195\162n s\225\187\177 th\195\180ng qua\nnhi\225\187\129u ph\198\176\198\161ng ti\225\187\135n truy\225\187\129n th\195\180ng bao g\225\187\147m c\225\186\163 truy\225\187\135n tranh.\nC\195\180 \225\186\165y \196\145ang s\225\187\145ng trong t\198\176\225\187\159ng t\198\176\225\187\163ng r\225\186\177ng c\195\180 \225\186\165y\nl\195\160 m\225\187\153t ng\198\176\225\187\157i l\195\173nh, nh\198\176ng c\195\180 \225\186\165y\ns\225\186\189 l\225\186\161i tr\225\187\159 th\195\160nh m\225\187\153t c\195\180 g\195\161i nh\195\186t nh\195\161t khi c\195\180 \225\186\165y lo l\225\186\175ng.\nT\198\176\198\161ng lai c\225\187\167a c\195\180 \225\186\165y kh\195\161 t\198\176\198\161i s\195\161ng v\195\172 c\195\180 \225\186\165y\nl\195\160 m\225\187\153t thi\195\170n t\195\160i lu\195\180n h\198\176\225\187\155ng v\225\187\129 nh\225\187\175ng g\195\172 c\195\180 \225\186\165y th\195\173ch."
