L5_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ZODIAC_PIONE"
L6_1 = "Hi\225\187\135p s\196\169 c\225\187\167a H\225\187\149 C\195\161p. Fione Lowell l\195\160 m\225\187\153t\nl\195\173nh ph\195\178ng v\225\187\135 h\225\187\151 tr\225\187\163 gi\195\186p t\196\131ng c\198\176\225\187\157ng\nkh\225\186\163 n\196\131ng ph\195\178ng th\225\187\167 c\225\187\167a \196\145\225\187\147ng minh.\nC\195\180 \225\186\165y l\195\160 \196\145\225\187\153i ph\195\179 c\225\187\167a c\195\161c Hi\225\187\135p s\196\169 Ho\195\160ng \196\144\225\186\161o.\nL\225\187\155n l\195\170n trong m\225\187\153t gia \196\145\195\172nh qu\195\162n nh\195\162n,\nc\195\180 \225\186\165y lu\195\180n v\225\187\175ng tin r\225\186\177ng k\225\187\183 lu\225\186\173t\nl\195\160 \196\145i\225\187\129u c\225\186\167n thi\225\186\191t \196\145\225\187\131 ki\225\187\131m so\195\161t m\225\187\153t nh\195\179m. Do \196\145\195\179, c\195\180 \225\186\165y nh\225\186\165n m\225\186\161nh\nvi\225\187\135c r\195\168n luy\225\187\135n th\198\176\225\187\157ng xuy\195\170n v\195\160 s\225\187\177 li\195\170m ch\195\173nh c\225\187\167a c\195\161 nh\195\162n,\n\196\145\225\187\147ng th\225\187\157i x\225\187\173 ph\225\186\161t nghi\195\170m kh\225\186\175c nh\225\187\175ng sai l\225\186\167m nh\225\187\143 nh\225\186\165t. C\195\161c hi\225\187\135p s\196\169 kh\195\161c r\225\186\165t\nc\196\131ng th\225\186\179ng v\225\187\155i th\195\161i \196\145\225\187\153 ngay th\225\186\179ng c\225\187\167a c\195\180 \225\186\165y,\nnh\198\176ng v\195\172 h\225\187\141 c\197\169ng nh\225\186\173n th\225\187\169c \196\145\198\176\225\187\163c\ntr\195\161ch nhi\225\187\135m n\225\186\183ng n\225\187\129 c\225\187\167a m\195\172nh,\nh\225\187\141 ch\225\186\165p thu\225\186\173n ph\198\176\198\161ng ph\195\161p c\225\187\167a c\195\180 \225\186\165y \225\187\159 m\225\187\153t m\225\187\169c \196\145\225\187\153 nh\225\186\165t \196\145\225\187\139nh.\nGia \196\145\195\172nh Lowell \196\145\225\186\183t r\225\186\165t nhi\225\187\129u k\225\187\179 v\225\187\141ng v\195\160o Fione v\195\160 mu\225\187\145n c\195\180 \225\186\165y h\225\186\161 g\225\187\165c\nEstherosa \196\145\225\187\131 t\225\187\177 m\195\172nh tr\225\187\159 th\195\160nh \196\145\225\187\153i tr\198\176\225\187\159ng.\nNh\198\176ng Fione t\195\180n tr\225\187\141ng Estherosa c\197\169ng nh\198\176 c\195\180 \225\186\165y\nt\195\180n tr\225\187\141ng k\225\187\183 lu\225\186\173t v\195\160 c\195\180 \225\186\165y h\195\160i l\195\178ng\nv\225\187\155i v\225\187\139 tr\195\173 \196\145\225\187\153i ph\195\179 hi\225\187\135n t\225\186\161i c\225\187\167a m\195\172nh.\n "
