L8_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_FRONTIER_LEE"
L9_1 = "Lee Dafoe l\195\160 m\225\187\153t l\195\173nh ph\195\178ng v\225\187\135\nc\195\179 k\225\187\185 n\196\131ng xu\225\186\165t s\225\186\175c khi ch\225\187\145ng l\225\186\161i nhi\225\187\129u k\225\186\187 th\195\185.\nC\195\161nh tay ph\225\186\163i, \196\145\198\176\225\187\163c bao ph\225\187\167 b\225\187\159i \195\161o gi\195\161p th\195\169p, \196\145\198\176\225\187\163c t\225\186\161o ra\nt\225\187\171 \196\144\225\187\147ng h\225\187\147 c\225\187\167a anh \225\186\165y. Anh \225\186\165y s\225\187\173 d\225\187\165ng n\195\179 nh\198\176 m\225\187\153t chi\225\186\191c khi\195\170n v\195\160 v\197\169 kh\195\173.\nLee \196\145\195\163 t\225\187\171ng l\195\160 m\225\187\153t v\195\181 s\196\169 quy\225\187\129n anh, nh\198\176ng anh \225\186\165y \196\145\195\163 m\225\186\165t\nc\195\161nh tay ph\225\186\163i khi g\225\186\183p ph\225\186\163i b\225\187\141n c\195\180n \196\145\225\187\147. Anh \225\186\165y\n\196\145\195\163 \196\145\195\161nh th\225\187\169c s\225\187\169c m\225\186\161nh c\225\187\167a m\195\172nh nh\198\176 m\225\187\153t Counter sau v\225\187\165 vi\225\187\135c.\nM\225\186\183c d\195\185 \196\145\195\163 \196\145\195\161nh m\225\186\165t \198\176\225\187\155c m\198\161 tr\225\187\159 th\195\160nh m\225\187\153t v\195\181 s\196\169 quy\225\187\129n anh,\nnh\198\176ng hi\225\187\135n t\225\186\161i anh \225\186\165y \196\145ang l\195\160m vi\225\187\135c t\225\186\161i Bi\195\170n Gi\225\187\155i v\225\187\155i m\225\187\153t m\225\187\165c ti\195\170u m\225\187\155i.\nLee \196\145ang c\195\179 k\225\186\191 ho\225\186\161ch x\195\162y d\225\187\177ng m\225\187\153t b\225\187\135nh vi\225\187\135n t\225\186\161i qu\195\170 nh\195\160\n\196\145\225\187\131 kh\195\180ng c\195\178n nh\225\187\175ng n\225\186\161n nh\195\162n nh\198\176 anh \225\186\165y n\225\187\175a.\nL\195\173nh \196\144\195\161nh Thu\195\170 Bi\195\170n Gi\225\187\155i v\225\186\171n l\195\160 m\225\187\153t nh\195\179m\nl\195\173nh \196\145\195\161nh thu\195\170 quy m\195\180 nh\225\187\143, \196\145i\225\187\129u \196\145\195\179 kh\195\180ng quan tr\225\187\141ng. Anh m\198\161 \198\176\225\187\155c tr\225\187\159 th\195\160nh\nm\225\187\153t v\195\181 s\196\169 quy\225\187\129n anh ngay c\225\186\163 trong m\225\187\153t ph\195\178ng t\225\186\173p t\225\187\145i t\196\131m, \225\186\169m m\225\187\145c. B\195\162y gi\225\187\157\nanh \225\186\165y \196\145\195\163 c\195\179 m\225\187\153t c\195\161nh tay m\225\187\155i, anh \225\186\165y c\195\179 th\225\187\131 l\195\160m b\225\186\165t c\225\187\169 \196\145i\225\187\129u g\195\172.\n"
