L9_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_FALLEN_ROSARIA"
L10_1 = "Rosaria le Friede l\195\160 \196\145\198\161n v\225\187\139 t\225\186\165n c\195\180ng t\225\186\167m xa to\195\160n di\225\187\135n, tung ra c\195\161c \196\145\195\178n t\225\186\165n c\195\180ng di\225\187\135n r\225\187\153ng m\225\186\161nh m\225\186\189 t\225\187\171 tr\195\170n kh\195\180ng trung.\n\nC\195\180 v\225\187\145n l\195\160 ch\225\187\167 s\225\187\159 h\225\187\175u \196\144\198\161n V\225\187\139 Th\195\161m T\225\187\173 Fallen Hawk n\225\187\149i ti\225\186\191ng v\225\187\155i kh\225\186\163 n\196\131ng t\195\172m ng\198\176\225\187\157i m\225\186\165t t\195\173ch, nhi\225\187\129u kh\195\161ch h\195\160ng \196\145\195\163 ch\225\187\169ng ki\225\186\191n c\225\186\163nh c\195\180 \196\145\225\187\145i x\225\187\173 v\225\187\155i nh\195\162n vi\195\170n c\225\187\167a m\195\172nh nh\198\176 n\195\180 l\225\187\135. Theo c\195\180 th\195\172 c\195\180 ch\225\187\137 \196\145ang ban ph\195\161t \198\161n hu\225\187\135 cho c\195\161c sinh v\225\186\173t h\195\168n k\195\169m h\198\161n, nh\225\187\175ng k\225\186\187 s\225\186\189 kh\195\180ng bi\225\186\191t m\225\187\165c \196\145\195\173ch cu\225\187\153c s\225\187\145ng c\225\187\167a m\195\172nh l\195\160 g\195\172 n\225\186\191u kh\195\180ng c\195\179 c\195\180.\n\nC\195\180 th\195\173ch quan s\195\161t h\195\160nh vi t\225\187\177 h\225\187\167y ho\225\186\161i v\195\160 phi l\195\189 c\225\187\167a lo\195\160i ng\198\176\225\187\157i v\195\160 c\225\187\177c k\225\187\179 th\195\173ch xem phim thu\225\187\153c th\225\187\131 lo\225\186\161i \"opera x\195\160 ph\195\178ng\" v\195\160o ban ng\195\160y. C\195\180 \196\145\225\186\183c bi\225\187\135t y\195\170u th\195\173ch b\225\187\153 phim \"The Bridge of Seduction\", M\195\185a 6, v\225\187\145n c\225\187\177c k\225\187\179 n\225\187\149i ti\225\186\191ng v\225\187\155i c\225\187\145t truy\225\187\135n v\195\180 nh\195\162n \196\145\225\186\161o v\195\160 g\195\162y tranh c\195\163i.\n\n\196\144\195\180i khi, c\195\180 s\225\186\189 \196\145i theo nh\195\162n vi\195\170n c\225\187\167a m\195\172nh trong c\195\161c cu\225\187\153c \196\145i\225\187\129u tra c\225\187\167a h\225\187\141, v\195\160 m\225\187\151i khi c\195\180 l\195\160m v\225\186\173y, nhi\225\187\129u v\225\187\165 vi\225\187\135c ph\195\161 ho\225\186\161i \196\145\225\187\139a ph\198\176\198\161ng b\195\173 \225\186\169n l\225\186\161i x\225\186\163y ra."
