L32_1 = "Dominic King Reginald l\195\160 \196\145\198\161n v\225\187\139 l\195\173nh ph\195\178ng v\225\187\135 c\195\160ng m\225\186\165t nhi\225\187\129u HP th\195\172 chi\225\186\191n \196\145\225\186\165u c\195\160ng h\196\131ng. \n\nTrong Cu\225\187\153c Chi\225\186\191n, Chu\225\186\169n T\198\176\225\187\155ng Reginald ph\225\187\165c v\225\187\165 d\198\176\225\187\155i quy\225\187\129n Trung T\198\176\225\187\155ng Antonov. Kh\195\180ng nhi\225\187\129u ng\198\176\225\187\157i bi\225\186\191t vi\225\187\135c n\195\160y, tuy nhi\195\170n, theo c\225\186\165p d\198\176\225\187\155i c\225\187\167a \195\180ng k\225\187\131 l\225\186\161i, vi\225\187\135c c\225\187\167a \195\180ng l\195\160 h\195\160nh \196\145\225\187\153ng t\225\187\171 trong b\195\179ng t\225\187\145i \196\145\225\187\131 v\195\180 hi\225\187\135u h\195\179a c\225\186\161m b\225\186\171y ch\195\173nh tr\225\187\139 v\195\160 \196\145\195\178n t\225\186\165n c\195\180ng nh\225\186\175m v\195\160o ng\198\176\225\187\157i c\225\186\165p tr\195\170n kh\195\180ng nh\195\162n nh\198\176\225\187\163ng c\225\187\167a \195\180ng.\n\nM\225\187\153t s\225\187\145s\225\187\173 gia qu\195\162n s\225\187\177 tin r\225\186\177ng Reginald ch\195\173nh l\195\160 l\195\189 do gi\195\186p Trung T\198\176\225\187\155ng t\225\186\161i v\225\187\139 l\195\162u \196\145\225\186\191n th\225\186\191; kh\195\180ng ph\225\186\163i v\195\172 s\225\187\177 nh\225\186\161y b\195\169n trong ch\195\173nh tr\225\187\139, m\195\160 c\195\178n v\195\172 kh\225\186\163 n\196\131ng chi\225\186\191n \196\145\225\186\165u, v\225\187\145n \196\145\195\163 gi\195\186p \195\180ng \196\145\195\163 nhi\225\187\129u l\225\186\167n tr\225\187\159 n\195\170n n\225\187\149i b\225\186\173t tr\195\170n chi\225\186\191n tr\198\176\225\187\157ng trong vai tr\195\178 b\195\160n tay ph\225\186\163i c\225\187\167a Trung T\198\176\225\187\155ng.\n\195\148ng l\195\160 ng\198\176\225\187\157i l\195\173nh t\225\187\171 trong ra ngo\195\160i, nh\198\176 di\225\187\135n m\225\186\161o ng\198\176\225\187\157i chi\225\186\191n s\196\169 c\225\187\167a \195\180ng cho th\225\186\165y. Tuy nhi\195\170n, m\225\187\153t b\195\161o c\195\161o c\225\187\167a L\225\187\177c L\198\176\225\187\163ng Th\225\187\145ng Nh\225\186\165t cho r\225\186\177ng \195\180ng tin t\198\176\225\187\159ng v\195\160o nh\225\186\173n th\225\187\169c c\225\187\167a b\225\186\163n th\195\162n \196\145\225\186\191n n\225\187\151i c\195\179 th\225\187\131 t\225\186\161o ra nhi\225\187\129u v\225\186\165n \196\145\225\187\129 m\225\187\155i."
