L32_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_SIXWING_LEE_JISOO"
L33_1 = "Lee Jisoo l\195\160 m\225\187\153t l\195\173nh h\225\187\151 tr\225\187\163 c\225\186\173n chi\225\186\191n chuy\195\170n v\225\187\129 c\195\161c lo\225\186\161i thu\225\186\173t nguy\225\187\129n r\225\187\167a, bao g\225\187\147m c\225\186\163 Gi\225\186\163m Ph\225\187\165c H\225\187\147i.\n\nL\195\160 m\225\187\153t th\195\160nh vi\195\170n c\225\187\167a t\225\187\149 ch\225\187\169c c\195\179 t\195\170n l\195\160 Six Wings, m\225\187\141i ng\198\176\225\187\157i th\198\176\225\187\157ng nh\195\172n th\225\186\165y c\195\180 \225\186\165y b\225\186\163o v\225\187\135 b\195\170n c\225\186\161nh th\225\187\167 l\196\169nh c\225\187\167a m\195\172nh, Na Yubin. Kh\195\180ng gi\225\187\145ng nh\198\176 nh\225\187\175ng th\195\160nh vi\195\170n kh\195\161c hi\225\186\191m khi l\225\187\153 di\225\187\135n tr\198\176\225\187\155c qu\225\186\167n ch\195\186ng. C\195\180 \225\186\165y l\195\160 m\225\187\153t ng\198\176\225\187\157i nguy hi\225\187\131m \196\145\195\163 t\225\187\171ng x\195\162m ph\225\186\161m v\195\178ng an ninh c\225\187\167a C\225\187\165c Qu\225\186\163n L\195\189 nhi\225\187\129u l\225\186\167n ch\225\187\137 b\225\186\177ng m\225\187\153t thanh ki\225\186\191m. L\195\160 Counter, c\195\161c kh\225\186\163 n\196\131ng c\225\187\167a c\195\180 \225\186\165y bao g\225\187\147m nh\225\187\175ng l\225\187\157i nguy\225\187\129n h\195\185ng m\225\186\161nh m\195\160 c\195\180 \225\186\165y th\198\176\225\187\157ng s\225\187\173 d\225\187\165ng th\195\180ng qua ki\225\186\191m thu\225\186\173t c\225\187\167a m\195\172nh \196\145\225\187\131 h\225\186\161 g\225\187\165c k\225\186\187 th\195\185.\nHi\225\187\135n c\195\180 \225\186\165y \196\145ang ho\225\186\161t \196\145\225\187\153ng ng\225\186\167m \225\187\159 v\196\131n ph\195\178ng ch\195\173nh ph\225\187\167, nh\198\176ng trong m\225\186\175t \196\145\225\187\147ng nghi\225\187\135p, c\195\180 \225\186\165y c\195\179 danh ti\225\186\191ng r\225\186\165t t\225\187\135 v\195\172 c\195\180 \225\186\165y lu\195\180n khi\225\186\191n c\195\180ng vi\225\187\135c tr\225\187\159 l\195\170n l\225\187\153n x\225\187\153n. \196\144\225\187\131 tr\195\161nh b\225\187\139 nghi ng\225\187\157, c\195\180 \225\186\165y, m\225\187\153t con ng\198\176\225\187\157i t\195\160i n\196\131ng, \196\145\195\163 c\225\187\145 g\225\186\175ng gi\225\186\163 v\225\187\157 l\195\160 m\225\187\153t ng\198\176\225\187\157i v\225\187\165ng v\225\187\129. Tr\225\187\171 \196\145i\225\187\129u \196\145\195\179 ra, c\195\178n l\195\189 do n\195\160o kh\195\161c?"
