L43_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_SCHOOL_CHAIR"
L44_1 = "Gh\225\186\191 an ninh, J.O.U.R., l\195\160 m\225\187\153t thi\225\186\191t b\225\187\139 b\225\186\163o v\225\187\135 t\225\186\167m xa \196\145\225\186\163m b\225\186\163o gi\225\186\165c ng\225\187\167 c\225\187\167a ng\198\176\225\187\157i l\195\161i kh\195\180ng b\225\187\139 gi\195\161n \196\145o\225\186\161n. N\225\186\191u n\195\179 nh\225\186\173n m\225\187\153t l\198\176\225\187\163ng s\195\161t th\198\176\198\161ng nh\225\186\165t \196\145\225\187\139nh v\195\160 Edith Twins t\225\187\137nh d\225\186\173y, n\195\179 s\225\186\189 bay l\195\170n kh\195\180ng trung v\195\160 tr\225\187\159 n\195\170n c\225\187\177c k\225\187\179 hung h\196\131ng.\n\nEdith Twins, nh\195\160 thi\225\186\191t k\225\186\191 c\225\187\167a J.O.U.R., l\195\160 th\195\160nh vi\195\170n c\225\187\167a H\225\187\153i \196\144\225\187\147ng H\225\187\141c Sinh H\225\187\141c Vi\225\187\135n, v\195\160 g\225\186\167n \196\145\195\162y \196\145\195\163 \196\145\198\176\225\187\163c Chi\225\186\191n Tranh T\198\176\198\161ng Lai tuy\225\187\131n d\225\187\165ng l\195\160m nh\195\160 nghi\195\170n c\225\187\169u c\225\186\165p cao danh d\225\187\177. C\195\180 g\195\161i t\225\187\171ng bi\225\186\191n \196\145\225\187\147 \196\145\225\186\161c trong nh\195\160 th\195\160nh nh\225\187\175ng v\225\186\173t d\225\187\165ng m\195\160 c\195\180 th\225\186\165y trong c\195\161c b\225\187\153 phim khoa h\225\187\141c vi\225\187\133n t\198\176\225\187\159ng v\195\160 ho\225\186\161t h\195\172nh \196\145\195\163 tr\225\187\159 th\195\160nh m\225\187\153t nh\195\160 khoa h\225\187\141c k\225\187\185 thu\225\186\173t thi\195\170n t\195\160i.\n Nh\198\176ng khi nh\225\187\175ng k\225\187\179 v\225\187\141ng c\225\187\167a ng\198\176\225\187\157i kh\195\161c v\225\187\129 c\195\180 khi\225\186\191n c\195\180 kh\195\180ng th\225\187\131 t\225\186\173n h\198\176\225\187\159ng gi\225\186\165c ng\225\187\167 tr\198\176a y\195\170u th\195\173ch, cu\225\187\145i c\195\185ng c\195\180 \196\145\195\163 ch\225\186\165p nh\225\186\173n l\225\187\157i \196\145\225\187\129 ngh\225\187\139 nh\225\186\173p h\225\187\141c c\225\187\167a H\225\187\141c Vi\225\187\135n v\195\160 b\225\187\143 ph\195\178ng th\195\173 nghi\225\187\135m c\225\187\167a m\195\172nh \196\145\225\187\131 b\225\186\175t \196\145\225\186\167u cu\225\187\153c s\225\187\145ng v\225\187\155i t\198\176 c\195\161ch l\195\160 m\225\187\153t h\225\187\141c sinh Counter L\225\187\155p D.\nNgay c\225\186\163 b\195\162y gi\225\187\157, c\195\180 \225\186\165y thi\225\186\191t k\225\186\191 robot bi\225\186\191n h\195\172nh cho Chi\225\186\191n Tranh T\198\176\198\161ng Lai nh\198\176 m\225\187\153t s\225\187\159 th\195\173ch, nh\198\176ng kh\195\180ng ai bi\225\186\191t cu\225\187\153c s\225\187\145ng c\225\187\167a ch\195\186ng ta c\195\179 th\225\187\131 ra sao n\225\186\191u c\195\180 \225\186\165y t\225\187\171 b\225\187\143 vi\225\187\135c ng\225\187\167 tr\198\176a v\195\160 t\225\186\173p trung v\195\160o nghi\195\170n c\225\187\169u."
