L13_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_YOO_MI_NA"
L14_1 = "Yoo Mina l\195\160 th\195\160nh vi\195\170n m\225\187\155i c\225\187\167a Fenrir. C\195\180 \225\186\165y l\195\160 m\225\187\153t chi\225\186\191n binh c\195\179 th\225\187\131 ti\195\170u di\225\187\135t k\225\186\187 th\195\185 t\225\187\171 xa b\225\186\177ng m\225\187\153t kh\225\186\169u s\195\186ng l\225\187\165c xung. C\195\180 \225\186\165y c\195\179 kh\225\186\163 n\196\131ng h\225\186\161 g\225\187\165c nhi\225\187\129u k\225\186\187 th\195\185 c\195\185ng l\195\186c b\225\186\177ng c\195\161ch s\225\187\173 d\225\187\165ng t\195\173nh n\196\131ng b\195\173 m\225\186\173t c\225\187\167a v\197\169 kh\195\173 c\225\187\167a m\195\172nh. M\225\186\183c d\195\185 c\195\180 \225\186\165y ch\198\176a t\225\187\171ng \196\145\198\176\225\187\163c \196\145\195\160o t\225\186\161o chi\225\186\191n \196\145\225\186\165u b\195\160i b\225\186\163n v\195\160 thi\225\186\191u ki\225\186\191n \226\128\139\226\128\139th\225\187\169c chuy\195\170n ng\195\160nh, nh\198\176ng C\195\180ng Ty Coffin l\195\160 c\195\180ng ty ch\225\187\167 qu\225\186\163n th\225\187\169 ba c\225\187\167a c\195\180 \225\186\165y.\nTheo m\225\187\153t c\225\187\153ng \196\145\225\187\147ng \225\186\169n danh, c\195\180 \225\186\165y \196\145\195\163 kh\195\180ng tu\195\162n l\225\187\135nh c\225\186\165p tr\195\170n t\225\186\161i n\198\161i l\195\160m vi\225\187\135c tr\198\176\225\187\155c \196\145\195\162y \196\145\225\187\131 th\225\187\131 hi\225\187\135n b\225\186\163n th\195\162n trong tr\225\186\173n chi\225\186\191n v\195\160 kh\225\187\159i \196\145\225\186\167u m\225\187\153t cu\225\187\153c bi\225\187\131u t\195\172nh v\197\169 trang khi c\195\161c kho\225\186\163n thanh to\195\161n c\225\187\167a c\195\180 \225\186\165y b\225\187\139 tr\195\172 ho\195\163n. Nh\225\187\175ng h\195\160nh vi li\225\187\129u l\196\169nh n\195\160y \196\145\198\176\225\187\163c cho l\195\160 do nh\225\187\175ng h\195\179a \196\145\198\161n y t\225\186\191 kh\225\187\149ng l\225\187\147 m\195\160 c\195\180 \225\186\165y \196\145ang ph\225\186\163i tr\225\186\163 cho gia \196\145\195\172nh, nh\198\176ng c\195\180 \225\186\165y ch\198\176a bao gi\225\187\157 l\195\170n ti\225\186\191ng v\225\187\129 v\225\186\165n \196\145\225\187\129 n\195\160y."
