L14_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CA_YOO_MI_NA"
L15_1 = "Yoo Mina, k\225\187\131 t\225\187\171 khi c\195\180 \225\186\165y th\225\187\169c t\225\187\137nh Nh\195\162n T\225\187\145 Qliphoth, \196\145\195\163 tr\225\187\159 n\195\170n m\225\186\161nh m\225\186\189 h\198\161n v\225\187\155i vai tr\195\178 l\195\160 L\195\173nh T\225\186\165n C\195\180ng, gi\225\187\157 \196\145\195\162y c\195\180 \225\186\165y c\195\179 th\225\187\131 vung ki\225\186\191m kh\195\180ng gi\225\187\155i h\225\186\161n. \n\nNgay c\225\186\163 sau tr\225\186\173n chi\225\186\191n \196\145\225\187\139nh m\225\187\135nh \196\145\195\179 v\225\187\155i nh\225\187\175ng Ng\198\176\225\187\157i Nh\195\162n B\225\186\163n, c\195\180 \225\186\165y v\225\186\171n \225\187\159 l\225\186\161i TASKFORCE, v\195\160 \196\145\195\163 tr\225\187\159 th\195\160nh m\225\187\153t th\195\160nh vi\195\170n k\225\187\179 c\225\187\177u trong \196\145\225\187\153i c\225\187\167a m\195\172nh, kh\195\161c h\225\186\179n m\225\187\153t t\195\162n binh kh\195\180ng bi\225\186\191t g\195\172 khi m\225\187\155i gia nh\225\186\173p. C\195\180 \225\186\165y c\197\169ng tho\195\161t ra kh\225\187\143i l\225\187\155p v\225\187\143 b\225\187\141c khi\225\186\191n c\195\180 \225\186\165y kh\195\180ng th\225\187\131 th\195\162n thi\225\186\191t v\225\187\155i nh\225\187\175ng ng\198\176\225\187\157i kh\195\161c \225\187\159 c\195\180ng ty l\195\186c ban \196\145\225\186\167u. Gi\225\187\157 \196\145\195\162y, c\195\180 \225\186\165y l\195\160 m\225\187\153t th\225\187\167 l\196\169nh g\198\176\198\161ng m\225\186\171u, t\225\186\165t c\225\186\163 c\195\161c th\195\160nh vi\195\170n trong nh\195\179m \196\145\225\187\129u \196\145\225\187\169ng v\225\187\129 ph\195\173a c\195\180 \225\186\165y. \nTuy nhi\195\170n, v\225\186\165n \196\145\225\187\129 chi ti\195\170u v\195\160 t\195\160i ch\195\173nh c\225\187\167a c\195\180 \225\186\165y v\225\186\171n kh\195\180ng thay \196\145\225\187\149i, c\195\180 \225\186\165y l\195\160m vi\225\187\135c ngay c\225\186\163 v\195\160o nh\225\187\175ng ng\195\160y ngh\225\187\137 v\195\160 mua nh\225\187\175ng h\225\187\153p th\225\187\169c \196\131n gi\195\161 r\225\186\187 t\225\186\161i c\195\161c c\225\187\173a h\195\160ng ti\225\187\135n l\225\187\163i. \nC\195\180 \225\186\165y kh\195\161 x\225\186\165u h\225\187\149 khi n\195\179i v\225\187\129 kh\195\173a c\225\186\161nh n\195\160y c\225\187\167a m\195\172nh. Xin \196\145\225\187\171ng b\195\172nh lu\225\186\173n g\195\172 v\225\187\129 v\195\173 ti\225\187\129n c\225\187\167a c\195\180 \225\186\165y."
