L38_1 = "\194\183 Ch\225\187\137 s\225\187\145 b\225\187\149 sung t\225\187\171 trang b\225\187\139, t\196\131ng c\225\186\165p v\195\160 t\196\131ng c\198\176\225\187\157ng ch\225\187\137 c\195\179 th\225\187\131 \196\145\198\176\225\187\163c \195\161p d\225\187\165ng m\225\187\153t ph\225\186\167n.\n\194\183 B\225\186\161n s\225\186\189 \196\145\198\176\225\187\163c gh\195\169p v\225\187\155i ng\198\176\225\187\157i d\195\185ng trong c\195\185ng khung \196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng v\225\187\155i b\225\186\161n.\n\194\183 N\225\186\191u \196\145\225\186\165u v\225\187\155i ng\198\176\225\187\157i d\195\185ng c\195\179 \196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng cao h\198\161n b\225\186\161n th\195\172 b\225\186\161n s\225\186\189 gi\195\160nh \196\145\198\176\225\187\163c nhi\225\187\129u \196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng h\198\161n v\195\160 m\225\186\165t \195\173t \196\145i\225\187\131m h\198\161n so v\225\187\155i b\195\172nh th\198\176\225\187\157ng.\n\194\183 N\225\186\191u b\225\186\161n \196\145\225\186\165u v\225\187\155i ng\198\176\225\187\157i d\195\185ng c\195\179 \196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng th\225\186\165p h\198\161n b\225\186\161n th\195\172 s\225\186\189 gi\195\160nh \196\145\198\176\225\187\163c \195\173t \196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng h\198\161n v\195\160 m\225\186\165t nhi\225\187\129u \196\145i\225\187\131m h\198\161n so v\225\187\155i b\195\172nh th\198\176\225\187\157ng.\n\194\183 Chi\225\186\191n th\225\186\175ng m\225\187\153t l\198\176\225\187\163ng \196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng nh\225\186\165t \196\145\225\187\139nh, b\225\186\161n s\225\186\189 \196\145\198\176\225\187\163c th\196\131ng l\195\170n gi\225\186\163i \196\145\225\186\165u cao h\198\161n.\n\194\183 Trong m\225\187\153t s\225\187\145 gi\225\186\163i \196\145\225\186\165u nh\225\186\165t \196\145\225\187\139nh, b\225\186\161n c\195\179 th\225\187\131 b\225\187\139 xu\225\187\145ng h\225\186\161ng n\225\186\191u \196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng t\225\187\165t xu\225\187\145ng d\198\176\225\187\155i y\195\170u c\225\186\167u \196\145i\225\187\131m t\225\187\145i thi\225\187\131u t\225\187\171 100 \196\145i\225\187\131m tr\225\187\159 l\195\170n.\n\194\183 \225\187\158 c\195\161c gi\225\186\163i \196\145\225\186\165u cao h\198\161n, b\225\186\161n c\195\179 th\225\187\131 b\225\187\139 xu\225\187\145ng h\225\186\161ng m\195\160 kh\195\180ng c\225\186\163nh b\195\161o tr\198\176\225\187\155c n\225\186\191u kh\195\180ng \196\145\195\161p \225\187\169ng \196\145i\225\187\129u ki\225\187\135n c\225\187\167a gi\225\186\163i.\n\194\183 N\225\186\191u b\225\186\161n c\225\187\145 t\195\172nh \196\145\225\187\131 thua Cu\225\187\153c Chi\225\186\191n X\225\186\191p H\225\186\161ng qu\195\161 nhi\225\187\129u l\225\186\167n \196\145\225\187\131 gi\225\186\163m \196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng th\195\172 \196\145i\225\187\131m c\225\187\167a b\225\186\161n s\225\186\189 kh\195\180ng t\225\187\165t xu\225\187\145ng d\198\176\225\187\155i ti\195\170u chu\225\186\169n Gh\195\169p Tr\225\186\173n hi\225\187\135n t\225\186\161i."
