L40_1 = "\194\183 Ch\225\187\137 s\225\187\145 b\225\187\149 sung t\225\187\171 trang b\225\187\139, t\196\131ng c\225\186\165p v\195\160 t\196\131ng c\198\176\225\187\157ng ch\225\187\137 c\195\179 th\225\187\131 \196\145\198\176\225\187\163c \195\161p d\225\187\165ng m\225\187\153t ph\225\186\167n.\n\194\183 B\225\186\161n ph\225\186\163i thi\225\186\191t l\225\186\173p ti\225\187\131u \196\145\225\187\153i Ph\195\178ng Th\225\187\167 th\195\172 m\225\187\155i \196\145\198\176\225\187\163c tham gia Tr\225\186\173n Chi\225\186\191n Chi\225\186\191n L\198\176\225\187\163c.\n  B\225\186\161n c\195\179 th\225\187\131 ch\225\187\141n v\195\160 \196\145\225\186\165u v\225\187\155i ti\225\187\131u \196\145\225\187\153i Ph\195\178ng Th\225\187\167 c\225\187\167a m\225\187\153t trong ba ng\198\176\225\187\157i d\195\185ng n\225\186\177m trong c\195\185ng khung \196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng v\225\187\155i b\225\186\161n.\n  C\195\161c tr\225\186\173n chi\225\186\191n chi\225\186\191n l\198\176\225\187\163c \196\145\198\176\225\187\163c th\225\187\177c hi\225\187\135n t\225\187\177 \196\145\225\187\153ng. \196\144\198\161n v\225\187\139 c\225\187\167a b\225\186\161n s\225\186\189 \196\145\198\176\225\187\163c tri\225\187\131n khai theo th\225\187\169 t\225\187\177 b\225\186\161n th\195\170m v\195\160o ti\225\187\131u \196\145\225\187\153i.\n\194\183 N\225\186\191u \196\145\225\186\165u v\225\187\155i ng\198\176\225\187\157i d\195\185ng c\195\179 \196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng cao h\198\161n b\225\186\161n th\195\172 b\225\186\161n s\225\186\189 gi\195\160nh \196\145\198\176\225\187\163c nhi\225\187\129u \196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng h\198\161n v\195\160 m\225\186\165t \195\173t \196\145i\225\187\131m h\198\161n so v\225\187\155i b\195\172nh th\198\176\225\187\157ng.\n\194\183 N\225\186\191u b\225\186\161n \196\145\225\186\165u v\225\187\155i ng\198\176\225\187\157i d\195\185ng c\195\179 \196\144i