L2_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_FUTURE_HARPY"
L3_1 = "Janus l\195\160 m\225\187\153t m\195\161y bay chi\225\186\191n \196\145\225\186\165u c\195\179 th\225\187\131 t\225\186\165n c\195\180ng k\225\186\187 th\195\185 t\225\187\171 tr\195\170n kh\195\180ng cho \196\145\225\186\191n khi nh\225\186\173n m\225\187\153t l\198\176\225\187\163ng s\195\161t th\198\176\198\161ng nh\225\186\165t \196\145\225\187\139nh. Sau \196\145\195\179 n\195\179 chuy\225\187\131n sang ch\225\186\191 \196\145\225\187\153 Janitor v\195\160 \196\145\195\161p xu\225\187\145ng m\225\186\183t \196\145\225\186\165t \196\145\225\187\131 ti\225\186\191p t\225\187\165c chi\225\186\191n \196\145\225\186\165u \225\187\159 ti\225\187\129n tuy\225\186\191n trong v\225\187\139 tr\195\173 ph\195\178ng th\225\187\167.\n\n   Nguy\195\170n m\225\186\171u c\225\187\167a m\225\187\153t robot bi\225\186\191n h\195\172nh g\225\186\167n \196\145\195\162y \196\145\198\176\225\187\163c ph\195\161t tri\225\187\131n b\225\187\159i Chi\225\186\191n Tranh T\198\176\198\161ng Lai, m\225\187\153t c\195\180ng ty n\225\187\149i ti\225\186\191ng v\225\187\155i c\195\180ng ngh\225\187\135 th\225\187\173 nghi\225\187\135m, \196\145\198\176\225\187\163c cho l\195\160 \196\145\195\163 t\195\173ch l\197\169y d\225\187\175 li\225\187\135u chi\225\186\191n \196\145\225\186\165u th\225\187\177c t\225\186\191 m\225\187\153t c\195\161ch b\195\173 m\225\186\173t tr\198\176\225\187\155c khi \196\145\198\176\225\187\163c gi\225\187\155i thi\225\187\135u cho c\195\180ng ch\195\186ng.\n\nNh\225\187\175ng kh\195\161ch h\195\160ng \196\145\195\163 xem c\195\161c bu\225\187\149i tr\195\172nh di\225\187\133n c\225\187\167a s\225\186\163n ph\225\186\169m n\195\160y d\198\176\225\187\157ng nh\198\176 tin r\225\186\177ng n\195\179 \196\145\225\187\167 \225\187\149n \196\145\225\187\139nh \196\145\225\187\131 \196\145\198\176\225\187\163c s\225\187\173 d\225\187\165ng ph\225\187\149 bi\225\186\191n. C\195\161c nh\195\160 nghi\195\170n c\225\187\169u m\195\160 th\225\187\177c s\225\187\177 ph\195\161t tri\225\187\131n n\195\179 th\195\172 kh\195\180ng nh\198\176 v\225\186\173y."
