L31_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALPHA_CHOI"
L32_1 = "Gabriel Jun K\225\186\187 Ph\225\186\161m Lu\225\186\173t X\225\186\165u Xa l\195\160\nm\225\187\153t ng\198\176\225\187\157i b\225\186\163o v\225\187\135 m\225\186\161nh m\225\186\189, n\195\162ng cao kh\225\186\163 n\196\131ng n\195\169 tr\195\161nh c\225\187\167a \196\145\225\187\147ng minh\nb\225\186\177ng ki\225\186\191m thu\225\186\173t \196\145\225\187\153c \196\145\195\161o c\225\187\167a m\195\172nh.\nAnh \225\186\165y \196\145\195\163 \196\145i kh\225\186\175p th\225\186\191 gi\225\187\155i v\195\160\nh\225\187\141c \196\145\198\176\225\187\163c nhi\225\187\129u k\225\187\185 n\196\131ng ki\225\186\191m thu\225\186\173t kh\195\161c nhau,\nnh\198\176ng kh\195\180ng ki\225\186\191m th\225\187\169c n\195\160o l\195\160m anh \225\186\165y h\195\160i l\195\178ng.\nV\195\172 v\225\186\173y, anh \225\186\165y \196\145\195\163 t\225\186\161o m\225\187\153t ki\225\186\191m th\225\187\169c m\225\187\155i c\225\187\167a ri\195\170ng m\195\172nh,\nch\225\187\137 sau m\225\187\153t th\195\161ng. Ki\225\186\191m Thu\225\186\173t B\225\186\165t \196\144\225\187\153ng\ncho ph\195\169p anh \225\186\165y ch\225\187\145ng l\225\186\161i k\225\186\187 th\195\185 t\225\187\171 m\225\187\141i ph\195\173a,\nnh\198\176ng anh \225\186\165y l\195\160 ng\198\176\225\187\157i duy nh\225\186\165t c\195\179 th\225\187\131 th\195\160nh th\225\186\161o n\195\179.\nHi\225\187\135n t\225\186\161i, anh \225\186\165y \196\145ang \196\145\195\179ng vai tr\195\178 l\195\160 Ng\198\176\225\187\157i Ph\195\161n X\195\169t c\225\187\167a C\195\161i \195\129c\n\196\145\225\187\131 duy tr\195\172 s\225\187\177 c\195\162n b\225\186\177ng c\225\187\167a th\225\186\191 gi\225\187\155i,\n\196\145i\225\187\129u m\195\160 anh \225\186\165y \196\145\195\163 nh\225\186\173n ra khi t\225\186\161o ra ki\225\186\191m thu\225\186\173t c\225\187\167a m\195\172nh.\n*Tuy\195\170n b\225\187\145 n\195\160y kh\195\180ng \196\145\198\176\225\187\163c x\195\161c nh\225\186\173n l\195\160 \196\145\195\186ng.\n\196\144\195\179 ch\225\187\137 l\195\160 m\225\187\153t tuy\195\170n b\225\187\145 c\195\161 nh\195\162n c\225\187\167a \196\145\225\187\145i t\198\176\225\187\163ng.\n"
