L49_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_FREEDOM_LIN"
L50_1 = "L\195\173nh t\225\186\165n c\195\180ng, t\196\131ng t\225\187\145c \196\145\225\187\153 t\196\131ng c\198\176\225\187\157ng\ncho \196\145\225\187\147ng minh b\225\186\177ng s\225\187\169c m\225\186\161nh b\195\173 \225\186\169n.\nS\225\187\145 ti\225\187\129n c\195\180 \225\186\165y r\225\186\163i xung quanh trong tr\225\186\173n chi\225\186\191n,\nh\195\172nh nh\198\176 c\195\179 in khu\195\180n m\225\186\183t c\225\187\167a ch\195\173nh c\195\180 tr\195\170n \196\145\195\179.\nGi\225\186\163 l\195\160m m\225\187\153t con s\195\179i \196\145\198\161n \196\145\225\187\153c,\nLin Xien c\195\178n l\195\162u m\225\187\155i c\195\179 th\225\187\131 tr\225\187\159 th\195\160nh l\195\173nh \196\145\195\161nh thu\195\170.\nTr\195\170n th\225\187\177c t\225\186\191, c\195\180 \225\186\165y l\195\160 con g\195\161i duy nh\225\186\165t c\225\187\167a m\225\187\153t doanh nh\195\162n v\196\169 \196\145\225\186\161i.\nC\195\180 \225\186\165y \196\145ang tr\225\187\145n kh\225\187\143i nh\195\160, v\195\172\nc\195\180 \225\186\165y mu\225\187\145n tr\225\187\159 th\195\160nh tay s\195\186ng c\225\187\171 kh\195\180i nh\225\186\165t\nnh\198\176 trong c\195\161c b\225\187\153 phim \196\144en. C\195\161c tr\225\187\163 l\195\189 c\225\187\167a c\195\180 \225\186\165y \196\145\195\163 \196\145\225\187\131 l\225\186\161i nh\225\186\173n x\195\169t\n\196\145\225\187\131 ai t\195\172m th\225\186\165y c\195\179 th\225\187\131 ch\196\131m s\195\179c c\195\180 \225\186\165y,\nv\195\172 c\195\180 \225\186\165y s\225\186\189 l\225\186\161i ch\225\186\161y n\225\186\191u \196\145\198\176\225\187\163c \196\145\198\176a v\225\187\129 nh\195\160.\n\196\144i\225\187\131m \196\145\225\186\183c bi\225\187\135t c\225\187\167a Lin Xien trong tr\225\186\173n chi\225\186\191n l\195\160\nn\195\179i c\195\162u c\225\187\173a mi\225\187\135ng c\225\187\167a c\195\180 \225\186\165y \226\128\148 \196\144\225\187\131 chuy\225\187\135n n\195\160y cho t\195\180i \226\128\148 v\195\160\nr\225\187\147i ng\195\163 xu\225\187\145ng tr\198\176\225\187\155c khi quay l\225\186\161i sau \196\145\195\179\nm\195\160 kh\195\180ng \196\145\225\187\131 l\225\186\161i s\225\186\185o. \196\144\195\179 th\225\187\177c s\225\187\177 l\195\160 m\225\187\153t k\225\187\185 n\196\131ng sinh t\225\187\147n tuy\225\187\135t v\225\187\157i,\nnh\198\176ng c\195\180 \225\186\165y t\225\187\171 ch\225\187\145i gi\225\186\163i th\195\173ch c\195\161ch th\225\187\177c hi\225\187\135n n\195\179\nv\195\172 c\195\180 \225\186\165y ngh\196\169 r\225\186\177ng n\195\179 kh\195\180ng ng\225\186\167u."
