L46_1 = "Claudia Nelson l\195\160 m\225\187\153t l\195\173nh h\225\187\151 tr\225\187\163\nc\195\179 th\225\187\131 b\225\186\163o v\225\187\135 v\195\160 ch\225\187\175a l\195\160nh cho nhi\225\187\129u \196\145\225\187\147ng minh th\195\180ng qua\nnh\225\187\175ng l\225\187\157i c\225\186\167u nguy\225\187\135n.\nC\195\180 \225\186\165y l\195\160 m\225\187\153t n\225\187\175 tu tr\225\186\187, ng\198\176\225\187\157i \196\145\195\163 tr\198\176\225\187\159ng th\195\160nh qua vi\225\187\135c\ngi\195\186p \196\145\225\187\161 ng\198\176\225\187\157i kh\195\161c. Khi \196\145\198\176\225\187\163c bi\225\186\191t r\225\186\177ng\nc\195\180 \225\186\165y \196\145\195\163 nh\225\186\173n \196\145\198\176\225\187\163c \196\144\225\187\147ng h\225\187\147, H\225\187\153i \196\145\225\187\147ng \196\145\195\163 b\225\187\145i r\225\187\145i\nli\225\187\135u \196\145i\225\187\129u n\195\160y c\195\179 ph\225\186\163i l\195\160 m\225\187\153t ph\195\169p m\195\160u hay kh\195\180ng.\nNgo\195\160i vi\225\187\135c l\195\160m vi\225\187\135c cho H\225\187\153i \196\144\225\187\147ng, c\195\180 \225\186\165y\nti\225\186\191p t\225\187\165c gi\195\186p \196\145\225\187\161 c\195\161c nh\195\160 th\225\187\157\nv\195\160 tr\225\186\161i tr\225\186\187 m\225\187\147 c\195\180i g\225\186\167n \196\145\195\179. C\195\161c gi\195\161o s\196\169 r\225\186\165t bi\225\186\191t \198\161n\ns\225\187\177 gi\195\186p \196\145\225\187\161 t\225\186\173n t\195\172nh c\225\187\167a c\195\180 \225\186\165y, nh\198\176ng h\225\187\141 kh\195\180ng bao gi\225\187\157\ncho ph\195\169p c\195\180 \225\186\165y v\195\160o b\225\186\191p. C\195\180 \225\186\165y l\195\160 ng\198\176\225\187\157i duy nh\225\186\165t\nkh\195\180ng bi\225\186\191t r\225\186\177ng c\195\161c m\195\179n \196\131n c\225\187\167a c\195\180 \225\186\165y\ng\195\162y ra t\225\187\149n th\198\176\198\161ng tinh th\225\186\167n cho ng\198\176\225\187\157i \196\131n."
