L21_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALPHA_CHOWON"
L22_1 = "Kim Chowon l\195\160 m\225\187\153t l\195\173nh b\225\186\175n t\225\187\137a c\225\187\167a C\225\186\163i C\195\161ch Alphatrix,\nng\198\176\225\187\157i c\195\179 th\225\187\131 nhanh ch\195\179ng t\195\161i s\225\187\173 d\225\187\165ng c\195\161c ch\225\187\169c n\196\131ng\n\196\145\198\176\225\187\163c c\195\160i \196\145\225\186\183t trong v\197\169 kh\195\173 c\225\187\167a m\195\172nh.\nC\195\180 \225\186\165y l\195\160 m\225\187\153t l\195\173nh \196\145\195\161nh thu\195\170 k\225\187\179 c\225\187\177u,\nng\198\176\225\187\157i \196\145\195\163 h\225\187\141c c\195\161ch s\196\131n V\225\186\173t Th\225\187\131 \196\130n M\195\178n tr\198\176\225\187\155c khi c\195\180 \225\186\165y h\225\187\141c s\225\187\145 h\225\187\141c. C\195\180 \225\186\165y\n\196\145\195\163 d\195\160nh h\198\161n n\225\187\173a cu\225\187\153c \196\145\225\187\157i c\225\187\167a m\195\172nh b\195\170n trong\nCounterside trong khi\ngi\195\186p t\195\172m ki\225\186\191m c\195\161c nh\195\179m tr\195\161i ph\195\169p b\195\170n ngo\195\160i\nranh gi\225\187\155i x\195\163 h\225\187\153i. C\195\179 l\225\186\189 v\195\172\nc\195\180 \225\186\165y c\195\179 m\225\187\153t cu\225\187\153c s\225\187\145ng kh\195\179 kh\196\131n, c\195\180 \225\186\165y kh\195\180ng bao gi\225\187\157 ph\225\186\163n \196\145\225\187\145i\nb\225\186\165t k\225\187\179 k\225\186\191 ho\225\186\161ch t\195\161c chi\225\186\191n ng\225\187\155 ng\225\186\169n n\195\160o m\195\160 ng\198\176\225\187\157i l\195\163nh \196\145\225\186\161o \196\145\198\176a ra.\nHi\225\187\135n c\195\180 \225\186\165y \196\145ang \196\145i h\225\187\141c \196\145\225\187\131 gi\195\186p c\225\186\163i thi\225\187\135n h\195\172nh \225\186\163nh c\195\180ng ty,\nnh\198\176ng c\195\180 \225\186\165y \196\145ang g\225\186\183p kh\195\179 kh\196\131n trong vi\225\187\135c h\195\178a nh\225\186\173p\nv\195\160o cu\225\187\153c s\225\187\145ng b\195\172nh th\198\176\225\187\157ng c\225\187\167a tu\225\187\149i teen. Tr\195\170n t\225\186\165t c\225\186\163, m\225\187\141i ng\198\176\225\187\157i \196\145\225\187\129u qu\195\161 l\225\187\139ch s\225\187\177\nv\225\187\155i c\195\180 \225\186\165y k\225\187\131 t\225\187\171 khi c\195\180 \225\186\165y d\195\185ng tay kh\195\180ng\nkh\225\187\145ng ch\225\186\191 m\225\187\153t t\195\170n t\225\187\153i ph\225\186\161m Counter \196\145\195\163 \196\145\225\187\153t nh\225\186\173p v\195\160o\ntr\198\176\225\187\157ng v\195\160 t\195\160n ph\195\161 m\225\187\141i th\225\187\169.\n"
