L39_1 = "Kim Chulsoo l\195\160 m\225\187\153t l\195\173nh ph\195\178ng v\225\187\135,\nng\198\176\225\187\157i ph\195\161 v\225\187\161 ph\195\178ng tuy\225\186\191n c\225\187\167a k\225\186\187 th\195\185 b\225\186\177ng v\195\181 thu\225\186\173t.\nM\225\187\153t nh\195\162n vi\195\170n v\196\131n ph\195\178ng b\195\172nh th\198\176\225\187\157ng trong qu\195\161 kh\225\187\169,\nanh \225\186\165y \196\145\195\163 s\225\187\145ng s\195\179t sau Th\225\186\163m H\225\187\141a \196\130n M\195\178n\nnh\225\187\157 \196\145\195\161nh th\225\187\169c s\225\187\169c m\225\186\161nh Counter c\225\187\167a m\195\172nh. Nh\225\187\175ng c\195\186 \196\145\195\161\n\196\145\195\161ng kinh ng\225\186\161c c\225\187\167a anh \225\186\165y \196\145\195\163 h\225\186\161 g\225\187\165c V\225\186\173t Th\225\187\131 \196\130n M\195\178n, v\195\160 \196\145\198\176\225\187\163c\nquay phim v\195\160 lan truy\225\187\129n. Ng\198\176\225\187\157i ta n\195\179i r\225\186\177ng\nanh \225\186\165y \196\145\195\163 v\195\180 th\225\187\169c sao ch\195\169p c\195\161c k\225\187\185 thu\225\186\173t\nt\225\187\171 m\225\187\153t tr\195\178 ch\198\161i \196\145i\225\187\135n t\225\187\173 m\195\160 anh \225\186\165y ch\198\161i th\225\187\157i th\198\161 \225\186\165u.\nAnh \225\186\165y \196\145\198\176\225\187\163c t\195\180n k\195\173nh nh\198\176 m\225\187\153t anh h\195\185ng tr\195\170n c\195\161c ph\198\176\198\161ng ti\225\187\135n truy\225\187\129n th\195\180ng,\nnh\198\176ng anh \225\186\165y b\225\187\139 sang ch\225\186\165n\ntrong m\225\187\153t th\225\187\157i gian.\nMay m\225\186\175n thay, anh \225\186\165y \196\145\195\163 ho\195\160n to\195\160n ph\225\187\165c h\225\187\147i\nv\195\160 quy\225\186\191t \196\145\225\187\139nh tr\225\187\159 l\225\186\161i l\195\160m vi\225\187\135c.\nThay v\195\172 tr\225\187\159 l\225\186\161i v\196\131n ph\195\178ng b\195\172nh th\198\176\225\187\157ng,\nanh \225\186\165y \196\145\195\163 n\225\187\153p \196\145\198\161n v\195\160o m\2