L8_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_POLICE_LEE_YUMI"
L9_1 = "Lee Yumi l\195\160 m\225\187\153t l\195\173nh ph\195\178ng v\225\187\135 c\225\187\167a SWAT 4, ng\198\176\225\187\157i ch\225\186\161y tr\195\170n chi\225\186\191n tuy\225\186\191n v\225\187\155i k\225\187\185 n\196\131ng tr\225\187\145n tr\195\161nh tuy\225\187\135t v\225\187\157i c\225\187\167a m\195\172nh.\n\nM\225\186\183c d\195\185 c\195\180 \225\186\165y l\195\160 s\196\169 quan c\225\186\163nh s\195\161t, c\195\180 \225\186\165y r\225\186\165t th\195\185 \196\145\225\187\139ch v\225\187\155i b\225\187\141n t\225\187\153i ph\225\186\161m n\195\170n c\195\180 \225\186\165y th\198\176\225\187\157ng xuy\195\170n vung ki\225\186\191m thay v\195\172 c\195\178ng tay h\225\187\141. H\195\160nh vi c\225\187\167a c\195\180 \225\186\165y \196\145\195\163 li\195\170n t\225\187\165c b\225\187\139 ch\225\187\137 tr\195\173ch b\225\187\159i c\195\161c ph\198\176\198\161ng ti\225\187\135n truy\225\187\129n th\195\180ng \196\145\225\186\161i ch\195\186ng, nh\198\176ng v\225\187\155i t\198\176 c\195\161ch l\195\160 Counter duy nh\225\186\165t trong l\225\187\177c l\198\176\225\187\163ng c\225\186\163nh s\195\161t c\195\179 t\225\187\183 l\225\187\135 b\225\186\175t gi\225\187\175 cao nh\225\186\165t, c\195\180 \225\186\165y kh\195\180ng th\225\187\131 b\225\187\139 \196\145\225\187\165ng \196\145\225\186\191n, ngay c\225\186\163 khi \196\145\195\179 l\195\160 c\225\186\165p tr\195\170n c\225\187\167a c\195\180. \196\144\225\187\147ng nghi\225\187\135p c\225\187\167a c\195\180 \225\186\165y, Kang Soyoung, c\197\169ng bi\225\186\191t \196\145i\225\187\129u n\195\160y v\195\160 th\198\176\225\187\157ng c\225\187\145 g\225\186\175ng \196\145\225\186\169y tr\195\161ch nhi\225\187\135m c\225\187\167a m\195\172nh cho Yumi. C\225\186\163 hai lu\195\180n c\195\163i v\195\163 v\225\187\155i nhau, nh\198\176ng khi \196\145\225\187\145i m\225\186\183t v\225\187\155i t\225\187\153i \195\161c, h\225\187\141 tr\225\187\159 th\195\160nh c\225\187\153ng s\225\187\177 \196\145\225\186\175c l\225\187\177c nh\225\186\165t.\n\nV\195\172 Yumi lu\195\180n b\225\186\173n r\225\187\153n ch\225\186\161y \196\145\225\186\191n hi\225\187\135n tr\198\176\225\187\157ng v\225\187\165 \195\161n, t\225\186\165t c\225\186\163 ch\225\187\167 ti\225\187\135m b\195\161nh trong khu v\225\187\177c \196\145\225\187\129u bi\225\186\191t m\225\186\183t c\195\180 \225\186\165y."
