L13_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_HB_CHOIENA"
L14_1 = "M\225\187\153t l\195\173nh h\225\187\151 tr\225\187\163 kh\195\180ng chi\225\186\191n \196\145\225\186\165u m\195\160 chuy\225\187\131n s\225\187\177 ch\195\186 \195\189 sang \196\145\225\187\147ng minh b\225\186\177ng c\195\161ch n\195\162ng cao \196\145\195\161ng k\225\187\131 kh\225\186\163 n\196\131ng c\225\187\167a h\225\187\141.\n\nChoi Ina l\195\160 m\225\187\153t n\225\187\175 doanh nh\195\162n, ng\198\176\225\187\157i t\225\187\171ng l\195\160m vi\225\187\135c trong ng\195\160nh gi\225\186\163i tr\195\173, nh\198\176ng g\225\186\167n \196\145\195\162y \196\145\195\163 ngh\225\187\137 vi\225\187\135c \196\145\225\187\131 kh\225\187\159i nghi\225\187\135p v\225\187\155i c\195\180ng ty NetTube ri\195\170ng. V\225\187\155i t\198\176 c\195\161ch l\195\160 CEO c\225\187\167a Tomorrow Entertainment, MCN c\225\187\167a nh\225\187\175ng ng\198\176\225\187\157i c\195\179 \225\186\163nh h\198\176\225\187\159ng nh\225\187\143, c\195\180 \225\186\165y c\197\169ng \196\145\195\179ng vai tr\195\178 nh\198\176 m\225\187\153t ng\198\176\225\187\157i qu\225\186\163n l\195\189 l\196\169nh v\225\187\177c \196\145\225\187\131 \196\145\225\186\163m b\225\186\163o th\195\160nh c\195\180ng c\225\187\167a D\225\187\177 \195\129n HRT BERRY. C\195\180 \225\186\165y r\225\186\165t nh\225\186\161y c\225\186\163m v\225\187\129 c\195\161ch c\195\180 \225\186\165y x\198\176ng h\195\180, v\195\160 nh\225\186\171n t\195\162m c\225\186\165m t\225\186\165t c\225\186\163 nh\225\187\175ng kh\195\161n gi\225\186\163 d\195\161m g\225\187\141i c\195\180 \225\186\165y l\195\160 Qu\195\189 b\195\160. \nTrong ng\195\160nh kinh doanh gi\225\186\163i tr\195\173 c\225\187\167a m\195\172nh, c\195\180 \225\186\165y l\195\160 m\225\187\153t ng\198\176\225\187\157i qu\225\186\163n l\195\189 tham c\195\180ng ti\225\186\191c vi\225\187\135c. C\195\180 th\195\160nh l\225\186\173p c\195\180ng ty ri\195\170ng c\225\187\167a m\195\172nh sau khi tranh c\195\163i v\225\187\155i c\225\186\165p tr\195\170n v\225\187\129 vi\225\187\135c ph\225\186\163i l\195\160m qu\195\161 nhi\225\187\129u vi\225\187\135c. Hi\225\187\135n t\225\186\161i, c\195\180 \225\186\165y \196\145ang b\225\186\173n r\225\187\153n v\225\187\155i c\195\161c th\195\160nh vi\195\170n HRT BERRY \196\145\225\187\131 t\225\187\149 ch\225\187\169c c\195\161c bu\225\187\149i ph\195\161t s\195\179ng tr\225\187\177c ti\225\186\191p c\225\187\167a h\225\187\141 v\225\187\155i ti\195\170u \196\145\225\187\129 Cu\225\187\153c s\225\187\145ng h\195\160ng ng\195\160y c\225\187\167a nh\225\187\175ng n\195\160ng Counter d\225\187\133 th\198\176\198\161ng."
