L7_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_ORCA_CHARLIE"
L8_1 = "Charlie Rockwood l\195\160 m\225\187\153t l\195\173nh ph\195\178ng v\225\187\135,\nng\198\176\225\187\157i ch\225\187\139u \196\145\225\187\177ng c\195\161c cu\225\187\153c t\225\186\165n c\195\180ng c\225\187\167a k\225\186\187 th\195\185 tr\198\176\225\187\155c khi\nph\225\186\163n c\195\180ng m\225\186\161nh m\225\186\189 b\225\186\177ng kh\225\186\169u s\195\186ng ti\225\187\131u li\195\170n c\225\187\167a m\195\172nh.\nAnh ta l\195\160 m\225\187\153t l\195\173nh \196\145\195\161nh thu\195\170 \225\187\173a tr\195\178 chuy\225\187\135n m\195\160\nb\225\186\161n s\225\186\189 g\225\186\183p t\225\186\161i m\225\187\153t qu\195\161n bar \196\145\225\187\139a ph\198\176\198\161ng. Anh \225\186\165y l\195\160 m\225\187\153t c\225\186\167u th\225\187\167 b\195\179ng \196\145\195\161 \225\187\159 tr\198\176\225\187\157ng \196\145\225\186\161i h\225\187\141c. M\225\187\153t ng\195\160y n\225\187\141,\nCharlie g\225\186\183p m\225\187\153t ng\198\176\225\187\157i l\195\173nh \196\145\195\161nh thu\195\170 t\225\186\161i m\225\187\153t qu\195\161n bar,\nnh\225\187\175ng c\195\162u chuy\225\187\135n c\225\187\167a anh ta \196\145\195\163 khi\225\186\191n anh \225\186\165y ngay l\225\186\173p t\225\187\169c thu d\225\187\141n \196\145\225\187\147 \196\145\225\186\161c\nv\195\160 r\225\187\157i kh\225\187\143i k\195\189 t\195\186c x\195\161. \196\144\195\163 tr\225\186\163i qua qu\195\161 tr\195\172nh\nhu\225\186\165n luy\225\187\135n kh\225\186\175c nghi\225\187\135t v\195\160 cu\225\187\153c s\225\187\145ng chung,\nCharlie c\195\179 v\225\186\187 gi\225\187\145ng\nm\225\187\153t l\195\173nh \196\145\195\161nh thu\195\170 h\198\161n l\195\160 m\225\187\153t c\225\186\167u th\225\187\167 b\195\179ng \196\145\195\161.\nAnh \225\186\165y nghe \196\145\198\176\225\187\163c nh\225\187\175ng tin \196\145\225\187\147n\nv\225\187\129 h\225\187\163p \196\145\225\187\147ng sinh l\225\187\157i phi l\195\189 nh\198\176ng ch\198\176a bao gi\225\187\157 \196\145\225\186\161t \196\145\198\176\225\187\163c th\195\160nh c\195\180ng. Nh\198\176ng anh \225\186\165y v\225\186\171n \196\145ang m\198\161\ntr\195\186ng s\225\187\145 \196\145\225\187\153c \196\145\225\186\175c. C\195\179 l\225\186\189 \196\145\195\179 l\195\160 l\195\189 do\nt\225\186\161i sao anh \225\186\165y kh\195\180ng bao gi\225\187\157 b\225\187\139 \196\145e d\225\187\141a tr\195\170n chi\225\186\191n tr\198\176\225\187\157ng.\n"
