L18_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALT_XIAOLIN"
L19_1 = "L\195\160 ng\198\176\225\187\157i tr\225\186\187 nh\225\186\165t trong \196\145\225\187\153i, \196\145\225\187\131 b\195\185 \196\145\225\186\175p cho v\195\179c d\195\161ng nh\225\187\143 b\195\169 c\225\187\167a m\195\172nh, Xiao Lin lu\195\180n l\195\160m ch\225\187\167 v\225\187\139 tr\195\173 b\225\186\175n t\225\187\137a.\n\nKh\225\186\163 n\196\131ng ki\225\187\131m so\195\161t \196\145i\225\187\135n sinh h\225\187\141c cho ph\195\169p c\195\180 \225\186\165y th\225\187\177c hi\225\187\135n nh\225\187\175ng ph\195\161t b\225\186\175n ch\195\173nh x\195\161c b\225\186\165t k\225\187\131 m\225\187\165c ti\195\170u \196\145ang di chuy\225\187\131n nhanh \196\145\225\186\191n \196\145\195\162u. Trong m\225\187\153t l\225\186\167n t\195\161c chi\225\186\191n, c\195\180 \225\186\165y ho\195\160n th\195\160nh xu\225\186\165t s\225\186\175c vai tr\195\178 trinh s\195\161t, n\225\186\175m b\225\186\175t ho\225\186\161t \196\145\225\187\153ng c\225\187\167a k\225\186\187 \196\145\225\187\139ch v\195\160 thu th\225\186\173p th\195\180ng tin. Nh\225\187\175ng n\225\187\151 l\225\187\177c c\225\187\167a c\195\180 \225\186\165y \196\145\195\163 \196\145\195\179ng g\195\179p r\225\186\165t nhi\225\187\129u v\195\160o t\225\187\183 l\225\187\135 th\195\160nh c\195\180ng nhi\225\187\135m v\225\187\165 cao c\225\187\167a Ti\225\187\131u \196\144\225\187\153i ALT.\n\nC\195\180 \225\186\165y ch\225\187\167 y\225\186\191u s\225\187\173 d\225\187\165ng m\225\187\153t kh\225\186\169u s\195\186ng b\225\186\175n t\225\187\137a ch\225\187\145ng v\225\186\173t ch\225\186\165t, n\198\161i c\195\180 \225\186\165y g\225\186\175n th\195\170m m\225\187\153t ph\225\187\165 ki\225\187\135n m\225\187\155i m\225\187\151i khi ho\195\160n th\195\160nh s\225\187\169 m\225\187\135nh. C\195\180 \225\186\165y tuy\195\170n b\225\187\145 r\225\186\177ng n\195\179 gi\195\186p c\195\180 \225\186\165y c\225\186\163i thi\225\187\135n hi\225\187\135u su\225\186\165t c\225\187\167a b\225\186\163n th