L17_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ZODIAC_ARIUS"
L18_1 = "Hi\225\187\135p s\196\169 c\225\187\167a B\225\186\163o B\195\172nh. Arius Esquede l\195\160\nm\225\187\153t l\195\173nh h\225\187\151 tr\225\187\163 h\225\187\147i m\195\161u, ng\198\176\225\187\157i h\225\187\147i ph\225\187\165c cho \196\145\225\187\147ng minh v\195\160 ban cho h\225\187\141 c\195\161c\nr\195\160o ch\225\186\175n b\225\186\177ng n\198\176\225\187\155c th\195\161nh ch\225\187\169a \196\145\225\187\177ng \195\189 ch\195\173 c\225\187\167a c\195\180 \225\186\165y.\nM\225\186\183c d\195\185 l\195\160 Counter, c\195\180 \225\186\165y c\195\179 th\225\187\131 ch\225\186\165t\ny\225\186\191u h\198\161n ng\198\176\225\187\157i b\195\172nh th\198\176\225\187\157ng.\nNgay c\225\186\163 tr\198\176\225\187\155c khi th\225\187\169c t\225\187\137nh s\225\187\169c m\225\186\161nh c\225\187\167a m\195\172nh, c\195\180 \225\186\165y \196\145\195\163 c\195\179 m\225\187\153t c\198\161 th\225\187\131 m\225\187\143ng manh\nkhi\225\186\191n c\195\180 \225\186\165y kh\195\180ng th\225\187\131 \196\145i d\225\186\161o b\195\170n ngo\195\160i.\nC\195\180 \225\186\165y l\195\160 con g\195\161i c\225\187\167a m\225\187\153t ng\198\176\225\187\157i \196\145\195\160n \195\180ng gi\195\160u c\195\179, ng\198\176\225\187\157i t\195\160i tr\225\187\163\ncho c\195\161c Hi\225\187\135p s\196\169 Ho\195\160ng \196\144\225\186\161o, nh\198\176ng c\195\180 \225\186\165y \196\145\195\163 khao kh\195\161t tr\225\187\159 th\195\160nh m\225\187\153t trong s\225\187\145 h\225\187\141 t\225\187\171 l\195\162u.\nNgay sau khi c\195\180 \225\186\165y th\225\187\169c t\225\187\137nh s\225\187\169c m\225\186\161nh c\225\187\167a m\195\172nh, c\195\180 \225\186\165y \196\145\195\163 gia nh\225\186\173p Hi\225\187\135p s\196\169 v\225\187\155i hy v\225\187\141ng\nc\195\180 \225\186\165y c\195\179 th\225\187\131 \196\145i v\195\160o th\225\186\191 gi\225\187\155i \196\145\225\187\131 gi\195\186p \196\145\225\187\161 ng\198\176\225\187\157i kh\195\161c.\nV\195\172 t\195\173nh t\195\178 m\195\178 b\225\186\169m sinh, \196\145i\225\187\129u m\195\160 kh\195\180ng ai nh\225\186\173n ra\nkhi c\195\180 \225\186\165y \196\145ang h\225\187\147i ph\225\187\165c s\225\187\169c kh\225\187\143e \225\187\159 nh\195\160,\nc\195\161c th\195\160nh vi\195\170n kh\195\161c lu\195\180n quan t\195\162m\nv\225\187\129 s\225\187\177 an to\195\160n c\225\187\167a con g\195\161i ng\198\176\225\187\157i b\225\186\163o tr\225\187\163 c\225\187\167a h\225\187\141, ng\198\176\225\187\157i lu\195\180n bi\225\186\191n m\225\186\165t. M\225\186\183t kh\195\161c, c\195\180 \225\186\165y mong mu\225\187\145n c\195\161c hi\225\187\135p s\196\169 kh\195\161c s\225\186\189 ng\225\187\171ng nh\195\172n\nv\195\160o c\195\180 \225\186\165y nh\198\176 m\225\187\153t ng\198\176\225\187\157i c\225\186\167n b\225\186\163o v\225\187\135, m\195\160 l\195\160 m\225\187\153t hi\225\187\135p s\196\169 c\195\179 th\225\187\131 d\225\187\177a v\195\160o.\n "
