L44_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_VATICAN_CINDY"
L45_1 = "Cindy Looper l\195\160 m\225\187\153t ng\198\176\225\187\157i ti\195\170n phong,\nng\198\176\225\187\157i chi\225\186\191n \196\145\225\186\165u trong khi ch\225\187\175a b\225\187\135nh cho b\225\186\163n th\195\162n. M\195\161y c\198\176a\n\196\145\198\176\225\187\163c t\225\186\161o ra t\225\187\171 \196\144\225\187\147ng h\225\187\147 \196\145\195\161nh c\225\186\175p\n\195\189 ch\195\173 kh\195\161ng c\225\187\177 c\225\187\167a n\225\186\161n nh\195\162n.\nN\225\187\175 tu nh\225\187\143 n\195\160y \196\145\198\176\225\187\163c t\195\172m th\225\186\165y\ntrong m\225\187\153t gi\195\161o ph\195\161i k\195\173n v\225\187\155i t\198\176 c\195\161ch l\195\160 ng\198\176\225\187\157i s\225\187\145ng s\195\179t duy nh\225\186\165t.\nKhi c\195\180 \196\145\198\176\225\187\163c t\195\172m th\225\186\165y, c\195\180 \225\186\165y \196\145\195\163 ghi l\225\186\161i nhi\225\187\129u\nb\225\187\153 phim Kinh d\225\187\139 trong VHS.\n\196\144i\225\187\129u tra th\195\170m cho th\225\186\165y r\225\186\177ng\nnh\225\187\175ng b\225\187\153 phim n\195\160y \196\145\195\163 g\195\179p ph\225\186\167n r\225\186\165t l\225\187\155n\ntrong vi\225\187\135c ph\195\161t tri\225\187\131n nh\195\162n c\195\161ch c\225\187\167a Cindy.\nC\195\180 \225\186\165y th\198\176\225\187\157ng b\225\187\143 qua c\195\161c d\225\187\139ch v\225\187\165 v\195\160\nr\225\186\165t k\195\169m trong vi\225\187\135c c\225\186\167u nguy\225\187\135n. Nh\198\176ng khi\nchi\225\186\191n \196\145\225\186\165u v\225\187\155i k\225\186\187 th\195\185 c\225\187\167a Ch\195\186a, c\195\180 \225\186\165y \196\145\195\163 th\225\187\131 hi\225\187\135n nh\225\187\175ng k\225\187\185 n\196\131ng xu\225\186\165t ch\195\186ng.\nC\195\180 \225\186\165y t\225\187\177 tin r\225\186\177ng ti\225\186\191ng g\225\186\167m\nc\225\187\167a chi\225\186\191c c\198\176a m\195\161y c\225\187\167a c\195\180 \225\186\165y \196\145\195\179ng vai tr\195\178 nh\198\176 m\225\187\153t b\195\160i th\195\161nh ca."
