L17_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_YG_HOJIN"
L18_1 = "Cho Hojin l\195\160 m\225\187\153t l\195\173nh t\225\186\165n c\195\180ng t\225\186\167m xa to\195\160n di\225\187\135n,\nng\198\176\225\187\157i b\195\185 \196\145\225\186\175p cho vi\225\187\135c thi\225\186\191u kh\225\186\163 n\196\131ng chi\225\186\191n \196\145\225\186\165u b\225\186\177ng s\225\187\177 may m\225\186\175n.\nC\195\180 \225\186\165y kh\195\180ng bao gi\225\187\157 b\225\187\143 qua nh\225\187\175ng ng\198\176\225\187\157i g\225\186\183p r\225\186\175c r\225\187\145i,\n\196\145i\225\187\129u n\195\160y \196\145\195\163 khi\225\186\191n c\195\180 \225\186\165y tham gia c\195\162u l\225\186\161c b\225\187\153 c\225\187\169u h\225\187\153 \196\145\225\187\153ng v\225\186\173t, Th\225\187\143 Tr\225\186\175ng.\nGi\225\187\157 c\195\180 \225\186\165y \196\145ang c\225\187\145 g\225\186\175ng h\225\186\191t s\225\187\169c \196\145\225\187\131 v\225\187\171a \196\145\225\186\191n tr\198\176\225\187\157ng v\225\187\171a gi\225\186\163i c\225\187\169u \196\145\225\187\153ng v\225\186\173t.\nTrong Th\225\187\143 Tr\225\186\175ng, c\195\180 \225\186\165y l\195\160 th\195\160nh vi\195\170n v\225\187\165ng v\225\187\129\nv\195\160 l\195\160 ng\198\176\225\187\157i ph\225\187\165 tr\195\161ch \196\145\225\187\147 \196\131n nh\225\186\185.\nCho \196\145\225\186\191n nay, c\195\180 \225\186\165y \196\145\195\163 ng\196\131n ch\225\186\183n h\198\161n 100 tr\198\176\225\187\157ng h\225\187\163p\nc\195\179 th\225\187\131 d\225\186\171n \196\145\225\186\191n h\225\187\135 qu\225\186\163 d\195\162n s\225\187\177,\nnh\198\176ng th\225\186\173t b\195\173 \225\186\169n t\225\186\161i sao nh\225\187\175ng tai n\225\186\161n nh\198\176 v\225\186\173y\nlu\195\180n x\225\186\163y ra xung quanh c\195\180 \225\186\165y.\nC\195\180 \225\186\165y nh\225\186\173n \196\145\198\176\225\187\163c \196\144\225\187\147ng h\225\187\147 c\225\187\167a c\195\180 \225\186\165y khi c\195\178n tr\225\186\187,\nnh\198\176ng kh\195\180ng l\195\162u k\225\187\131 t\225\187\171 khi c\195\180 \225\186\165y nh\225\186\173n ra r\225\186\177ng\nc\195\180 \225\186\165y th\225\187\177c s\225\187\177 l\195\160 m\225\187\153t Counter."
