L25_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_FOX_STINGER"
L26_1 = "M\225\187\153t l\195\173nh b\225\186\175n t\225\187\137a chuy\195\170n ti\195\170u di\225\187\135t c\195\161c m\225\187\165c ti\195\170u tr\195\170n kh\195\180ng.\nH\225\187\141 s\225\187\173 d\225\187\165ng t\195\170n l\225\187\173a \196\145\225\186\165t \196\145\225\187\145i kh\195\180ng \196\145\225\187\131 b\225\186\163o v\225\187\135 b\225\186\167u tr\225\187\157i cho \196\145\225\187\147ng minh.\nH\225\187\141 bao g\225\187\147m nh\225\187\175ng ng\198\176\225\187\157i l\195\173nh \196\145\195\163 s\225\187\145ng s\195\179t\nsau c\195\161c \196\145\225\187\163t b\225\186\175n ph\195\161 trong cu\225\187\153c n\225\187\153i chi\225\186\191n\nho\225\186\183c c\195\161c cu\225\187\153c t\225\186\165n c\195\180ng tr\195\170n kh\195\180ng c\225\187\167a c\195\161c V\225\186\173t Th\225\187\131 \196\130n M\195\178n.\nDo sang ch\225\186\165n, h\225\187\141 kh\195\180ng th\225\187\131 \225\187\159 l\195\162u\ntrong nh\195\160 v\195\160 ph\225\186\163i th\198\176\225\187\157ng xuy\195\170n ki\225\187\131m tra b\225\186\167u tr\225\187\157i\nngay c\225\186\163 khi \196\145ang tr\195\178 chuy\225\187\135n.\nS\225\187\177 \195\161m \225\186\163nh v\225\187\129 l\225\187\177c l\198\176\225\187\163ng ph\195\178ng kh\195\180ng c\225\187\167a h\225\187\141\ng\225\186\167n nh\198\176 kh\225\187\155p v\225\187\155i c\195\161c AI \196\145\198\176\225\187\163c ph\195\161t tri\225\187\131n cho m\225\187\165c \196\145\195\173ch n\195\160y.\nG\225\186\167n \196\145\195\162y h\225\187\141 \196\145\195\163 y\195\170u c\225\186\167u x\195\162y d\225\187\177ng\ndoanh tr\225\186\161i c\225\187\167a h\225\187\141 tr\195\170n m\195\161i nh\195\160 c\225\187\167a c\195\180ng ty."
