L26_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_FOX_ANTIAIR"
L27_1 = "M\225\186\183c d\195\185 chuy\195\170n t\225\186\165n c\195\180ng ph\195\178ng kh\195\180ng,\nl\195\173nh t\225\186\165n c\195\180ng t\225\186\167m xa n\195\160y c\195\179 th\225\187\131 \196\145\198\176\225\187\163c s\225\187\173 d\225\187\165ng \196\145\225\187\131 ch\225\187\145ng l\225\186\161i b\225\186\165t c\225\187\169 th\225\187\169 g\195\172.\n\nN\195\179 l\195\160 m\225\187\153t kh\225\186\169u s\195\186ng ph\195\178ng kh\195\180ng t\225\187\177 h\195\160nh\n\196\145\195\163 \196\145\198\176\225\187\163c s\225\187\173 d\225\187\165ng t\225\187\171 gi\225\187\175a Th\225\186\191 k\225\187\183 20.\n\196\144\198\176\225\187\163c trang b\225\187\139 b\225\187\145n s\195\186ng m\195\161y 23mm,\nn\195\179 c\195\179 kh\225\186\163 n\196\131ng ti\195\170u di\225\187\135t c\195\161c m\225\187\165c ti\195\170u tr\195\170n m\225\186\183t \196\145\225\186\165t\nc\197\169ng nh\198\176 c\195\161c m\225\187\165c ti\195\170u tr\195\170n kh\195\180ng. Radar \196\145\198\176\225\187\163c l\225\186\175p \196\145\225\186\183t\n\225\187\159 ph\225\186\167n tr\195\170n gi\195\186p \196\145\225\187\161 r\225\186\165t nhi\225\187\129u cho C\195\161o Fennec\nv\225\187\155i s\225\187\177 thi\225\186\191u h\225\187\165t thi\225\186\191t b\225\187\139 gi\195\161m s\195\161t c\225\187\167a h\225\187\141.\nV\195\172 gi\195\161p c\225\187\167a xe y\225\186\191u n\195\170n vi\225\187\135c giao tranh m\225\187\153t m\195\172nh c\195\179 th\225\187\131 r\225\186\165t t\195\160n kh\225\187\145c. T\195\161c chi\225\186\191n\nv\225\187\155i c\195\161c \196\145\198\161n v\225\187\139 b\225\187\153 binh n\225\186\191u c\195\179 th\225\187\131."
