L28_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ZODIAC_LIV"
L29_1 = "Hi\225\187\135p s\196\169 c\225\187\167a Thi\195\170n B\195\172nh. Liv Allen l\195\160\nl\195\173nh ti\195\170n phong xua \196\145u\225\187\149i k\225\186\187 th\195\185\nb\225\186\177ng s\225\187\169c ch\225\187\139u \196\145\225\187\177ng v\195\180 t\225\186\173n c\225\187\167a m\195\172nh.\nC\195\180 \225\186\165y tr\195\180ng gi\225\187\145ng nh\198\176 m\225\187\153t tomboy lu\195\180n mu\225\187\145n ch\198\161i \196\145\195\185a,\nv\195\160 c\195\180 \225\186\165y th\225\187\177c s\225\187\177 h\195\160nh \196\145\225\187\153ng nh\198\176 v\225\186\173y,\nnh\198\176ng c\195\180 \225\186\165y c\197\169ng l\195\160 m\225\187\153t hi\225\187\135p s\196\169 ch\195\173nh ngh\196\169a,\nng\198\176\225\187\157i kh\195\180ng bao gi\225\187\157 quay l\198\176ng l\225\186\161i v\225\187\155i k\225\186\187 y\225\186\191u.\nNh\225\187\175ng ng\198\176\225\187\157i trong gia \196\145\195\172nh Allen cho r\225\186\177ng\ns\225\187\177 h\198\176\225\187\155ng d\225\186\171n c\195\179 k\225\187\183 lu\225\186\173t\nv\195\160 s\225\187\177 gi\195\161o d\225\187\165c c\225\187\167a h\225\187\141 \196\145\195\163 gi\195\186p c\195\180 \225\186\165y tr\225\187\159 th\195\160nh\nm\225\187\153t hi\225\187\135p s\196\169 th\225\187\177c th\225\187\165. Tr\225\187\155 tr\195\170u thay, kh\195\180ng ai\ntrong s\225\187\145 c\195\161c Hi\225\187\135p s\196\169 Ho\195\160ng \196\144\225\186\161o kh\195\161c th\225\186\165y\nc\195\180 \225\186\165y tham gia c\195\161c l\225\187\155p h\225\187\141c hi\225\187\135p s\196\169 k\225\187\131 c\225\186\163\nkhi c\195\180 \225\186\165y c\195\178n l\195\160 m\225\187\153t h\225\187\153 v\225\187\135.\nNh\198\176ng khi th\225\186\165y c\195\180 \225\186\165y d\225\187\133 d\195\160ng s\225\187\173 d\225\187\165ng Quy\225\187\129n tr\198\176\225\187\163ng c\225\187\167a Lira,\nm\225\187\153t v\197\169 kh\195\173 m\195\160 tr\225\187\141ng l\198\176\225\187\163ng d\225\187\177a v\195\160o s\225\187\177 \195\161c \196\145\225\187\153c c\225\187\167a ng\198\176\225\187\157i s\225\187\173 d\225\187\165ng n\195\179,\nng\198\176\225\187\157i ta kh\195\180ng th\225\187\131 kh\195\180ng ngh\196\169 r\225\186\177ng\nc\195\180 \225\186\165y \196\145\198\176\225\187\163c sinh ra v\225\187\155i tr\195\161i tim c\225\187\167a m\225\187\153t hi\225\187\135p s\196\169.\n "
