L18_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SCHOOL_C_PENCIL"
L19_1 = "Mika\226\152\133Star l\195\160 m\225\187\153t L\195\173nh H\225\187\151 Tr\225\187\163 s\225\187\173 d\225\187\165ng nh\225\187\175ng tr\195\178 \225\186\163o thu\225\186\173t k\225\187\179 di\225\187\135u \196\145\225\187\131 qu\225\186\165y r\225\187\145i v\195\160 l\195\160m suy y\225\186\191u k\225\186\187 th\195\185.\n\n   V\225\187\155i kh\195\161t v\225\187\141ng tr\225\187\159 th\195\160nh ph\195\161p s\198\176 v\196\169 \196\145\225\186\161i nh\225\186\165t th\225\186\191 k\225\187\183, c\195\180 \225\186\165y \196\145\225\186\161i di\225\187\135n cho nh\225\187\175ng Counter c\225\187\167a H\225\187\141c Vi\225\187\135n \225\187\167ng h\225\187\153 ch\225\187\167 ngh\196\169a phi chi\225\186\191n tranh. C\195\180 kh\225\186\179ng \196\145\225\187\139nh r\225\186\177ng \198\176\225\187\155c m\198\161 c\225\187\167a m\225\187\141i ng\198\176\225\187\157i ph\225\186\163i \196\145\198\176\225\187\163c t\195\180n tr\225\187\141ng, v\195\160 kh\195\180ng ph\225\186\163i t\225\186\165t c\225\186\163 c\195\161c Counter \196\145\225\187\129u c\225\186\167n t\225\186\173p trung v\195\160o k\225\187\185 n\196\131ng chi\225\186\191n \196\145\225\186\165u th\225\187\131 ch\225\186\165t. \196\144\195\162y h\225\186\179n l\195\160 l\195\189 do t\225\186\161i sao Ch\225\187\167 T\225\187\139ch H\225\187\141c Sinh, ng\198\176\225\187\157i tin t\198\176\225\187\159ng v\195\160o s\225\187\177 h\195\178a h\225\187\163p, \196\145\195\163 ch\225\187\141n c\195\180 \225\186\165y v\195\160o H\225\187\153i \196\144\225\187\147ng H\225\187\141c Sinh.\n   V\195\160 ch\225\187\137 v\195\172 c\195\180 \225\186\165y tin v\195\160o ch\225\187\167 ngh\196\169a phi chi\225\186\191n tranh, \196\145i\225\187\129u \196\145\195\179 kh\195\180ng c\195\179 ngh\196\169a l\195\160 c\195\180 \225\186\165y y\225\186\191u \196\145u\225\187\145i. Ph\195\169p thu\225\186\173t c\225\187\167a c\195\180 \225\186\165y, th\225\187\169 m\195\160 c\195\180 \225\186\165y \196\145\195\163 \196\145\198