L3_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GUILTY_S_MAY"
L4_1 = "May l\195\160 L\195\173nh H\225\187\151 Tr\225\187\163 c\195\179 th\225\187\131 t\225\187\145i \196\145a h\195\179a t\225\187\183 l\225\187\135 s\225\187\145ng s\195\179t c\225\187\167a c\195\161c \196\145\225\187\147ng minh xung quanh th\195\180ng qua HP v\195\160 kh\225\186\163 n\196\131ng h\225\187\151 tr\225\187\163 c\225\187\167a c\195\180 \225\186\165y. M\225\187\153t \196\145\225\187\169a tr\225\186\187 m\225\187\147 c\195\180i trong chi\225\186\191n tranh v\195\160 C\198\176\225\187\155p Bi\225\187\131n S\225\187\169a. V\225\186\187 ngo\195\160i nh\225\187\143 nh\225\186\175n, xinh x\225\186\175n khi\225\186\191n ng\198\176\225\187\157i kh\195\161c kh\195\180ng th\225\187\131 ng\225\187\157 \196\145\225\186\191n s\225\187\169c m\225\186\161nh si\195\170u ph\195\160m c\225\187\167a c\195\180 \225\186\165y, th\225\187\169 s\225\187\169c m\225\186\161nh c\195\179 th\225\187\131 khi\225\186\191n c\195\180 \225\186\165y n\195\169m c\225\186\163 m\225\187\153t c\195\161i m\225\187\143 neo d\225\187\133 d\195\160ng. C\195\180 \225\186\165y c\197\169ng c\195\179 th\225\187\131 tri\225\187\135u h\225\187\147i c\195\161c sinh v\225\186\173t bi\225\187\131n. Tin t\198\176\225\187\159ng v\195\160o nguy\195\170n t\225\186\175c h\195\160nh \196\145\225\187\153ng tr\198\176\225\187\155c v\195\160 suy ngh\196\169 sau, c\195\180 \225\186\165y th\198\176\225\187\157ng l\195\180i k\195\169o nh\225\187\175ng C\198\176\225\187\155p Bi\225\187\131n S\225\187\169a kh\195\161c tham gia c\195\161c h\195\160nh vi b\225\187\145c \196\145\225\187\147ng c\225\187\167a m\195\172nh. Trong Trang B\225\187\139 T\225\187\153i \195\129c -Strive-, sau khi ph\225\186\167n m\225\187\129m m\195\180 ph\225\187\143ng \196\145\198\176\225\187\163c thi\225\186\191t k\225\186\191, c\195\180 \225\186\165y tr\225\187\159 n\195\170n tr\198\176\225\187\159ng th\195\160nh h\198\161n so v\225\187\155i nh\225\187\175ng c\195\180ng vi\225\187\135c tr\198\176\225\187\155c \196\145\195\162y. \196\144i\225\187\129u \196\145\195\179 khi\225\186\191n ng\198\176\225\187\157i h\195\162m m\225\187\153 c\225\187\167a c\195\180 \225\186\165y ng\225\186\161c nhi\195\170n. "
