L38_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GUILTY_C_RAMLETHAL"
L39_1 = "Ramlethal Valentine l\195\160 m\225\187\153t L\195\173nh T\225\186\165n C\195\180ng chuy\195\170n t\225\186\165n c\195\180ng combo t\225\186\167m g\225\186\167n c\225\187\177c m\225\186\161nh. C\195\180 \225\186\165y l\195\160 m\225\187\153t trong nh\225\187\175ng d\225\186\161ng s\225\187\145ng gi\225\187\145ng con ng\198\176\225\187\157i \196\145\198\176\225\187\163c g\225\187\141i l\195\160 Valentines v\195\160 \196\145\198\176\225\187\163c giao nhi\225\187\135m v\225\187\165 ti\195\170u di\225\187\135t lo\195\160i ng\198\176\225\187\157i. C\195\180 \225\186\165y \196\145\195\163 t\225\187\171ng th\225\187\177c hi\225\187\135n m\225\187\135nh l\225\187\135nh c\225\187\167a m\195\172nh m\225\187\153t c\195\161ch m\195\161y m\195\179c tr\198\176\225\187\155c khi c\195\180 \225\186\165y g\225\186\183p con ng\198\176\225\187\157i v\195\160 bi\225\186\191t \196\145\198\176\225\187\163c c\225\186\163m gi\195\161c c\195\179 c\225\186\163m x\195\186c l\195\160 nh\198\176 th\225\186\191 n\195\160o. C\195\180 \225\186\165y \196\145\195\163 \196\145\225\187\169ng v\225\187\129 ph\195\173a nh\195\162n lo\225\186\161i k\225\187\131 t\225\187\171 \196\145\195\179. Ramlethal, ng\198\176\225\187\157i c\195\179 th\225\186\191 gi\225\187\155i quan h\225\187\147n nhi\195\170n nh\198\176 m\225\187\153t \196\145\225\187\169a tr\225\186\187, s\225\186\189 h\195\178a nh\225\186\173p ngay v\225\187\155i nh\225\187\175ng nh\195\162n vi\195\170n v\225\187\165ng v\225\187\129 trong x\195\163 h\225\187\153i. "
L37_1[1] = L38_1
L37_1[2] = L39_1
