L39_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GUILTY_M_INO"
L40_1 = "I-NO l\195\160 m\225\187\153t L\195\173nh B\225\186\175n T\225\187\137a t\225\186\165n c\195\180ng AoE t\225\187\171 xa. C\195\180 \225\186\165y c\195\179 th\225\187\131 th\225\187\149i bay k\225\186\187 th\195\185 \196\145ang t\225\187\155i \196\145\225\187\131 b\225\186\163o v\225\187\135 b\225\186\163n th\195\162n v\195\160 c\195\179 kh\225\186\163 n\196\131ng ch\225\187\145ng l\225\186\161i c\195\161c \196\145\198\161n v\225\187\139 bay m\225\187\153t c\195\161ch m\225\186\161nh m\225\186\189.\nC\195\179 v\225\186\187 th\195\162n thi\225\187\135n, h\198\176\225\187\155ng ngo\225\186\161i v\195\160 ham h\225\187\141c h\225\187\143i, nh\198\176ng c\195\180 \225\186\165y th\225\187\177c s\225\187\177 l\195\160 m\225\187\153t ng\198\176\225\187\157i c\195\180 \196\145\225\187\153c, coi th\198\176\225\187\157ng nh\225\187\175ng ng\198\176\225\187\157i kh\195\161c v\195\160 c\195\180ng khai th\195\185 \196\145\225\187\139ch v\225\187\155i nh\225\187\175ng ng\198\176\225\187\157i m\195\160 c\195\180 \225\186\165y c\225\186\163m th\225\186\165y b\225\187\139 \196\145e d\225\187\141a. M\225\186\183c d\195\185 c\195\180 \225\186\165y n\225\186\177m trong danh s\195\161ch m\195\180 ph\225\187\143ng, nh\198\176ng c\195\180 \225\186\165y kh\195\180ng ph\225\186\163i l\195\160 m\225\187\153t l\225\187\177a ch\225\187\141n l\195\189 t\198\176\225\187\159ng \196\145\225\187\131 ch\198\161i theo \196\145\225\187\153i v\195\172 s\225\187\159 th\195\173ch thao t\195\186ng v\195\160 h\195\160nh h\225\186\161 ng\198\176\225\187\157i kh\195\161c. Danh t\195\173nh th\225\187\177c s\225\187\177 c\225\187\167a c\195\180 l\195\160 Magical Foci, m\225\187\153t d\225\186\161ng s\225\187\145ng gi\225\186\163 \196\145\198\176\225\187\163c t\225\186\161o ra t\225\187\171 mong mu\225\187\145n c\225\187\167a con ng\198\176\225\187\157i v\225\187\129 m\225\187\153t ng\195\160y mai t\198\176\198\161i s\195\161ng h\198\161n trong c\195\161c cu\225\187\153c Th\225\186\173p T\225\187\177 Chinh. M\225\186\183t n\195\160y c\225\187\167a c\195\180 \225\186\165y \196\145\195\163 \196\145\198\176\225\187\163c ph\225\186\163n \195\161nh trong Counter/L\195\173nh Thi\225\186\191t Gi\195\161p m\195\180 ph\225\187\143ng. "
