L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_1_INTERLUDE_3"
L6_1 = "Ph\198\176\198\161ng ti\225\187\135n truy\225\187\129n th\195\180ng \196\145\225\187\129u \196\145\225\187\147ng \195\189 l\195\160 v\225\187\139 CEO kh\195\179 hi\225\187\131u c\225\187\167a Jehuty Biotech \196\145ang c\225\187\145 t\195\172nh t\225\186\161o ra m\225\187\153t h\195\172nh \225\186\163nh b\195\173 \225\186\169n. \196\144\198\176\225\187\163c c\195\180ng nh\225\186\173n l\195\160 Doanh Nh\195\162n C\225\187\167a N\196\131m \225\187\159 Charade, anh \225\186\165y \196\145\195\163 n\225\187\151 l\225\187\177c \196\145\195\161ng k\225\187\131 \196\145\225\187\131 c\225\186\163i thi\225\187\135n h\195\172nh \225\186\163nh c\195\180ng ty b\225\186\177ng c\195\161ch th\195\186c \196\145\225\186\169y ch\198\176\198\161ng tr\195\172nh c\225\187\169u tr\225\187\163 y t\225\186\191 \225\187\159 c\195\161c khu v\225\187\177c b\225\187\139 thi\225\187\135t th\195\178i."
