L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_2_2"
L8_1 = "Gi\195\161m M\225\187\165c Elcano l\195\160 m\225\187\153t trong nh\225\187\175ng k\225\186\187 \196\145\195\160o t\225\186\169u trong v\225\187\165 \195\161n v\198\176\225\187\163t ng\225\187\165c l\225\187\155n. M\225\186\183c d\195\185 kh\195\180ng ai bi\225\186\191t ch\225\186\175c ch\225\186\175n h\225\186\175n ta g\195\162y qu\225\187\185 th\225\186\191 n\195\160o, nh\198\176ng r\195\181 r\195\160ng l\195\160 h\225\186\175n ta \196\145\195\163 t\225\186\173p h\225\187\163p \196\145\198\176\225\187\163c m\225\187\153t s\225\187\145 ng\198\176\225\187\157i cu\225\187\147ng t\195\173n theo Hi\225\187\135p H\225\187\153i Ti\195\170n Tri Magellan. H\225\186\175n ph\225\186\163i b\225\187\139 b\225\186\175t ngay l\225\186\173p t\225\187\169c."
