L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_2_INTERLUDE_3"
L10_1 = "C\195\179 \196\145i\225\187\129u g\195\172 \196\145\195\179 kh\195\179 hi\225\187\131u v\225\187\129 vi\225\187\135n tr\225\187\163 y t\225\186\191 c\225\187\167a Jehuty Biotech. Th\225\187\145ng k\195\170 cho th\225\186\165y nh\225\187\175ng khu v\225\187\177c m\195\160 \196\145o\195\160n c\225\187\169u tr\225\187\163 \196\145\225\186\191n c\195\179 t\225\187\183 l\225\187\135 ng\198\176\225\187\157i m\225\186\165t t\195\173ch cao h\198\161n so v\225\187\155i m\225\187\169c trung b\195\172nh c\225\187\167a khu v\225\187\177c. \196\144\195\179 l\195\160 m\225\187\153t s\225\187\177 tr\195\185ng h\225\187\163p ng\225\186\171u nhi\195\170n h\198\161i \196\145\195\161ng ng\225\187\157, kh\195\180ng ph\225\186\163i sao?"
