L11_1 = "SI_SKIN_DESC_NKM_UNIT_C_ORCA_1BIRTHDAY"
L12_1 = "V\225\186\173t Th\225\187\131 \196\130n M\195\178n, t\195\180i ph\225\186\163i gi\225\186\191t ch\195\186ng!... L\195\186c n\195\160o c\197\169ng th\225\186\191, nh\198\176ng c\195\180 \225\186\165y \196\145\195\163 quy\225\186\191t \196\145\225\187\139nh t\225\186\161m ngh\225\187\137 ng\198\161i m\225\187\153t ng\195\160y. Ch\225\186\179ng ai mu\225\187\145n chi\225\186\191n \196\145\225\186\165u trong khi m\225\187\141i ng\198\176\225\187\157i \196\145ang \196\131n ti\225\187\135c c\225\186\163. \196\144\195\163 \196\145\225\186\191n l\195\186c s\196\131n l\195\185ng m\225\186\165y m\195\179n \196\145\225\187\147 ng\225\187\141t ch\225\186\163y n\198\176\225\187\155c mi\225\186\191ng r\225\187\147i!\n\n<color=#ffd34c>Kh\195\180ng. C\195\161i n\195\160y l\195\160 c\225\187\167a t\195\180i!... Ch\195\160, v\225\186\173y ch\225\187\137 m\225\187\153t mi\225\186\191ng th\195\180i nh\195\169.</color>"
