L12_1 = "SI_SKIN_DESC_NKM_UNIT_C_ALPHA_JIA_1BIRTHDAY"
L13_1 = "C\195\180 \225\186\165y kh\195\180ng ph\225\186\163i l\195\160 m\225\187\153t b\195\180ng hoa trong nh\195\160 k\195\173nh nh\198\176 suy ngh\196\169 c\225\187\167a nhi\225\187\129u ng\198\176\225\187\157i. C\195\180 \225\186\165y s\225\186\189 kh\195\180ng h\195\169o \195\186a ngay c\225\186\163 khi ra kh\225\187\143i nh\195\160 k\195\173nh. \196\144\225\187\171ng c\195\179 th\225\187\173 g\195\162y s\225\187\177 v\195\172 s\225\186\189 b\225\187\139 s\225\187\169t \196\145\225\186\167u m\225\186\187 tr\195\161n th\195\180i. Tr\198\176\225\187\155c m\225\187\153t vi\195\170n ng\225\187\141c qu\195\189, ch\225\187\137 \196\145\198\176\225\187\163c ph\195\169p nh\195\172n t\225\187\171 xa ch\225\187\169 kh\195\180ng \196\145\198\176\225\187\163c ph\195\169p ch\225\186\161m v\195\160o.\n\n<color=#ffd34c>T\195\180i kh\195\180ng ngh\196\169 r\225\186\177ng ng\195\160i s\225\186\189 \196\145\225\186\191n. \196\144\198\176\225\187\163c r\225\187\147i, gi\225\187\157 ch\195\186ng ta vui ch\198\161i th\195\180i nh\225\187\137?</color> "
