L13_1 = "SI_SKIN_DESC_NKM_UNIT_CA_YOO_MI_NA_1BIRTHDAY"
L14_1 = "C\195\180 \225\186\165y c\195\179 l\225\186\189 \196\145\195\163 tr\195\180i d\225\186\161t v\195\160 tr\225\186\163i qua nhi\225\187\129u bi\225\186\191n c\225\187\145, nh\198\176ng s\225\186\189 kh\195\180ng bao gi\225\187\157 thay \196\145\225\187\149i.\nGi\225\187\157 c\195\180 \225\186\165y c\197\169ng bi\225\186\191t m\195\172nh \196\145ang \196\145i \196\145\195\162u. Tuy nhi\195\170n, c\195\180 \225\186\165y d\198\176\225\187\157ng nh\198\176 kh\195\180ng bi\225\186\191t th\198\176\225\187\159ng th\225\187\169c m\225\187\153t b\225\187\175a ti\225\187\135c nh\198\176 th\225\186\191 n\195\160o. Ch\225\186\175c \196\145\195\160nh tr\195\180ng c\225\186\173y v\195\160o \195\180ng ch\225\187\167 th\195\180i.\n\n<color=#ffd34c>\195\148i, xin l\225\187\151i. T\195\180i th\225\186\165y m\225\187\141i ng\198\176\225\187\157i \196\145ang n\225\186\175m tay nhau, n\195\170n t\195\180i ngh\196\169 m\195\172nh c\197\169ng n\195\170n l\195\160m th\225\186\191 ch\196\131ng? </color>"
