L12_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_FUTURE_MA_LOAN"
L13_1 = "\196\144\198\176\225\187\163c di\225\187\133n gi\225\186\163i t\225\187\171 m\225\187\153t \196\145o\225\186\161n tr\195\173ch trong t\225\186\161p ch\195\173 c\225\187\167a Ti\225\186\191n S\196\169 Ember.\nCh\225\186\191 \196\145\225\187\153 chi\225\186\191n \196\145\225\186\165u n\195\160y cho ph\195\169p Horizon \196\145\195\179ng vai tr\195\178 t\225\186\165n c\195\180ng tr\195\170n kh\195\180ng, g\195\162y s\195\161t th\198\176\198\161ng t\198\176\198\161ng \225\187\169ng v\225\187\155i \196\145i\225\187\131m tr\195\186ng \196\145\195\173ch c\225\187\167a m\225\187\165c ti\195\170u.\nD\225\187\177a tr\195\170n ph\195\162n t\195\173ch \196\145\195\161ng tin c\225\186\173y, Cold Case s\225\187\145 137 c\195\179 th\225\187\131 \196\145\195\163 \196\145\198\176\225\187\163c thi\225\186\191t k\225\186\191 nh\198\176 m\225\187\153t ph\198\176\198\161ng ti\225\187\135n h\225\187\153 t\225\187\145ng c\195\179 kh\225\186\163 n\196\131ng th\225\187\177c hi\225\187\135n c\195\186 nh\225\186\163y kh\195\180ng gian v\195\160 \196\145i\225\187\129u h\198\176\225\187\155ng gi\225\187\175a c\195\161c v\195\172 sao. C\195\161c lo\225\186\161i v\197\169 kh\195\173 c\225\186\167n thi\225\186\191t \196\145\225\187\131 tham gia \196\145\198\176\225\187\163c mua s\225\186\175m th\195\180ng qua m\225\187\153t n\225\187\129n t\225\186\163ng c\195\179 t\195\170n l\195\160 Simurgh Silhouette. Tr\198\176\225\187\157ng ch\225\186\175n h\195\160ng r\195\160o \196\145\198\176\225\187\163c t\225\186\161o ra trong ch\225\186\191 \196\145\225\187\153 kh\195\180ng chi\225\186\191n \196\145\225\186\165u c\195\179 th\225\187\131 l\195\160 m\225\187\153t ph\198\176\198\161ng th\225\187\169c b\225\186\163o v\225\187\135 ph\198\176\198\161ng ti\225\187\135n trong qu\195\161 tr\195\172nh \196\145i\225\187\129u h\198\176\225\187\155ng. \nNghi\195\170n c\225\187\169u n\195\160y \196\145\195\163 mang l\225\186\161i nh\225\187\175ng th\195\160nh t\225\187\177u to l\225\187\155n trong ti\225\186\191n b\225\187\153 c\195\180ng ngh\225\187\135 android c\225\187\167a ch\195\173nh ch\195\186ng ta. Tuy nhi\195\170n, v\195\172 to\195\160n b\225\187\153 nh\195\179m nghi\195\170n c\225\187\169u \196\145\195\163 \196\145\225\187\147ng \195\189 r\225\186\177ng b\225\187\153 khung n\195\160y c\195\179 nguy c\198\161 b\225\187\139 chi\225\186\191m \196\145o\225\186\161t \196\145\225\187\131 s\225\187\173 d\225\187\165ng nh\198\176 m\225\187\153t v\197\169 kh\195\173 chi\225\186\191n l\198\176\225\187\163c, ch\195\186ng t\195\180i \196\145\195\163 quy\225\186\191t \196\145\225\187\139nh ph\195\162n lo\225\186\161i n\195\179 l\195\160 kh\195\180ng s\225\187\173 d\225\187\165ng \196\145\198\176\225\187\163c v\195\160 ni\195\170m phong n\195\179.\nT\195\180i ch\225\187\137 hy v\225\187\141ng n\195\179 s\225\186\189 \196\145\198\176\225\187\163c s\225\187\173 d\225\187\165ng t\225\187\145t h\198\161n nhi\225\187\129u so v\225\187\155i nh\225\187\175ng g\195\172 t\195\180i t\198\176\225\187\159ng t\198\176\225\187\163ng."
