L52_1 = "Moena l\195\160 m\225\187\153t ng\198\176\225\187\157i ph\225\187\165 n\225\187\175 m\225\186\161nh m\225\186\189 s\225\187\145ng trong m\225\187\153t l\195\160ng ch\195\160i nh\225\187\143. C\195\180 \225\186\165y c\197\169ng l\195\160 b\195\160 m\225\186\185 l\225\186\169m c\225\186\169m c\225\187\167a Mone. B\195\160 \225\186\165y c\195\179 th\225\187\131 l\195\160m b\225\186\165t c\225\187\169 \196\145i\225\187\129u g\195\172 cho ng\195\180i l\195\160ng v\195\160 con g\195\161i c\225\187\167a m\195\172nh. B\195\160 lu\195\180n c\225\186\163m th\225\186\165y h\225\187\145i ti\225\186\191c v\195\172 kh\195\180ng th\225\187\131 mang \196\145\225\186\191n cu\225\187\153c s\225\187\145ng \196\145\225\187\167 \196\145\225\186\167y cho Mone, nh\198\176ng Mone t\225\187\177 h\195\160o v\225\187\129 m\225\186\185 m\195\172nh \196\145\225\186\191n n\225\187\151i c\195\180 \225\186\165y kh\195\180ng quan t\195\162m. \n\nM\225\186\183t kh\195\161c, s\225\186\175c \196\145\225\186\185p tr\225\186\187 trung t\225\187\177 nhi\195\170n c\225\187\167a b\195\160 khi\225\186\191n cho ngay c\225\186\163 nh\225\187\175ng du kh\195\161ch c\225\186\165p cao nh\225\186\165t t\225\187\171 c\195\161c th\195\160nh ph\225\187\145 c\197\169ng c\225\186\163m th\225\186\165y ghen t\225\187\139. B\195\173 quy\225\186\191t l\195\160m \196\145\225\186\185p c\225\187\167a b\195\160 ch\195\173nh l\195\160 kem d\198\176\225\187\161ng t\225\187\171 d\225\187\171a, c\195\180ng th\225\187\169c gia truy\225\187\129n t\225\187\171 bao \196\145\225\187\157i nay. L\195\160 m\225\187\153t c\198\176 d\195\162n theo ch\225\186\191 \196\145\225\187\153 m\225\186\171u h\225\187\135 h\195\160o ph\195\179ng, Moena lu\195\180n vui v\225\186\187 chia s\225\186\187 lo\225\186\161i kem d\198\176\225\187\161ng c\225\187\167a m\195\172nh v\225\187\155i nh\225\187\175ng ng\198\176\225\187\157i kh\195\161c. Ch\225\187\137 ri\195\170ng \196\145i\225\187\129u \196\145\195\179 th\195\180i c\197\169ng \196\145\225\187\167 \196\145\225\187\131 con g\195\161i b\195\160 \225\186\165y t\225\187\177 h\195\160o v\225\187\129 b\195\160 \225\186\165y r\225\187\147i nh\225\187\137?"
