L47_1 = "Tr\225\186\173n chi\225\186\191n v\225\187\155i ti\225\187\131u \196\145\225\187\153i Ph\195\178ng Th\225\187\167 c\225\187\167a k\225\186\187 th\195\185. \n-Ph\225\186\163i th\195\160nh l\225\186\173p ti\225\187\131u \196\145\225\187\153i Ph\195\178ng Th\225\187\167 \196\145\225\187\131 tham gia Tr\225\186\173n Chi\225\186\191n Chi\225\186\191n L\198\176\225\187\163c.\nC\195\161c th\195\180ng s\225\187\145 b\225\187\149 sung t\225\187\171 trang b\225\187\139, th\196\131ng c\225\186\165p v\195\160 t\196\131ng c\198\176\225\187\157ng s\225\186\189 \196\145\198\176\225\187\163c \195\161p d\225\187\165ng m\225\187\153t ph\225\186\167n.\nGi\195\160nh l\225\186\165y m\225\187\153t s\225\187\145 \196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng \196\145\225\187\131 l\195\170n tr\225\186\173n \196\145\225\186\165u cao h\198\161n.\n-Chi\225\186\191n th\225\186\175ng li\195\170n ti\225\186\191p nhi\225\187\129u Tr\225\186\173n Chi\225\186\191n Chi\225\186\191n L\198\176\225\187\163c \196\145\225\187\131 nh\225\186\173n th\198\176\225\187\159ng chi\225\186\191n th\225\186\175ng li\195\170n ti\225\186\191p.\n-Trong c\195\161c tr\225\186\173n \196\145\225\186\165u cao h\198\161n, c\195\179 th\225\187\131 b\225\187\139 gi\195\161ng c\225\186\165p m\195\160 kh\195\180ng c\195\179 c\225\186\163nh b\195\161o tr\198\176\225\187\155c n\225\186\191u \196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng th\225\186\165p h\198\161n m\225\187\169c c\225\186\167n thi\225\186\191t.\n-\196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng s\225\186\189 b\225\187\139 tr\225\187\171 n\225\186\191u kh\195\180ng th\225\187\131 b\225\186\163o v\225\187\135 \196\145\198\176\225\187\163c \196\145i\225\187\131m s\225\187\145 n\195\160y, nh\198\176ng s\225\186\189 kh\195\180ng ti\225\186\191p t\225\187\165c b\225\187\139 tr\225\187\171 sau khi gi\225\186\163m xu\225\187\145ng m\225\187\153t s\225\187\145 \196\145i\225\187\131m nh\225\186\165t \196\145\225\187\139nh.\n-C\195\179 th\225\187\131 ki\225\186\191m \196\144i\225\187\131m Chi\225\186\191n Th\225\186\175ng v\225\187\155i Tr\225\186\173n Chi\225\186\191n NPC cho \196\145\225\186\191n m\225\187\153t Tr\225\186\173n \196\144\225\186\165u nh\225\186\165t \196\145\225\187\139nh.\n-C\195\179 th\225\187\131 th\225\187\177c hi\225\187\135n Tr\225\186\173n Chi\225\186\191n B\195\161o Th\195\185 \196\145\225\187\145i v\225\187\155i k\225\186\187 th\195\185 \196\145\195\163 \196\145\195\161nh b\225\186\161i Ti\225\187\131u \196\144\225\187\153i Ph\195\178ng Th\225\187\167 c\225\187\167a m\195\172nh."
