L26_1 = "Gremory l\195\160 L\195\173nh H\225\187\151 Tr\225\187\163 truy\225\187\129n \196\145i n\196\131ng l\198\176\225\187\163ng t\195\172nh y\195\170u khi c\195\180 ra ngo\195\160i chi\225\186\191n \196\145\225\186\165u, khi\225\186\191n k\225\186\187 th\195\185 bu\225\187\147n ng\225\187\167 ngay l\225\186\173p t\225\187\169c .\n\nC\195\180 \225\186\165y \196\145\195\163 t\225\187\171ng l\195\160 m\225\187\153t nh\195\160 ti\195\170n tri huy\225\187\129n tho\225\186\161i, c\195\179 th\225\187\131 gi\195\186p thay \196\145\225\187\149i cu\225\187\153c \196\145\225\187\157i con ng\198\176\225\187\157i trong th\225\186\191 gi\225\187\155i ng\225\186\167m, nh\198\176ng c\195\180 \225\186\165y \196\145\195\163 r\225\187\157i b\225\187\143 cu\225\187\153c s\225\187\145ng \196\145\195\179 v\195\160 m\225\187\159 m\225\187\153t qu\195\161n bar nh\225\187\143, t\198\176 v\225\186\165n cho nh\225\187\175ng kh\195\161ch quen v\225\187\129 c\195\161c v\225\186\165n \196\145\225\187\129 trong m\225\187\145i quan h\225\187\135 t\195\172nh c\225\186\163m c\225\187\167a h\225\187\141.\n\nC\195\180 \225\186\165y lu\195\180n r\198\176\225\187\163u m\225\186\161nh v\195\160 th\195\173ch \196\145\225\187\141c truy\225\187\135n tranh l\195\163ng m\225\186\161n, v\195\160 kh\195\180ng quan t\195\162m nhi\225\187\129u \196\145\225\186\191n th\225\186\191 gi\225\187\155i b\195\170n ngo\195\160i qu\195\161n bar c\225\187\167a m\195\172nh. C\195\180 th\195\173ch c\225\186\163 vi\225\187\135c \196\145\225\187\141c v\225\186\173n may trong t\195\172nh y\195\170u c\225\187\167a kh\195\161ch h\195\160ng m\225\187\155i v\195\160 l\195\160m cho nh\225\187\175ng k\225\186\187 th\195\185 c\225\187\167a nhau y\195\170u l\225\186\171n nhau. Tuy nhi\195\170n, c\195\180 \225\186\165y kh\195\180ng tr\195\162n tr\225\187\141ng t\225\186\165t c\225\186\163 c\195\161c lo\225\186\161i t\195\172nh y\195\170u. V\195\173 d\225\187\165: s\225\187\177 b\225\187\153i t\195\173n c\195\179 th\225\187\131 khi\225\186\191n c\195\180 \225\186\165y ph\225\186\171n n\225\187\153 \196\145\225\186\191n m\225\187\169c l\225\186\173t tung qu\195\161n bar c\225\187\167a m\195\172nh l\195\170n \196\145\225\187\131 t\195\172m th\225\187\167 ph\225\186\161m b\195\170n trong."
