L20_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ALPHA_C_CHESS"
L21_1 = "Con B\225\186\161c l\195\160 m\225\187\153t l\195\173nh h\225\187\151 tr\225\187\163 chuy\195\170n g\195\162y suy y\225\186\191u, c\195\179 th\225\187\131 l\195\160m suy y\225\186\191u k\225\186\187 th\195\185 c\225\187\167a m\195\172nh v\225\187\155i c\198\161 h\225\187\153i g\195\162y ra hi\225\187\135u \225\187\169ng suy y\225\186\191u m\225\186\161nh h\198\161n.\nCon B\225\186\161c n\225\187\149i ti\225\186\191ng t\225\186\161i S\195\178ng B\225\186\161c Ng\225\186\167m v\195\172 l\195\160 k\225\186\187 d\195\161m \196\145\195\161nh li\225\187\129u m\225\187\141i th\225\187\169 \196\145\225\187\131 th\225\186\175ng c\198\176\225\187\163c. C\195\179 l\225\186\189 v\195\172 v\225\186\173y m\195\160 nhi\225\187\129u ng\198\176\225\187\157i \196\145\225\186\191n xem c\195\180 \225\186\165y ch\198\161i. M\225\187\141i ng\198\176\225\187\157i t\225\187\165 t\225\186\173p xung quanh \196\145\225\187\131 bi\225\186\191t xem c\195\180 \225\186\165y s\225\186\189 \196\145\225\186\183t c\198\176\225\187\163c bao nhi\195\170u ho\225\186\183c cu\225\187\145i c\195\185ng c\195\180 ta s\225\186\189 thua ai.\n\nKh\195\180ng ai bi\225\186\191t Con B\225\186\161c l\195\160 ai. Ch\225\187\137 c\195\179 nh\225\187\175ng tin \196\145\225\187\147n th\225\186\165t thi\225\187\135t xung quanh v\195\172 c\195\180 ta c\195\179 v\225\186\187 l\195\160 ng\198\176\225\187\157i gi\195\160u c\195\179 v\195\160 c\195\180 ta b\225\186\175t \196\145\225\186\167u t\225\187\155i s\195\178ng b\225\186\161c sau c\195\161i ch\225\186\191t c\225\187\167a Ch\225\187\167 T\225\187\139ch Alphatrix, th\225\186\173m ch\195\173 m\225\187\153t s\225\187\145 ng\198\176\225\187\157i c\195\178n cho r\225\186\177ng c\195\180 ta l\195\160 th\195\160nh vi\195\170n c\225\187\167a gia t\225\187\153c Shin, t\225\187\169c l\195\160 ng\198\176\225\187\157i \196\145\195\163 b\225\187\139 \196\145\225\186\169y ra trong c\195\161c cu\225\187\153c tranh ch\225\186\165p quy\225\187\129n qu\225\186\163n l\195\189 \225\187\159 Alphatrix.\n\nTheo c\195\161c b\195\161o c\195\161o, g\225\186\167n \196\145\195\162y c\195\180 \225\186\165y \196\145\195\163 c\195\179 m\225\187\153t b\195\173 danh, Cecilia Shin, v\195\160 th\195\160nh l\225\186\173p m\225\187\153t c\195\180ng ty gi\225\186\165y c\195\179 t\195\170n Betatrix Company. Kh\195\180ng r\195\181 l\195\160 t\225\187\177 m\195\172nh l\225\186\173p c\195\180ng ty hay c\195\179 ng\198\176\225\187\157i \196\145\225\187\169ng sau c\195\180 \225\186\165y. Tuy nhi\195\170n, ch\225\186\175c ch\225\186\175n \196\145\195\179 l\195\160 b\198\176\225\187\155c \196\145i m\225\187\159 m\195\160n \196\145\225\187\131 gi\195\160nh chi\225\186\191n th\225\186\175ng trong canh b\225\186\161c c\225\187\167a ch\195\173nh cu\225\187\153c \196\145\225\187\157i c\195\180 ta."
