L5_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SECURITY_C_SERGEANT"
L6_1 = "Chris l\195\160 m\225\187\153t L\195\173nh C\198\161 \196\144\225\187\153ng h\225\187\151 tr\225\187\163 \196\145\225\186\163m b\225\186\163o kh\225\186\163 n\196\131ng s\225\187\145ng s\195\179t b\225\186\177ng vi\225\187\135c gi\225\187\175 kho\225\186\163ng c\195\161ch gi\225\187\175a b\225\186\163n th\195\162n v\195\160 k\225\186\187 th\195\185. K\225\187\185 N\196\131ng T\225\187\145i Th\198\176\225\187\163ng c\225\187\167a c\195\180 \225\186\165y g\195\162y s\195\161t th\198\176\198\161ng b\225\186\165t th\198\176\225\187\157ng cho k\225\186\187 th\195\185 trong ph\225\186\161m vi v\195\160 kh\195\180i ph\225\187\165c chi ph\195\173.\n\nTrung S\196\169 Christina Brecht l\195\160 ng\198\176\225\187\157i nh\225\186\173n \196\145\198\176\225\187\163c Hu\195\162n Ch\198\176\198\161ng Danh d\225\187\177 k\225\187\131 t\225\187\171 khi Gronia \196\145\198\176\225\187\163c l\225\186\173p ra. M\225\186\183c d\195\185 c\195\180 \225\186\165y ch\198\176a bao gi\225\187\157 \196\145\198\176\225\187\163c \196\145\195\160o t\225\186\161o b\195\160i b\225\186\163n nh\198\176 m\225\187\153t l\195\173nh ngh\196\169a v\225\187\165 tr\198\176\225\187\155c khi ra ti\225\187\129n tuy\225\186\191n, c\195\180 \225\186\165y \196\145\195\163 tr\225\187\159 v\225\187\129 l\195\160nh l\225\186\183n sau nh\225\187\175ng tr\225\186\173n chi\225\186\191n kinh ho\195\160ng nh\225\186\165t, khi\225\186\191n c\225\186\165p tr\195\170n c\225\187\167a c\195\180 \225\186\165y c\197\169ng ph\225\186\163i kinh ng\225\186\161c. M\225\187\153t s\225\187\145 s\196\169 quan c\225\186\165p cao \196\145\195\163 \196\145\198\176\225\187\163c c\195\180 \225\186\165y gi\225\186\163i c\225\187\169u, \196\145\225\186\183c bi\225\187\135t l\195\160 trong Tr\225\186\173n Chi\225\186\191n M\195\185a Xu\195\162n, n\198\161i \196\145\198\176\225\187\163c coi l\195\160 \195\161c m\225\187\153ng \196\145\225\187\145i v\225\187\155i qu\195\162n \196\145\225\187\153i ch\195\173nh ph\225\187\167.\n\nCh\195\17