L32_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_HB_GAEUN_RA"
L33_1 = "Gaeun c\195\179 l\225\186\189 \196\145\195\163 b\225\186\175t \196\145\225\186\167u ph\195\161t s\195\179ng v\195\172 mong mu\225\187\145n g\225\186\183p \196\145\198\176\225\187\163c ai \196\145\195\179 \196\145\225\186\183c bi\225\187\135t. Tuy nhi\195\170n, Gaeun c\225\187\167a HRT Berry d\225\186\167n d\225\186\167n \196\145\195\163 b\225\187\153c l\225\187\153 n\196\131ng khi\225\186\191u l\195\160m tr\198\176\225\187\159ng nh\195\179m th\195\180ng qua nh\225\187\175ng bu\225\187\149i ph\195\161t s\195\179ng c\225\187\167a m\195\172nh.\n\nC\195\180 \225\186\165y \196\145\195\163 g\195\162y d\225\187\177ng \196\145\198\176\225\187\163c uy t\195\173n \196\145\225\187\131 khi\225\186\191n c\195\161c th\195\160nh vi\195\170n c\195\179 t\195\173nh c\195\161ch m\225\186\161nh m\225\186\189 trong nh\195\179m ph\225\186\163i tin ph\225\187\165c, v\195\173 d\225\187\165 nh\198\176 s\225\187\177 t\225\187\177 tin th\195\161i qu\195\161 c\225\187\167a Lumi, c\225\187\173 ch\225\187\137 b\225\187\151 b\195\163 c\225\187\167a Bomi v\195\160 kinh nghi\225\187\135m live stream d\195\160y d\225\186\161n c\225\187\167a Miya.\n\nNgay c\225\186\163 khi c\195\180 \225\186\165y kh\195\180ng ph\225\186\163i l\195\160 trung t\195\162m c\225\187\167a nh\195\179m, kh\225\186\163 n\196\131ng l\195\160m th\225\187\167 l\196\169nh c\225\187\167a Gaeun v\225\186\171n gi\195\186p ph\195\161t huy s\225\187\159 tr\198\176\225\187\157ng t\225\187\145t nh\225\186\165t c\225\187\167a t\225\187\171ng th\195\160nh vi\195\170n, c\225\186\163 khi ph\195\161t s\195\179ng v\195\160 khi tr\195\170n s\195\162n kh\225\186\165u.\nK\225\186\191t qu\225\186\163 l\195\160, c\195\161c c\195\180ng ty gi\225\186\163i tr\195\173 l\225\187\155n \196\145\195\163 c\195\180ng nh\225\186\173n HRT Berry l\195\160 nh\195\179m nh\225\186\161c th\225\186\167n t\198\176\225\187\163ng m\225\187\155i n\225\187\149i.\n\nGaeun hi\225\187\135n r\225\186\165t \196\145\198\176\225\187\163c ch\195\186 \195\189 v\195\160 c\195\179 th\225\187\131 t\198\176\198\161i c\198\176\225\187\157i tho\225\186\163i m\195\161i v\225\187\155i ng\198\176\225\187\157i h\195\162m m\225\187\153, cho d\195\185 th\225\187\177c t\225\186\191 c\195\180 \225\186\165y v\225\186\171n kh\195\180ng gi\225\187\143i b\225\186\177ng c\195\161c th\195\160nh vi\195\170n kh\195\161c v\225\187\129 kho\225\186\163n nh\225\186\163y m\195\186a v\195\160 ca h\195\161t.\n\nB\225\187\159i b\195\162y gi\225\187\157 c\195\180 \225\186\165y hi\225\187\131u r\225\186\177ng ng\198\176\225\187\157i Th\225\186\167y, ng\198\176\225\187\157i h\195\162m m\225\187\153 l\225\187\155n nh\225\186\165t c\225\187\167a m\195\172nh s\225\186\189 lu\195\180n \225\187\159 \196\145\195\162u \196\145\195\179 \225\187\167ng h\225\187\153 c\195\180 \225\186\165y."
