L37_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_ESPR_PILE_RA"
L38_1 = "Nhi\225\187\129u th\195\160nh vi\195\170n c\225\187\167a H\225\187\153i b\225\187\139 \195\161m \225\186\163nh b\225\187\159i m\225\187\153t \196\145i\225\187\129u g\195\172 \196\145\195\179. Trong ph\198\176\198\161ng di\225\187\135n \196\145\195\179, Rivet ph\195\185 h\225\187\163p v\225\187\155i h\225\187\141 m\225\187\153t c\195\161ch \196\145\195\161ng kinh ng\225\186\161c. Thay v\195\172 tr\225\187\159 n\195\170n t\225\187\177 m\195\163n, c\195\180 \225\186\165y s\225\186\189 tung m\195\172nh v\195\160o nguy hi\225\187\131m \196\145\225\187\131 tr\225\186\163i nghi\225\187\135m c\225\186\163m gi\195\161c v\225\187\153i v\195\160ng, v\195\160 lu\195\180n theo \196\145u\225\187\149i c\225\186\163m gi\195\161c h\225\187\147i h\225\187\153p ti\225\186\191p theo. \n\nLai l\225\187\139ch c\225\187\167a Rivet v\225\186\171n c\195\178n l\195\160 b\195\173 \225\186\169n k\225\187\131 c\225\186\163 sau khi gia nh\225\186\173p H\225\187\153i. Nh\225\187\175ng ngh\225\187\139ch c\225\186\163nh trong cu\225\187\153c s\225\187\145ng c\225\187\167a c\195\180 \225\186\165y qu\195\161 l\225\187\155n \196\145\225\186\191n n\225\187\151i ch\195\186ng kh\195\180ng \225\186\163nh h\198\176\225\187\159ng \196\145\225\186\191n nh\225\187\175ng \196\145\195\161nh gi\195\161 c\225\187\167a c\195\180. B\225\187\153 ph\225\186\173n Kinh doanh \196\145\195\163 h\225\186\191t s\225\187\169c khuy\195\170n r\225\186\177ng n\195\170n t\198\176\225\187\155c b\225\187\143 Trang B\225\187\139 \196\144\225\186\183c Bi\225\187\135t c\225\187\167a c\195\180 \225\186\165y, nh\198\176ng cu\225\187\145i c\195\185ng \196\145\195\163 b\225\187\139 Ch\225\187\167 T\225\187\139ch ph\225\187\167 quy\225\186\191t. \n\nB\225\187\159i v\195\172 c\195\161 nh\195\162n b\195\173 \225\186\169n n\195\160y kh\195\180ng ph\225\186\163i l\195\160 m\225\187\145i \196\145e d\225\187\141a ti\225\187\129m \225\186\169n \196\145\225\187\145i v\225\187\155i H\225\187\153i, m\195\160 l\195\160 m\225\187\153t ch\225\187\167 \196\145\225\187\129 nghi\195\170n c\225\187\169u h\225\186\165p d\225\186\171n."
