L2_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REAPER_C_ARMS"
L3_1 = "Lenore l\195\160 gi\195\161m \196\145\225\187\145c \196\145i\225\187\129u h\195\160nh thu\225\187\153c \196\144\225\187\153i T\195\161c Chi\225\186\191n c\225\187\167a Li\195\170n Minh Ph\195\173a B\225\186\175c. C\195\180 \196\145\195\163 m\225\186\161o hi\225\187\131m t\195\172nh nguy\225\187\135n l\195\160m \196\145\225\187\145i t\198\176\225\187\163ng th\225\187\173 nghi\225\187\135m trong d\225\187\177 \195\161n Oracle m\195\160 cha c\195\180 \196\145ang nghi\195\170n c\225\187\169u v\195\160 l\195\160 \196\145\225\187\145i t\198\176\225\187\163ng duy nh\225\186\165t c\195\179 \196\145\198\176\225\187\163c k\225\186\191t qu\225\186\163 th\195\160nh c\195\180ng. \n\nC\195\180 \225\186\165y c\195\179 th\225\187\131 nh\195\172n th\225\186\165y t\198\176\198\161ng lai m\195\172nh mong mu\225\187\145n th\195\180ng qua th\195\173 nghi\225\187\135m v\195\160 c\195\179 nh\225\187\175ng \196\145\195\179ng g\195\179p \196\145\195\161ng k\225\187\131 cho Li\195\170n Minh Ph\195\173a B\225\186\175c b\225\186\177ng c\195\161ch lo\225\186\161i b\225\187\143 k\225\186\187 ph\225\186\163n b\225\187\153i b\195\170n trong. \196\144\225\187\145i v\225\187\155i Lenore v\225\187\155i kh\225\186\163 n\196\131ng nh\195\172n tr\198\176\225\187\155c t\198\176\198\161ng lai m\195\160 n\195\179i, kh\195\180ng c\195\179 th\225\187\169 g\225\187\141i l\195\160 th\225\186\165t b\225\186\161i, n\195\170n c\195\161i t\195\180i c\225\187\167a c\195\180 \225\186\165y ng\195\160y c\195\160ng l\225\187\155n h\198\161n. D\225\186\167n d\225\186\167n, c\195\180 kh\195\180ng c\195\178n h\225\187\169ng th\195\186 v\225\187\155i k\225\186\191t qu\225\186\163 hi\225\187\131n nhi\195\170n c\225\187\167a k\225\186\191 ho\225\186\161ch c\225\187\167a m\195\172nh. C\195\180 b\225\186\175t \196\145\225\186\167u t\195\172m ki\225\186\191m nh\225\187\175ng \196\145i\225\187\129u m\225\187\155i m\225\186\187, ph\225\186\165n kh\195\173ch v\195\160 c\225\186\163m th\225\186\165y \196\145\198\176\225\187\163c s\225\187\177 vui s\198\176\225\187\155ng khi d\225\186\171m \196\145\225\186\161p l\195\170n nh\225\187\175ng k\225\186\187 th\195\185 c\195\179 ni\225\187\129m tin m\195\163nh li\225\187\135t. Nhi\225\187\135m v\225\187\165 \196\145\198\176\225\187\163c ho\195\160n th\195\160nh v\225\187\145n d\196\169 \196\145\225\187\131 ph\225\187\165c v\225\187\165 \196\145\225\186\165t n\198\176\225\187\155c, nh\198\176ng \225\187\159 \196\145\195\162u \196\145\195\179, l\225\186\161i bi\225\186\191n th\195\160nh nh\225\187\175ng t\225\187\153i \195\161c bu\195\180ng th\225\186\163 t\225\186\173p trung mang l\225\186\161i s\225\187\177 h\225\187\167y ho\225\186\161i cho ng\198\176\225\187\157i kh\195\161c."
