L37_1 = "SI_COLLECTION_UNIT_INTRO_OPR_SYSOP"
L38_1 = "Ch\225\187\167 t\225\187\139ch c\225\187\167a H\225\187\153i \196\144\225\187\147ng H\225\186\175c \195\129m, m\225\187\153t li\195\170n minh c\225\187\167a nh\225\187\175ng k\225\186\187 th\225\187\145ng tr\225\187\139 th\225\186\191 gi\225\187\155i ng\225\186\167m. M\225\186\183c d\195\185 c\195\179 v\195\160i nh\195\162n v\225\186\173t ph\225\186\163n di\225\187\135n kh\195\169t ti\225\186\191ng ph\225\187\165c v\225\187\165 d\198\176\225\187\155i quy\225\187\129n, danh t\195\173nh c\225\187\167a h\225\186\175n ta v\225\186\171n l\195\160 m\225\187\153t b\195\173 \225\186\169n, d\225\186\171n \196\145\225\186\191n v\195\180 s\225\187\145 tin \196\145\225\187\147n.\n\nM\225\187\153t s\225\187\145 ng\198\176\225\187\157i coi H\225\187\153i \196\145\225\187\147ng l\195\160 m\225\187\153t huy\225\187\129n tho\225\186\161i \196\145\195\180 th\225\187\139, v\195\172 h\225\187\141 kh\195\180ng th\225\187\131 hi\225\187\131u \196\145\198\176\225\187\163c sao nh\225\187\175ng t\195\170n t\225\187\153i ph\225\186\161m ng\225\187\151 ng\198\176\225\187\163c n\195\160y ch\225\187\139u ph\225\187\165c v\225\187\165 d\198\176\225\187\155i m\225\187\153t th\225\187\167 l\196\169nh duy nh\225\186\165t. Tuy nhi\195\170n, Sysop th\225\187\177c s\225\187\177 t\225\187\147n t\225\186\161i. Th\225\187\177c t\225\186\191 vi\225\187\135c h\225\186\175n ta kh\195\180ng c\225\187\145 qu\225\186\163n l\195\189 ho\225\186\183c ki\225\187\131m so\195\161t nh\225\187\175ng t\195\170n t\225\187\153i ph\225\186\161m n\195\160y, ch\225\187\137 l\195\160 do suy \196\145o\195\161n ng\198\176\225\187\157i ta kh\195\180ng ng\225\187\157 t\225\187\155i. h\225\186\175n ta ch\225\187\137 \196\145\198\161n thu\225\186\167n t\195\173nh to\195\161n quan h\225\187\135 nh\195\162n qu\225\186\163 v\195\160 \196\145i\225\187\129u ch\225\187\137nh qu\195\161 tr\195\172nh \196\145\225\187\131 \196\145\225\186\161t \196\145\198\176\225\187\163c k\225\186\191t qu\225\186\163 mong mu\225\187\145n.\n\nDo \196\145\195\179, kh\195\180ng ai qu\225\186\163n l\195\189 H\225\187\153i \196\144\225\187\147ng H\225\186\175c \195\129m. Ch\225\187\137 nh\225\187\175ng ng\198\176\225\187\157i \196\145\225\186\167y tham v\225\187\141ng v\195\160 c\225\187\145 v\225\186\165n c\225\187\167a h\225\187\141 m\225\187\155i t\225\186\161o n\195\170n nh\195\179m n\195\160y."
