L32_1 = "Ciel l\195\160 m\225\187\153t s\195\161t th\225\187\167 v\195\160 l\195\160 l\195\173nh t\225\186\165n c\195\180ng, \196\145\195\161nh tuy\225\186\191n sau b\225\186\177ng c\195\161ch vung ng\225\187\141n gi\195\161o Bakuya v\195\160 l\195\160m ch\225\187\135ch h\198\176\225\187\155ng \196\145\195\178n t\225\186\165n c\195\180ng c\225\187\167a k\225\186\187 th\195\185.\n\nM\225\186\183c d\195\185 c\195\179 kh\195\161t v\225\187\141ng tr\225\187\159 th\195\160nh m\225\187\153t h\225\187\141c sinh g\198\176\198\161ng m\225\186\171u, nh\198\176ng c\195\180 l\225\186\161i l\195\160 m\225\187\153t c\195\180 g\195\161i s\225\187\145ng v\225\187\129 \196\145\195\170m hi\225\186\191m khi t\225\187\137nh t\195\161o trong l\225\187\155p. C\195\180 kh\195\180ng c\195\179 k\225\187\185 n\196\131ng x\195\163 h\225\187\153i khi m\225\187\155i v\195\160o H\225\187\141c vi\225\187\135n; c\195\178n kh\195\180ng bi\225\186\191t t\225\187\171 \"b\225\186\161n\" ngh\196\169a l\195\160 g\195\172. Tuy nhi\195\170n, gi\225\187\157 \196\145\195\162y v\225\187\155i s\225\187\177 gi\195\186p \196\145\225\187\161 c\225\187\167a c\195\161c b\225\186\161n, c\195\180 \196\145ang d\225\186\167n d\225\186\167n h\225\187\141c cu\225\187\153c s\225\187\145ng h\195\160ng ng\195\160y.\n\nC\195\180 l\195\160 th\225\187\167 l\196\169nh c\225\187\167a m\225\187\153t gi\195\161o ph\195\161i s\195\161t th\225\187\167 \196\145i\225\187\129u h\195\160nh m\225\187\153t th\195\160nh ph\225\187\145, c\197\169ng kh\195\180ng h\225\187\129 c\225\187\145 g\225\186\175ng che gi\225\186\165u s\225\187\177 th\225\186\173t n\195\160y. M\225\187\153t v\195\160i h\225\187\141c sinh l\195\186c \196\145\225\186\167u c\195\179 v\225\186\187 r\225\186\165t nghi\195\170m tr\225\187\141ng. Nh\198\176ng b\225\187\159i c\195\180 \225\186\165y ng\195\162y th\198\161 v\195\160 kh\195\180ng c\195\179 kh\225\186\163 n\196\131ng t\225\187\171 ch\225\187\145i gi\195\186p \196\145\225\187\161 g\195\172, n\195\170n ch\225\186\179ng ai tin c\195\180 l\195\160 m\225\187\153t s\195\161t th\225\187\167 th\225\187\177c s\225\187\177.\n\nN\225\186\191u b\225\186\161n nh\225\186\173n th\225\186\165y Ciel c\195\179 v\225\186\187 c\195\161u k\225\187\137nh v\195\160o ban ng\195\160y th\195\172 \196\145\225\187\171ng lo. Ch\225\187\137 \196\145\198\161n gi\225\186\163n l\195\160 c\195\180 \225\186\165y \196\145ang c\225\187\145 nh\195\172n r\195\181 v\225\186\173t th\225\187\131 tr\198\176\225\187\155c m\225\186\183t m\195\172nh h\198\161n th\195\180i."
