L49_1 = "C\195\180 t\225\187\171ng l\195\160 h\225\187\153 v\225\187\135 c\225\187\167a Elysion, m\225\187\153t hi\225\187\135p s\196\169 v\195\160 l\195\160 \196\145\225\187\169c tin m\195\160 m\225\187\141i ng\198\176\225\187\157i \196\145\225\187\129u c\225\187\145ng hi\225\186\191n \196\145i theo. M\225\187\141i ng\198\176\225\187\157i \196\145\225\187\129u t\195\180n th\225\187\157 c\195\180, v\195\160 \196\145\225\187\169c tin \196\145\195\179 \196\145\195\163 tr\225\187\159 th\195\160nh s\225\187\169c m\225\186\161nh \196\145\225\187\149i l\225\186\161i b\225\186\163o v\225\187\135 m\225\187\141i ng\198\176\225\187\157i.\n\nC\195\180 \196\145\195\163 ti\225\186\191t l\225\187\153 r\225\186\177ng c\195\179 m\225\187\153t ng\195\160y t\225\186\173n th\225\186\191 s\225\186\175p x\225\186\163y ra v\195\160 c\195\185ng v\225\187\155i Elysion Philharmonic, \196\145\195\163 x\195\162y d\225\187\177ng C\225\187\149ng M\225\186\183t tr\225\187\157i \196\145\225\187\131 \196\144\225\186\169y L\195\185i b\225\187\135nh d\225\187\139ch b\195\179ng t\225\187\145i v\195\160 ng\196\131n ch\225\186\183n n\195\179. Ecclesia c\195\179 v\195\160i d\195\160n nh\225\186\161c v\195\160 nh\225\186\161c tr\198\176\225\187\159ng d\198\176\225\187\155i quy\225\187\129n. Tuy nhi\195\170n, c\195\180 \225\186\165y ch\198\176a bao gi\225\187\157 t\225\187\177 ch\198\161i c\225\186\163. Nh\225\186\161c c\225\187\165 l\195\160 m\225\187\153t c\195\161ch th\225\187\131 hi\225\187\135n t\195\162m h\225\187\147n v\195\160 tr\195\161ch nhi\225\187\135m c\225\187\167a c\195\180 l\195\160 l\225\186\175ng nghe v\195\160 th\225\186\165u hi\225\187\131u tr\195\161i tim c\225\187\167a m\225\187\141i ng\198\176\225\187\157i.\n\nC\195\180 th\195\173ch \195\162m nh\225\186\161c; tuy nhi\195\170n, c\195\180 \225\186\165y ch\198\176a bao gi\225\187\157 ch\198\161i cho ch\195\173nh m\195\172nh. C\195\180 s\225\187\145ng ch\225\187\137 \196\145\225\187\131 l\225\186\175ng nghe c\225\186\163m x\195\186c c\225\187\167a ng\198\176\225\187\157i kh\195\161c. T\225\187\171 \196\145\195\179 tr\225\187\159 \196\145i, m\225\187\141i ng\198\176\225\187\157i b\225\186\175t \196\145\225\186\167u g\225\187\141i c\195\180 l\195\160 S\225\187\177 Im L\225\186\183ng V\196\169 \196\144\225\186\161i."
