L34_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_JAPAN_C_CRAFTER"
L35_1 = "Nao l\195\160 h\225\186\173u du\225\187\135 c\225\187\167a m\225\187\153t v\225\187\139 th\225\186\167n c\225\187\149 x\198\176a. C\195\180 l\195\160 m\225\187\153t th\225\187\163 r\195\168n nh\195\186t nh\195\161t, kh\195\180ng ch\225\187\139u ra kh\225\187\143i l\195\178 r\195\168n v\195\172 kh\195\180ng th\195\173ch t\198\176\198\161ng t\195\161c v\225\187\155i ng\198\176\225\187\157i kh\195\161c.\n\nS\225\187\169c m\225\186\161nh c\225\187\167a cha c\195\180 t\225\187\171ng n\195\162ng \196\145\225\187\161 th\225\186\191 gi\225\187\155i, nh\198\176ng khi n\195\179 s\225\187\165p \196\145\225\187\149, th\225\186\191 gi\225\187\155i c\225\187\167a c\195\180 ch\195\172m s\195\162u trong ng\225\187\141n l\225\187\173a kh\195\180ng bao gi\225\187\157 t\225\186\175t. \196\144\195\179 l\195\160 l\195\186c c\195\180 b\225\186\165t ng\225\187\157 ph\225\186\163i g\195\161nh v\195\161c tr\195\161ch nhi\225\187\135m d\225\186\171n d\225\186\175t nh\225\187\175ng ng\198\176\225\187\157i s\225\187\145ng s\195\179t. \196\144\195\179 l\195\160 c\198\161 h\225\187\153i duy nh\225\186\165t khi\225\186\191n c\195\180 ch\225\186\161m tr\195\161n v\225\187\155i C\225\187\165c Qu\225\186\163n L\195\189. Cu\225\187\153c g\225\186\183p g\225\187\161 \196\145\195\163 gi\195\186p c\195\180 tr\198\176\225\187\159ng th\195\160nh v\195\160 l\195\163nh \196\145\225\186\161o ng\198\176\225\187\157i d\195\162n c\225\187\167a m\195\172nh m\225\187\153t c\195\161ch \196\145\195\186ng \196\145\225\186\175n, \196\145\225\187\147ng th\225\187\157i c\197\169ng gi\195\186p c\195\180 t\225\187\171 b\225\187\143 c\195\161i t\195\170n \196\145\225\186\167y \195\180 nh\225\187\165c \"Th\225\186\167n S\225\187\163 C\195\161i ch\225\186\191t\".\n\nK\225\187\131 t\225\187\171 khi C\225\187\165c Qu\225\186\163n L\195\189 C\197\169 s\225\187\165p \196\145\225\187\149, c\195\180 \196\145\195\163 l\195\185i m\225\187\153t b\198\176\225\187\155c kh\225\187\143i ti\225\187\129n tuy\225\186\191n v\195\160 t\195\172m ki\225\186\191m m\225\187\153t c\195\161 nh\195\162n x\225\187\169ng \196\145\195\161ng c\195\179 th\225\187\131 k\225\186\191 th\225\187\171a k\225\187\185 n\196\131ng r\195\168n c\225\187\167a c\195\180 \225\186\165y. Nh\198\176ng, c\195\180 \225\186\165y s\225\186\189 lu\195\180n \196\145\225\186\191n tr\225\187\163 gi\195\186p n\225\186\191u th\225\186\191 gi\225\187\155i g\225\186\183p ph\225\186\163i nguy hi\225\187\131m."
