L26_1 = "<b><color=#4EC2F3>[Ti\225\186\191p S\225\187\169c \196\144\225\187\153i]</color></b>\n<color=#FFCF3B>- Ch\225\187\141n m\225\187\153t trong hai \196\145\225\187\153i \196\145\225\187\131 c\225\187\149 v\197\169 b\225\186\177ng Gi\195\160y.</color>\n<color=#FFCF3B>- N\225\186\191u \196\145\225\187\153i b\225\186\161n ch\225\187\141n chi\225\186\191n th\225\186\175ng, b\225\186\161n c\195\179 th\225\187\131 nh\225\186\173n \196\145\198\176\225\187\163c ph\225\186\167n th\198\176\225\187\159ng theo h\225\187\135 s\225\187\145 ph\225\186\167n th\198\176\225\187\159ng.</color>\n<color=#FFCF3B>- C\195\161c cu\225\187\153c \196\145ua \196\145\198\176\225\187\163c t\225\187\149 ch\225\187\169c m\225\187\153t l\225\186\167n m\225\187\151i ng\195\160y v\195\160 b\225\186\161n s\225\186\189 kh\195\180ng th\225\187\131 tham gia trong th\225\187\157i gian t\225\187\149ng k\225\186\191t.</color>\n\n<b><color=#FFFFFF>[Nhi\225\187\135m V\225\187\165 Cu\225\187\153c \196\144ua]</color></b>\n<color=#F2F2F2>- Ho\195\160n th\195\160nh c\195\161c nhi\225\187\135m v\225\187\165 \196\145\198\176\225\187\163c cung c\225\186\165p \196\145\225\187\131 ki\225\186\191m th\195\170m Gi\195\160y.</color>\n\n<b><color=#FFFFFF>[C\225\187\149 V\197\169]</color></b>\n<color=#F2F2F2>- S\225\187\173 d\225\187\165ng Gi\195\160y \196\145\225\187\131 c\225\187\149 v\197\169 cho \196\145\225\187\153i m\195\160 b\225\186\161n \196\145\195\163 ch\225\187\141n.</color>\n<color=#F2F2F2>-  M\225\187\151i ng\195\160y b\225\186\161n ch\225\187\137 c\195\179 th\225\187\131 ch\225\187\141n m\225\187\153t \196\145\225\187\153i.</color>\n<color=#F2F2F2>- M\225\187\151i ng\195\160y b\225\186\161n c\195\179 th\225\187\131 s\225\187\173 d\225\187\165ng t\225\187\145i \196\145a 500 Gi\195\160y.</color>\n\n<b><color=#FFFFFF>[Ph\225\186\167n Th\198\176\225\187\159ng]</color></b>\n<color=#F2F2F2>- N\225\186\191u \196\145\225\187\153i b\225\186\161n ch\225\187\141n gi\195\160nh \196\145\198\176\225\187\163c chi\225\186\191n th\225\186\175ng, Gi\195\160y l\195\160m ph\225\186\167n th\198\176\225\187\159ng s\225\186\189 \196\145\198\176\225\187\163c ph\195\161t theo ph\225\186\167n th\198\176\225\187\159ng h\225\187\135 s\225\187\145 nh\195\162n.</color>\n<color=#F2F2F2>- N\225\186\191u \196\145\225\187\153i c\225\187\167a b\225\186\161n thua,  s\225\186\189 b\225\187\139 m\225\186\165t 80% Gi\195\160y d\195\185ng \196\145\225\187\131 c\225\187\149 v\197\169.</color>\n<color=#F2F2F2>- B\225\186\161n c\195\179 th\225\187\131 nh\225\186\173n ph\225\186\167n th\198\176\225\187\159ng cho c\195\161c cu\225\187\153c \196\145ua m\195\172nh \196\145\195\163 tham gia khi cu\225\187\153c \196\145ua ng\195\160y h\195\180m sau b\225\186\175t \196\145\225\186\167u.</color>"
